window.XCTK_DATA.cats = [{"id":"zz","name":"政治理论","desc":"11 套 250 题"},{"id":"cs","name":"常识判断","desc":"6 套 90 题"},{"id":"xf","name":"法律新规","desc":"5 套 100 题"}];
(function(d){d.units.push.apply(d.units,[{"id":"zz-1","cat":"zz","title":"小黑模考五套卷 · 第一套","short":"第一套","sub":"20 题","questions":[{"id":"zz-1q1","n":1,"s":"2026年10月22日，纪念中国工农红军长征胜利90周年大会隆重举行。习近平总书记指出，正是在党的正确路线指引下，红军作战指挥实行了一系列符合实际、机动灵活的战略战术，从而成功突破敌人层层封锁，不断走向新生、走向胜利。历史雄辩地证明，马克思主义基本原理只有同中国具体实际紧密结合，才能解决中国的问题，才能展现出强大生命力。这段材料体现的哲学道理是：\n①物质决定意识，主观必须符合客观，做到一切从实际出发\n②事物发展是前进性与曲折性的统一，在曲折中不断走向胜利\n③矛盾的普遍性与特殊性相互联结，坚持共性与个性具体的历史的统一\n④先进的社会意识可以正确预见社会发展方向，积极推动社会发展","o":["①②③④","①②④","①②","③④"],"a":"A","e":"①符合题意：“红军作战指挥实行了一系列符合实际、机动灵活的战略战术”，强调从中国革命的实际情况出发制定战略战术，体现了物质决定意识，主观必须符合客观，做到一切从实际出发。②符合题意：“成功突破敌人层层封锁，不断走向新生、走向胜利”，红军长征历经艰难险阻，但最终走向胜利，体现了事物发展是前进性与曲折性的统一，在曲折中不断走向胜利。③符合题意：“马克思主义基本原理只有同中国具体实际紧密结合，才能解决中国的问题”，直接体现了矛盾的普遍性与特殊性相互联结，坚持共性与个性具体的历史的统一。④符合题意：“正是在党的正确路线指引下……不断走向胜利”“马克思主义……展现出强大生命力”，党的正确路线、马克思主义作为先进的社会意识，能够正确预见社会发展方向，对社会发展起积极的推动作用。故本题答案为A。"},{"id":"zz-1q2","n":2,"s":"2026年7月1日，庆祝中国共产党成立105周年大会在京举行。习近平总书记指出，我们党清醒认识到打铁必须自身硬，善于以时代发展要求审视自己、以强烈忧患意识警醒自己、以自我革命精神完善自己，高度重视自身建设，坚决清除一切损害党的先进性和纯洁性的因素、清除一切侵蚀党的健康肌体的病毒，在革命性锻造中更加坚强有力。下列选项蕴含的哲学道理和题干一致的是：\n①勇于自我革命，是我们党最鲜明的品格，也是我们党最大的优势\n②江山就是人民，人民就是江山\n③从严治党，关键是要抓住领导干部这个“关键少数”\n④必须以苦练内功来应对外部挑战\n⑤反腐败斗争永远在路上、永远是进行时，必须以愚公移山、精卫填海的精神一抓到底","o":["①②③","①③④⑤","①④","②④⑤"],"a":"C","e":"题干中“打铁必须自身硬”“以自我革命精神完善自己”“高度重视自身建设”，都是在强调事物的变化发展主要是由内因推动的，内因是事物变化发展的根据和根本动力，要着眼于自身、加强自身建设。①符合题意：“勇于自我革命是我们党最鲜明的品格、最大的优势”，即通过党自身的自我革命实现自我完善、自我提高，依靠自身力量解决自身问题，体现了内因是事物变化发展的根据，与题干哲理一致。②不符合题意：“江山就是人民，人民就是江山”强调的是人民群众是历史的创造者，要坚持群众观点和群众路线，与题干哲理不一致。③不符合题意：“抓住领导干部这个‘关键少数’”体现的是在复杂事物中抓主要矛盾、抓重点的哲学道理，与题干哲理不一致。④符合题意：“必须以苦练内功来应对外部挑战”，苦练内功强调的是内因，体现了重视内因、着眼于自身发展的道理，与题干哲理一致。⑤不符合题意：“以愚公移山、精卫填海的精神一抓到底”强调的是发挥主观能动性、重视量的积累、持之以恒的道理，与题干哲理不一致。故本题答案为C。"},{"id":"zz-1q3","n":3,"s":"习近平总书记指出，基础研究是打基础、利长远的事业，既不能急功近利，也不可消极无为，要有“前人栽树、后人乘凉”的境界和担当，有“十年磨一剑”的恒心和毅力。这体现的哲学道理是：\n①量变达到一定程度必然引起质变，量变比质变更重要\n②联系具有普遍性、客观性，人们可以根据自身需要建立新的具体联系\n③价值观对人的行为具有重要的导向作用，要坚持正确的价值判断和价值选择\n④正确发挥主观能动性要以尊重客观规律为前提和基础","o":["①②","②④","③④","①③"],"a":"C","e":"①说法错误：“量变比质变更重要”表述错误。量变与质变二者地位不同、作用不同，但不能比较谁“更重要”，也不存在孰轻孰重的问题。②说法错误：“人们可以根据自身需要建立新的具体联系”说法错误。联系的客观性要求人们只能根据事物固有的联系，通过改变事物的状态、调整原有的联系来建立新的具体联系，而不能“根据自身需要”随意建立。③符合题意：“前人栽树、后人乘凉”的境界和担当、“不能急功近利”的价值取向，直接体现了价值观作为一种社会意识对人的行为具有重要的导向作用，要求人们自觉树立正确的价值观，坚持正确的价值判断和价值选择，把当前利益与长远利益、个人价值与社会价值统一起来。④符合题意：“十年磨一剑”的恒心和毅力是充分发挥主观能动性的表现；“不能急功近利”“打基础、利长远”则要求尊重基础研究周期长、见效慢的客观规律，从实际出发、按规律办事。二者结合体现了正确发挥主观能动性必须以尊重客观规律为前提和基础。故本题答案为C。"},{"id":"zz-1q4","n":4,"s":"“六个必须坚持”是习近平新时代中国特色社会主义思想的世界观和方法论，深刻揭示了这一思想的理论品格和鲜明特质，构成相互联系、内在统一的有机整体。下列对应准确的是：","o":["推进改革发展往往牵一发而动全身——坚持人民至上","既不能刻舟求剑、封闭僵化，也不能照抄照搬、食洋不化——坚持自信自立","为解决人类面临的共同问题作出贡献——坚持问题导向","人民的创造性实践是理论创新的不竭源泉——坚持守正创新"],"a":"B","e":"A项对应错误：推进改革发展往往牵一发而动全身对应坚持系统观念。B项对应正确：“不能照抄照搬、食洋不化”强调了不直接抄国外模式，要立足本国国情，依靠自身力量，体现了坚持自信自立。这句话出自党的二十大报告，习近平总书记指出：“党的百年奋斗成功道路是党领导人民独立自主探索开辟出来的，马克思主义的中国篇章是中国共产党人依靠自身力量实践出来的，贯穿其中的一个基本点就是中国的问题必须从中国基本国情出发，由中国人自己来解答。我们要坚持对马克思主义的坚定信仰、对中国特色社会主义的坚定信念，坚定道路自信、理论自信、制度自信、文化自信，以更加积极的历史担当和创造精神为发展马克思主义作出新的贡献，既不能刻舟求剑、封闭僵化，也不能照抄照搬、食洋不化。”C项对应错误：为解决人类面临的共同问题作出贡献对应坚持胸怀天下。D项对应错误：人民的创造性实践是理论创新的不竭源泉对应坚持人民至上。故本题答案为B。"},{"id":"zz-1q5","n":5,"s":"习近平总书记指出，中国式现代化是我们党领导全国各族人民在长期探索和实践中历经千辛万苦、付出巨大代价取得的重大成果，我们必须倍加珍惜、始终坚持、不断拓展和深化。下列相关说法，正确的有几项？\n①一个国家走向现代化，最重要的是要遵循世界现代化一般规律\n②全体人民共同富裕的现代化，这是中国式现代化的本质特征\n③中国式现代化是人类历史上规模最大的现代化，也是难度最大的现代化\n④中国式现代化走得通、行得稳，是强国建设、民族复兴的唯一正确道路\n⑤中国式现代化，拓展了发展中国家走向现代化的路径选择，为人类对更好社会制度的探索提供了中国方案","o":["1项","2项","3项","4项"],"a":"D","e":"①说法错误：一个国家走向现代化，既要遵循现代化一般规律，更要符合本国实际，具有本国特色。②③④⑤说法正确。故本题答案为D。"},{"id":"zz-1q6","n":6,"s":"2025年12月，第24期《求是》杂志发表习近平总书记重要文章《扩大内需是战略之举》。文章指出，扩大内需既关系经济稳定，也关系经济安全，不是权宜之计，而是战略之举。下列说法正确的是：","o":["当产能总体过剩时，扩大内需可进一步通过扩大规模投资来提高发展速度和边际效用","要增强投资对经济增长的基础作用，更要有效发挥消费对优化供给结构的关键作用","要把扩大内需战略同深化供给侧结构性改革有机结合起来，形成供给牵引需求、需求创造供给的更高水平动态平衡","需求侧管理，重在解决总量性问题，主要是通过调节税收、财政支出、货币信贷等来刺激或抑制需求，进而推动经济增长"],"a":"D","e":"A项说法错误：过去，我国生产能力滞后，因而把工作重点放在扩大投资、提高生产能力上。现在，产能总体过剩，仍一味靠扩大规模投资抬高速度，作用有限且边际效用递减。B项说法错误：在扩大有效投资、发挥投资关键作用的同时，必须更加有效地发挥消费对增长的基础作用。C项说法错误：要把扩大内需战略同深化供给侧结构性改革有机结合起来，形成需求牵引供给、供给创造需求的更高水平动态平衡。D项说法正确：需求侧管理，重在解决总量性问题，注重短期调控，主要是通过调节税收、财政支出、货币信贷等来刺激或抑制需求，进而推动经济增长。供给侧管理，重在解决结构性问题，注重激发经济增长动力，主要通过优化要素配置和调整生产结构来提高供给体系质量和效率，进而推动经济增长。故本题答案为D。"},{"id":"zz-1q7","n":7,"s":"要发挥区域协调发展战略、区域重大战略、主体功能区战略、新型城镇化战略叠加效应，统筹推进区域内战略深化实施和区域间联动发展，优化重大生产力布局，发挥重点区域增长极作用，构建优势互补、高质量发展的区域经济布局和国土空间体系。下列相关举措，说法正确的是：","o":["鼓励东北地区率先推进现代化，加强原创性、颠覆性科技创新，引领建设具有国际竞争力的先进制造业集群和现代服务业高地","支持京津冀、长三角、黄河中游城市群打造世界级城市群，巩固提升动力源作用","促进城市化地区增强经济人口集聚承载能力、农产品主产区提升农业综合生产能力、重点生态功能区改善自然生态系统质量","推进以县城为核心的新型城镇化建设，要把推进农业转移人口市民化作为首要任务"],"a":"C","e":"A项说法错误：推动西部大开发形成新格局，推动东北全面振兴取得新突破，促进中部地区加快崛起，鼓励东部地区加快推进现代化。由此可知，“鼓励东北地区率先推进现代化”说法错误。B项说法错误：巩固提升京津冀、长三角、粤港澳大湾区动力源作用。D项说法错误：推进以人为核心的新型城镇化建设，要分类推进以县城为重要载体的城镇化建设。故本题答案为C。"},{"id":"zz-1q8","n":8,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。党的十八大以来，习近平总书记创造性提出“依规治党”并作出一系列重要论述。下列说法正确的有几项？\n①加强党内法规制度建设是全面从严治党的长远之策、根本之策\n②要增强制度执行力，法规制度的生命力在于监督\n③完善的党内法规体系是中国特色社会主义法治体系的重要内容\n④完善党内法规制度体系，重点是做好顶层设计、查漏补缺、提质增效文章\n⑤必须坚持把宪法作为全党的根本行为规范","o":["2项","3项","4项","5项"],"a":"B","e":"②说法错误：要增强制度执行力，法规制度的生命力在于执行。⑤说法错误：必须坚持把党章作为全党的根本行为规范。①③④说法正确。故本题答案为B。"},{"id":"zz-1q9","n":9,"s":"2026年10月22日，纪念中国工农红军长征胜利90周年大会在京隆重举行。下列属于伟大长征精神的是：\n①把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信念，坚信正义事业必然胜利的精神\n②为了救国救民，不怕任何艰难险阻，不惜付出一切牺牲的精神\n③坚持独立自主、实事求是，一切从实际出发的精神\n④顾全大局、严守纪律、紧密团结的精神\n⑤紧紧依靠人民群众，同人民群众生死相依、患难与共、艰苦奋斗的精神\n⑥开天辟地、敢为人先的首创精神","o":["①②③④⑤","①②③⑤⑥","①③④⑤⑥","②③④⑤⑥"],"a":"A","e":"①②③④⑤均属于伟大长征精神内涵。⑥说法错误：“开天辟地、敢为人先的首创精神”属于红船精神。故本题答案为A。"},{"id":"zz-1q10","n":10,"s":"2026年10月12日至13日，全国卫生与健康大会在京召开。下列相关举措，说法正确的有几项？\n①要增强思想自觉和行动自觉，坚定不移走中国特色卫生与健康发展道路\n②要牢固树立健康优先导向，推进人民健康与经济社会协调发展\n③要坚持从保基本向提品质转变，更好满足人民群众多样化健康需求\n④要坚守基本医疗卫生事业的公益性，夯实全民健康根基\n⑤要深化改革创新和开放合作，持续增强卫生与健康事业发展动力活力","o":["2项","3项","4项","5项"],"a":"C","e":"③说法错误：坚持保基本和提品质并重，更好满足人民群众多样化健康需求。①②④⑤说法正确。故本题答案为C。"},{"id":"zz-1q11","n":11,"s":"2026年10月9日，《中共中央国务院关于发展新质生产力的意见》发布。《意见》指出，要改造提升传统产业、培育壮大新兴产业、前瞻布局未来产业。下列属于“培育壮大新兴产业”相关举措的是：\n①巩固提升矿业、冶金、化工等产业在全球产业分工中的地位和竞争力\n②加快新一代信息技术、新能源、新材料、智能网联新能源汽车等产业发展\n③推动量子科技、氢能和核聚变能、具身智能、第六代移动通信等产业发展\n④在确保安全前提下，推动低空经济、商业航天健康有序发展","o":["①③","①④","②③","②④"],"a":"D","e":"①属于“改造提升传统产业”方面的举措。③属于“前瞻布局未来产业”方面的举措。②④说法正确。故本题答案为D。"},{"id":"zz-1q12","n":12,"s":"2026年9月1日，习近平总书记在上海合作组织峰会上发表讲话指出，今年是上海合作组织成立25周年。25年来，上海合作组织走过不平凡历程。关于上海合作组织，下列说法不正确的是：","o":["最重大的发展成就是一步步成为世界上幅员最广、人口最多、发展潜力巨大的新型区域合作组织","最宝贵的精神财富是开创性提出和始终遵循互信、互利、平等、协商、尊重多样文明、谋求共同发展的“上海精神”","最重要的合作经验是找到不结盟、不对抗、不针对第三方的正确共处之道","最核心的组织定位是成为当今世界最具影响力的新兴市场和发展中国家合作平台"],"a":"D","e":"A、B、C项说法正确：习近平总书记指出，今年是上海合作组织成立25周年。25年来，上海合作组织走过不平凡历程。最重大的发展成就是一步步成为世界上幅员最广、人口最多、发展潜力巨大的新型区域合作组织；最宝贵的精神财富是开创性提出和始终遵循互信、互利、平等、协商、尊重多样文明、谋求共同发展的“上海精神”；最重要的合作经验是找到不结盟、不对抗、不针对第三方的正确共处之道，推动地区国家携手建设共同家园。D项说法错误：当今世界最具影响力的新兴市场和发展中国家合作平台是金砖合作机制。故本题答案为D。"},{"id":"zz-1q13","n":13,"s":"《2026年政府工作报告》指出，要坚持内需主导，统筹促消费和扩投资，拓展内需增长新空间，更好发挥我国超大规模市场优势。下列说法正确的有几项？\n①增强政府主导的有效投资增长动力，提高民生类政府投资比重\n②单列并降低用于项目建设的地方政府专项债券额度，继续向投资项目准备充分、资金用得好的地方倾斜\n③制定实施城乡居民增收计划，在促进低收入群体增收、增加居民财产性收入、完善薪酬和社保制度等方面推出一批务实举措\n④扩大个人消费贷款和服务业经营主体贷款贴息政策支持领域，提高贴息上限","o":["1项","2项","3项","4项"],"a":"B","e":"①说法错误：增强市场主导的有效投资增长动力，提高民生类政府投资比重。②说法错误：单列并提高用于项目建设的地方政府专项债券额度，继续向投资项目准备充分、资金用得好的地方倾斜。③④说法正确。故本题答案为B。"},{"id":"zz-1q14","n":14,"s":"2026年1月，中国共产党第二十届中央纪律检查委员会第五次全体会议召开。下列说法正确的是：","o":["党的自我革命重在授权，把权力关进制度笼子是全面从严治党的重要任务","深化巡察巡视上下联动，加强对省区市巡察、对村巡视工作指导督导","持续深化群众身边不正之风和腐败问题集中整治，推动省级主战场持续深化整治工作，发挥群众监督作用","把权力关进制度笼子，既要不断完善制度规定，使制度密而不繁、有效管用，又要着力提高制度执行力，增强刚性约束"],"a":"D","e":"A项说法错误：党的自我革命重在治权，把权力关进制度笼子是新时代全面从严治党的一项重要任务。B项说法错误：深化巡视巡察上下联动，加强对省区市巡视、中央单位内部巡视、对村巡察工作指导督导。C项说法错误：推动县级主战场持续深化整治工作，发挥群众监督作用，提升基层监督能力。故本题答案为D。"},{"id":"zz-1q15","n":15,"s":"2026年9月，第18期《求是》杂志发表习近平总书记重要文章《在加强基础研究座谈会上的讲话》。文章指出，要优化基础研究系统布局。下列举措说法正确的是：\n①要把准目标方向，坚持“四个面向”战略导向，从国家急迫需要和长远需求出发，进一步明确基础研究的主攻方向和重点领域\n②要强化力量协同，发挥新型举国体制优势，强化国家实验室、国家科研机构、高水平研究型大学等引领作用\n③要鼓励和规范发展新型研发机构，推动国家实验室主导的产学研深度融合，打通基础研究、应用开发、成果转化的创新链条\n④要健全学科布局，完善学科设置调整机制，加强基础学科建设，促进应用学科与基础学科协调发展，鼓励多学科交叉融合和跨学科研究","o":["②③④","①②④","①③④","①②③"],"a":"B","e":"③说法错误：强化力量协同，发挥新型举国体制优势，强化国家实验室、国家科研机构、高水平研究型大学等引领作用，鼓励和规范发展新型研发机构，推动企业主导的产学研深度融合，打通基础研究、应用开发、成果转化的创新链条。①②④说法正确。故本题答案为B。"},{"id":"zz-1q16","n":16,"s":"2026年4月，全国服务业大会在京召开。习近平总书记就服务业发展作出重要指示。下列相关说法，正确的是：","o":["我国服务业规模稳步扩大，质效持续提升，在支撑产业升级、满足民生需要、带动就业扩容等方面发挥了重要作用，服务贸易规模稳居全球第二","要突出供给牵引、改革攻坚、科技赋能、开放合作，深入实施服务业扩能提质行动","要推进生活性服务业向专业化和价值链高端延伸，促进生产性服务业高品质多样化便利化发展","要扩大服务业高水平对外开放，服务业领域外资准入负面清单已实现清零"],"a":"A","e":"B项说法错误：突出需求牵引、改革攻坚、科技赋能、开放合作，深入实施服务业扩能提质行动。C项说法错误：要推进生产性服务业向专业化和价值链高端延伸，要促进生活性服务业高品质多样化便利化发展。D项说法错误：“十四五”时期，制造业领域外资准入负面清单已实现清零。“十五五”规划纲要指出，放宽服务领域准入，扩大服务业高水平对外开放。但“放宽服务领域准入”不等于“完全放开”，服务业领域外资准入负面清单并未实现清零。故本题答案为A。"},{"id":"zz-1q17","n":17,"s":"2026年3月，《关于做好第二轮土地承包到期后再延长30年试点工作的意见》发布。下列相关要求，说法正确的是：","o":["牢牢把住提高农民收入这条主线，坚持把依法维护农民权益作为出发点和落脚点","逐步推行市场化改革，农村集体土地可以由本集体经济组织外的成员有偿进行承包","不断完善“三权分置”政策体系，落实集体所有权、稳定土地经营权、放活农户承包权","坚持农民主体地位，充分发挥农民主动性和创造性，鼓励农民集体在法律和政策范围内因地制宜探索延包具体路径和办法"],"a":"D","e":"A项说法错误：牢牢把住处理好农民和土地关系这条主线，坚持把依法维护农民权益作为出发点和落脚点。B项说法错误：农村集体土地家庭承包，仅限本集体经济组织内部农户。外部主体可以流转经营权，但不能取得承包权。C项说法错误：不断完善三权分置政策体系，落实集体所有权、稳定农户承包权、放活土地经营权。故本题答案为D。"},{"id":"zz-1q18","n":18,"s":"2026年6月，《美丽中国建设“十五五”规划》发布，这是我国生态环境领域第一部以“美丽中国建设”命名的五年规划。下列相关说法，正确的有几项？\n①到2030年，绿色生产生活方式基本形成，碳中和目标如期实现\n②京津冀及周边地区、长三角地区和汾渭平原，推动煤炭消费总量保持下降趋势、新改扩建用煤项目依法实行煤炭等量或增量替代\n③持续巩固以青藏高原生态屏障区、黄河重点生态区、长江重点生态区、东北森林带、北方防沙带、南方丘陵山地带、海岸带等“三区四带”为骨架的国家生态安全屏障体系\n④建立健全以国家公园为主体的自然保护地体系，自然保护地面积占陆域国土面积比例不低于18%\n⑤有序扩大全国碳排放权交易市场覆盖行业范围、扩展参与主体，对碳排放总量相对稳定的行业优先实施配额总量控制，稳妥推行免费和有偿相结合的配额分配方式","o":["2项","3项","4项","5项"],"a":"B","e":"①说法错误：到2030年，绿色生产生活方式基本形成，碳达峰目标如期实现。2060年实现碳中和目标。②说法错误：京津冀及周边地区、长三角地区和汾渭平原，推动煤炭消费总量保持下降趋势、新改扩建用煤项目依法实行煤炭等量或减量替代。③④⑤说法正确。故本题答案为B。"},{"id":"zz-1q19","n":19,"s":"2026年，习近平总书记多次给有关方面和各界群众致信回信，以殷殷嘱托激励他们踔厉奋发、勇毅前行，积极投身强国建设、民族复兴伟业。下列致信回信的内容与其对象对应正确的是：\n①赓续千年书院学脉，弘扬“实事求是、敢为人先”的精神，努力培养更多经世致用的优秀人才——四所交通大学全体师生\n②扎根通信技术岗位辛勤付出一辈子，期颐之年仍关心党和国家事业发展——新华社老党员张连生\n③传承红色基因，增长知识本领，磨练意志品质，做党和人民的红孩子——中央广播电视总台《小喇叭》节目\n④守百姓幸福，护家国平安，人民公安重任在肩——福建省“漳州110”全体队员","o":["①③","①④","②③","②④"],"a":"D","e":"①说法错误：习近平总书记给四所交通大学全体师生回信，勉励他们要秉持“求实学、务实业”办学宗旨，传承弘扬西迁精神，聚焦国家重大战略需求，加强科技自主创新和人才自主培养，在促进产学研深度融合上实现更多突破，为建设教育强国、科技强国、人才强国作出新贡献。习近平总书记在湖南大学建校100周年的贺信中强调，希望湖南大学以新时代中国特色社会主义思想为指导，继承光荣革命传统，赓续千年书院学脉，弘扬“实事求是、敢为人先”的精神，不断提升办学质量和水平，努力培养更多经世致用的优秀人才，为建设教育强国、推进中国式现代化作出新贡献。③说法错误：习近平总书记在致中央广播电视总台《小喇叭》节目开播70周年的贺信中指出，要落实立德树人根本任务，紧扣时代发展脉搏，深耕少儿文化沃土。习近平总书记在给中共一大纪念馆、南湖革命纪念馆少先队红领巾讲解员回信时指出，要传承红色基因，增长知识本领，磨练意志品质，做党和人民的红孩子。②④说法正确。故本题答案为D。"},{"id":"zz-1q20","n":20,"s":"2026年7月，习近平总书记对基础教育工作作出重要指示，强调党的十八大以来，党中央把基础教育作为基础性、先导性工作来抓，多措并举推动基础教育实现长足发展，为建设教育强国提供了有力支撑。下列相关说法，正确的有几项？\n①要以加强师德师风建设为教育的根本任务，坚持不懈用党的创新理论铸魂育人，培养德智体美劳全面发展的社会主义建设者和接班人\n②要遵循教育规律，落实健康第一教育理念，提升教育教学质量，促进广大学生身心健康、成长成才\n③要推动学校、家庭、社会各自发力，不断开创基础教育高质量发展新局面\n④我国已建成了世界上规模最大且有质量的基础教育体系，基础教育总体已经达到世界高收入国家的平均水平","o":["4项","3项","2项","1项"],"a":"C","e":"①说法错误：要以新时代中国特色社会主义思想为指导，全面贯彻党的教育方针，落实立德树人根本任务，坚持不懈用党的创新理论铸魂育人，培养德智体美劳全面发展的社会主义建设者和接班人。③说法错误：各级党委和政府要切实扛起政治责任，优化办学资源配置，深化教育综合改革，推动学校、家庭、社会同向发力，不断开创基础教育高质量发展新局面。②④说法正确。故本题答案为C。"}]},{"id":"zz-2","cat":"zz","title":"小黑模考五套卷 · 第二套","short":"第二套","sub":"20 题","questions":[{"id":"zz-2q1","n":1,"s":"习近平总书记指出，保障和改善民生要抓住人民最关心最直接最现实的利益问题，既尽力而为，又量力而行，一件事情接着一件事情办，一年接着一年干。这一要求体现的哲学道理是：\n①发挥主观能动性与尊重客观规律是辩证统一的\n②量变是质变的必要准备，要注重量的积累\n③办事情要善于抓住重点，集中力量解决主要矛盾\n④矛盾的普遍性寓于特殊性之中，要坚持具体问题具体分析\n⑤人民群众是社会历史的主体，要坚持群众观点和群众路线","o":["①②③⑤","①②④","①③④⑤","②③④"],"a":"A","e":"①符合题意：“尽力而为”强调充分发挥主观能动性，积极作为、主动担当；“量力而行”强调尊重客观规律，从实际出发，按规律办事。二者结合体现了发挥主观能动性与尊重客观规律的辩证统一。②符合题意：“一件事情接着一件事情办，一年接着一年干”强调民生建设是一个循序渐进、持续积累的过程，体现了量变是质变的必要准备，要重视量的积累，通过持续努力逐步实现民生改善的质的飞跃。③符合题意：“抓住人民最关心最直接最现实的利益问题”体现了在复杂事物发展过程中要善于抓住主要矛盾，集中力量解决关键问题，以重点突破带动整体推进。④不符合题意：题干材料并未涉及矛盾普遍性与特殊性的关系，也未体现具体问题具体分析的方法论要求。⑤符合题意：“抓住人民最关心最直接最现实的利益问题”直接表明民生工作的出发点和落脚点在于人民，体现了人民群众是历史的创造者、是社会历史的主体，要坚持一切为了群众、一切依靠群众。故本题答案为A。"},{"id":"zz-2q2","n":2,"s":"习近平总书记指出，当前和今后一个时期，我国卫生与健康工作需要因应形势发展变化，优化完善一些具体政策举措，但是走中国特色卫生与健康发展道路不能动摇，贯彻新时代卫生与健康工作方针不能动摇。这段话体现的哲学道理是：公考资料免费更新加微shgk738\n①物质决定意识，要坚持一切以时间、地点、条件为转移\n②物质世界的发展是绝对运动和相对静止的统一\n③社会意识具有相对独立性，总是落后于社会存在的发展\n④辩证否定的实质是“扬弃”，即既克服又保留","o":["①②③","①②④","①③④","②③④"],"a":"B","e":"①符合题意：“因应形势发展变化，优化完善一些具体政策举措”，说明政策举措的调整要依据客观形势这一物质条件，体现物质决定意识，要求一切以时间、地点、条件为转移。②符合题意：“优化完善具体政策举措”是运动变化，“道路”“方针”不能动摇是保持相对稳定，体现物质世界的发展是绝对运动和相对静止的统一。③说法错误：社会意识具有相对独立性，但“总是落后于社会存在的发展”这一表述过于绝对，社会意识有时会先于社会存在而变化。④符合题意：优化完善具体政策举措是对原有政策中不适应形势部分的克服，坚守正确道路与方针是对合理部分的保留，体现辩证否定的实质是“扬弃”，即既克服又保留。故本题答案为B。"},{"id":"zz-2q3","n":3,"s":"2026年，我国继续实施更加积极的财政政策。一方面，适当提高财政赤字率，扩大政府投资规模，加大对科技创新、民生保障等重点领域的支持力度；另一方面，明确强调“不搞大水漫灌”，坚决防止债务风险累积，确保财政可持续。上述做法最能体现的哲学道理是：","o":["事物的量变必然引起质变，要积极促进事物质的飞跃","事物发展是前进性与曲折性的统一，要做好应对困难的思想准备","度是保持事物质的稳定性的数量界限，要坚持适度原则","上层建筑适合经济基础状况，就能推动生产力发展"],"a":"C","e":"C项符合题意：题干中“适当提高赤字率、扩大政府投资规模”体现的是政策力度上的加力，“不搞大水漫灌、防止债务风险累积、确保财政可持续”强调的则是把握力度、守住边界。这两个方面共同说明，财政政策在扩张时必须控制在合理限度内，超过一定界限就会使财政可持续性这一“质”发生改变；这正是“度是保持事物质的稳定性的数量界限，要坚持适度原则”的道理。A项说法错误：“量变必然引起质变”表述绝对化，量变只有积累到一定程度才会引起质变。B项说法正确，但是与题意无关。D项说法错误：上层建筑适合经济基础状况，并且为先进经济基础服务时，才会推动生产力发展。故本题答案为C。"},{"id":"zz-2q4","n":4,"s":"实体经济是一国经济的立身之本，是财富创造的根本源泉，是国家强盛的重要支柱。下列相关说法，正确的有几项？\n①坚持把发展经济的着力点放在实体经济上，推动资源要素向实体经济集聚、政策措施向实体经济倾斜、工作力量向实体经济加强\n②制造业是实体经济的基础，要快速扩大制造业规模，坚定不移建设制造强国\n③实施产业基础再造工程和重大技术装备攻关工程，支持专精特新企业发展，推动制造业高端化、智能化、绿色化发展\n④实体经济是金融的根基，金融是实体经济的血脉，要防止金融逐渐脱实向虚","o":["1项","2项","3项","4项"],"a":"C","e":"②说法错误：制造业是实体经济的基础，要保持制造业合理比重，坚定不移建设制造强国。“快速扩大制造业规模”表述不恰当。①③④说法正确。故本题答案为C。"},{"id":"zz-2q5","n":5,"s":"坚持马克思主义在意识形态领域的指导地位，植根博大精深的中华文明，顺应信息技术发展潮流，发展具有强大思想引领力、精神凝聚力、价值感召力、国际影响力的新时代中国特色社会主义文化。下列相关举措，说法正确的有几项？\n①坚持不懈用习近平新时代中国特色社会主义思想凝心铸魂，加强体系化、学理化研究阐释和大众化、通俗化宣传普及\n②盘活用好各类公共文化设施资源，有序推进公共文化设施所有权和使用权分置改革\n③推动文化遗产系统性保护和统一监管，推进管理资源整合，建立文化遗产保护督察制度\n④改造提升传统文化业态，推动文化建设数智化赋能、信息化转型，发展数字动漫、沉浸式展演、线上演播、短视频、微短剧等新型文化业态","o":["1项","2项","3项","4项"],"a":"D","e":"①②③④说法均正确。故本题答案为D。"},{"id":"zz-2q6","n":6,"s":"2026年6月，第12期《求是》杂志发表习近平总书记重要文章《一体推进教育科技人才发展》。教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑。下列相关表述，正确的有几项？\n①要增强系统观念，坚持教育优先发展、科技自立自强、人才引领驱动\n②科学技术是第一生产力、第一竞争力、第一资源，必须充分认识科学技术的根本支撑作用\n③要优化国家科研机构、高水平研究型大学、科技领军企业定位和布局，强化基础研究领域、交叉前沿领域、重点领域前瞻性、引领性布局\n④基础研究是科技创新的源头，要有组织推进市场导向的体系化基础研究、前沿导向的探索性基础研究、战略导向的应用性基础研究\n⑤要坚持把引进人才作为满足人才需求的核心环节，努力充实高科技人才队伍","o":["1项","2项","3项","4项"],"a":"B","e":"②说法错误：必须充分认识科技的根本支撑作用，科学技术是第一生产力、第一竞争力，人才是第一资源，创新是第一动力。所以科学技术是第一资源搭配不当。④说法错误：基础研究是科技创新的源头，要有组织推进战略导向的体系化基础研究、前沿导向的探索性基础研究、市场导向的应用性基础研究。⑤说法错误：走好人才自主培养之路，满足庞大的人才需求必须主要依靠自主培养。①③说法正确。故本题答案为B。"},{"id":"zz-2q7","n":7,"s":"国家安全是民族复兴的根基，社会稳定是国家强盛的前提。必须坚定不移贯彻总体国家安全观，把维护国家安全贯穿党和国家工作各方面全过程，确保国家安全和社会稳定。下列相关举措，说法正确的有几项？\n①要落实行业监管、属地管理、政府主体的食品药品安全责任，加大违法犯罪行为惩治力度\n②要强化末端治理、预判预警、早期纠正，统筹推进房地产、地方政府债务、中小金融机构等风险有序化解\n③要坚持立足国内、补齐短板、多元保障、强化储备，加强能源产供储销体系建设\n④要严格落实耕地保护和粮食安全党政同责要求，严守耕地红线","o":["1项","2项","3项","4项"],"a":"B","e":"①说法错误：要落实行业监管、属地管理、企业主体的食品药品安全责任，加大违法犯罪行为惩治力度。②说法错误：要强化源头防控、预判预警、早期纠正，统筹推进房地产、地方政府债务、中小金融机构等风险有序化解。③④说法正确。故本题答案为B。"},{"id":"zz-2q8","n":8,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。下列关于持之以恒推进全面从严治党，说法正确的是：","o":["以宪法为根本，坚持党的先锋队性质，坚持党的全面领导和党中央集中统一领导","着眼于提高党的长期行政能力、保持党的先进性和纯洁性、保持党同人民群众的血肉联系","坚持严的基调不动摇，健全全面从严治党体系，以党的制度建设为统领，全面推进党的各方面建设","充分激发全党积极性主动性创造性，不断实现党的自我净化、自我完善、自我革新、自我提高，持续增强党的政治领导力、思想引领力、群众组织力、社会号召力"],"a":"D","e":"A、B、C项说法错误，D项说法正确：全会指出，落实新时代党的建设总要求，以党章为根本，坚持党的先锋队性质，坚持党的全面领导和党中央集中统一领导，着眼于提高党的长期执政能力、保持党的先进性和纯洁性、保持党同人民群众的血肉联系，坚持严的基调不动摇，健全全面从严治党体系，以党的政治建设为统领，全面推进党的各方面建设，充分激发全党积极性主动性创造性，不断实现党的自我净化、自我完善、自我革新、自我提高，持续增强党的政治领导力、思想引领力、群众组织力、社会号召力。故本题答案为D。"},{"id":"zz-2q9","n":9,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。党的十八大以来，逐渐形成了党委抓、书记抓、各有关部门抓、一级抓一级、层层抓落实的党建工作格局。下列说法正确的有几项？\n①围绕加强对管党治党的领导、选好用好干部、强化权力运行监督制约、维护群众利益等，明确纪委全面从严治党主体责任\n②围绕高效监督、从严执纪、精准问责等，明确各级监察委员会的监督责任\n③围绕抓好班子、带好队伍、推动落实，明确纪委书记第一责任人责任\n④结合职责任务分工，按照“一岗双责”要求，明确领导班子其他成员的管党治党责任\n⑤围绕严于自律和互相监督、互相提醒帮助，结合党员、干部岗位特点和工作实际，明确党员、干部的具体责任","o":["2项","3项","4项","5项"],"a":"A","e":"①说法错误：围绕加强对管党治党的领导、选好用好干部、强化权力运行监督制约、维护群众利益等，明确党委（党组）全面从严治党主体责任。②说法错误：围绕高效监督、从严执纪、精准问责等，明确各级纪委的监督责任。纪委是党内监督专责机关，监察委员会是国家监督机关而非党内监督专责机关。小黑提示，出题人在这里故意偷换主体，纪委和监委二者虽然合署办公，但在落实全面从严治党政治责任这个语境下，只能用纪委，不用监委。③说法错误：围绕抓好班子、带好队伍、推动落实，明确党委（党组）书记第一责任人责任。④⑤说法正确，故本题答案为A。"},{"id":"zz-2q10","n":10,"s":"2026年10月12日至13日，全国卫生与健康大会在京召开。习近平总书记出席会议并发表重要讲话。讲话指出，全面提高医疗服务水平是建成健康中国的一项重点任务。下列相关说法，正确的有几项？\n①要深入实施医疗卫生强基工程，优化医疗卫生机构功能定位和结构布局，促进集中诊疗，让群众能就近看得上病、看得好病\n②要加强慢性病综合防控，完善防治康管全链条服务\n③要健全中医药传承创新发展机制，强化中西医逐步分离、独立发展\n④要加强卫生与健康领域基础研究和原始创新，促进科技成果转化，做大做强健康产业\n⑤要优化就医体验，不断提高群众看病就医的便利度和满意度","o":["2项","3项","4项","5项"],"a":"B","e":"①说法错误：要深入实施医疗卫生强基工程，优化医疗卫生机构功能定位和结构布局，促进分级诊疗，让群众能就近看得上病、看好病。③说法错误：健全中医药传承创新发展机制，强化中西医协同融合。②④⑤说法正确。故本题答案为B。"},{"id":"zz-2q11","n":11,"s":"2026年10月9日，《中共中央国务院关于发展新质生产力的意见》发布。《意见》指出，要强化企业科技创新主体地位。下列相关说法，正确的有几项？\n①加强普惠激励政策供给，建立企业研发准备金制度，强化企业科技投入主导作用\n②鼓励科技型中小企业加大研发投入，降低企业研发费用加计扣除比例\n③将各类企业研发项目按程序上升为国家项目，鼓励企业牵头国家科技任务\n④支持有能力的民营企业牵头承担国家重大技术攻关任务\n⑤建立用户考核评价成果的机制，强化企业成果转化主体地位","o":["2项","3项","4项","5项"],"a":"B","e":"②说法错误：鼓励科技型中小企业加大研发投入，提高企业研发费用加计扣除比例。③说法错误：将符合国家战略需求的企业研发项目按程序上升为国家项目，鼓励企业牵头国家科技任务，支持有能力的民营企业牵头承担国家重大技术攻关任务。①④⑤说法正确。故本题答案为B。"},{"id":"zz-2q12","n":12,"s":"2026年10月21日，《中共中央办公厅国务院办公厅关于推动科技创新和产业创新深度融合的意见》发布。《意见》指出，推动科技创新和产业创新深度融合，是以高水平科技自立自强引领发展新质生产力的关键。下列说法正确的是：","o":["统筹布局国家新兴产业创新中心、国家产业技术工程化中心、国家技术创新中心、国家制造业创新中心等，优先强化重点产业关键个性技术供给","逐步弱化央地合作，鼓励各地自主承担科技投入、重大任务实施","健全科技成果转化、创业投资等方面尽职免责机制，探索建立负面清单","完善国有企业分类考核评价体系，降低企业与高校、科研院所等联合研发费用视同利润加回的比例"],"a":"C","e":"A项说法错误：统筹布局国家新兴产业创新中心、国家产业技术工程化中心、国家技术创新中心、国家制造业创新中心等，强化重点产业关键共性技术供给。B项说法错误：加强央地协同，健全中央与地方科技投入共担、重大任务联动实施机制。D项说法错误：完善国有企业分类考核评价体系，提高企业与高校、科研院所等联合研发费用视同利润加回的比例。故本题答案为C。"},{"id":"zz-2q13","n":13,"s":"《2026年政府工作报告》指出，要纵深推进全国统一大市场建设。下列说法正确的是：","o":["鼓励地方政府经济促进行为，多出台差异化税收优惠、财政补贴政策","加强反垄断、反不正当竞争，强化公平竞争审查柔性约束","综合运用产能调控、标准引领、价格执法、质量监管等手段，鼓励“内卷式”竞争，营造良好市场生态","深化要素市场化配置综合改革试点，将更多符合条件的地区纳入试点范围"],"a":"D","e":"A项说法错误：规范地方政府经济促进行为，出台地方政府招商引资鼓励和禁止事项清单，规范税收优惠、财政补贴政策。“差异化税收优惠、财政补贴政策”不利于推进全国统一大市场建设。B项说法错误：加强反垄断、反不正当竞争，强化公平竞争审查刚性约束。C项说法错误：综合运用产能调控、标准引领、价格执法、质量监管等手段，深入整治“内卷式”竞争，营造良好市场生态。故本题答案为D。"},{"id":"zz-2q14","n":14,"s":"2026年6月18日，《关于学习贯彻习近平党建思想的通知》印发。关于习近平党建思想的科学内涵，下列说法正确的有几项？\n①坚持党中央集中统一领导是党的领导的最高原则\n②坚持锤炼坚强党性是党的宗旨立场和价值取向\n③坚持落实管党治党政治责任是全面从严治党需要牢牢牵住的“牛鼻子”\n④坚持推进作风建设常态化长效化是保持党同人民群众血肉联系的有效途径\n⑤坚持用党的创新理论凝心铸魂是党的思想建设的首要任务","o":["2项","3项","4项","5项"],"a":"B","e":"②说法错误：坚持不忘初心、牢记使命是党的宗旨立场和价值取向。坚持锤炼坚强党性是党员、干部的终身课题。⑤说法错误：坚持用党的创新理论凝心铸魂是党的思想建设的根本任务。坚定理想信念是党的思想建设的首要任务。①③④说法正确。故本题答案为B。"},{"id":"zz-2q15","n":15,"s":"2026年9月，第18期《求是》杂志发表习近平总书记重要文章《在加强基础研究座谈会上的讲话》。文章指出，要加强对基础研究的支持保障。下列说法正确的是：","o":["要逐步提高基础研究经费占比，进一步拓宽筹资渠道，稳步增加财政投入，引导企业和社会力量加大投入，形成基础研究多元化投入格局","要建立以竞争性支持取代稳定支持的基础研究投入机制","要加紧建设世界一流科技期刊，鼓励国内外成果在海外期刊和平台首发","要深化科技体制改革，健全符合基础研究特点的统一评价体系，完善基础研究激励机制"],"a":"A","e":"B项说法错误：提高科学基金资助效能，对从事基础研究的科研机构和平台基地提供稳定支持，对优秀研究团队和人才实行竞争择优基础上的接续支持，对重大原创项目采取滚动式支持。故要完善竞争性支持和稳定支持相结合的基础研究投入机制，而非“竞争性支持取代稳定支持”。C项说法错误：加紧建设世界一流科技期刊，鼓励国内外成果在我国期刊和平台首发。D项说法错误：深化科技体制改革，健全符合基础研究特点的分类评价体系，完善基础研究激励机制，改革科研管理方式。故本题答案为A。"},{"id":"zz-2q16","n":16,"s":"习近平总书记指出，当前世界百年变局加速演进，新一轮科技革命和产业变革加速突破，全球人工智能技术创新进入前所未有的活跃期，既蕴含巨大机遇，也面临治理挑战。下列关于人工智能发展，说法正确的有几项？\n①人工智能以数据、算力、算法等为关键要素，以神经科学、认知科学、计算科学、数学等理论突破和学科交叉为基础，以智能前沿技术群体性突破和广泛渗透赋能为标志\n②人工智能呈现数据驱动、万物互联、人机协同、跨界融合等显著特征\n③各国应当秉持以人为本、向上向善理念，让人工智能成为促进共同繁荣、维护共同安全的一个重要动力源\n④要加强人工智能发展战略、治理规则、技术标准的对接协调，早日形成具有广泛共识的全球治理框架\n⑤要维护产业安全，加快构建独立于西方技术体系的发展中国家人工智能产业链","o":["5项","4项","3项","2项"],"a":"B","e":"⑤说法错误：我们坚持高水平自立自强、自主可控，但倡导鼓励开源开放、合作共享。“构建独立于西方技术体系的发展中国家人工智能产业链”，和习近平总书记强调的“坚持开放共赢”完全相悖。①②③④说法正确。故本题答案为B。"},{"id":"zz-2q17","n":17,"s":"新时代以来，习近平总书记在地方考察和重要指示中，多次肯定基层创造的一系列先进发展治理经验，并要求各地结合实际学习借鉴、复制推广，更好推动高质量发展和社会治理现代化。下列经验与学习要求对应正确的是：","o":["学习“义乌发展经验”——因地制宜完善乡村建设实施机制，分类有序、片区化推进乡村振兴","学习“闽宁协作”经验——推动产业互补、人员互动、技术互学、观念互通、作风互鉴","学习新时代“枫桥经验”——引导各地区立足自身资源禀赋，尊重基层和群众首创精神，因地制宜发展县域经济","学习“千万工程”经验——紧紧依靠人民群众，把问题解决在基层、化解在萌芽状态"],"a":"B","e":"A项说法错误：学习“义乌发展经验”，要求引导各地区立足自身资源禀赋，尊重基层和群众首创精神，因地制宜发展县域经济。C项说法错误：学习新时代“枫桥经验”，要求紧紧依靠人民群众，把问题解决在基层、化解在萌芽状态。D项说法错误：学习“千万工程”经验，要求因地制宜完善乡村建设实施机制，分类有序、片区化推进乡村振兴。故本题答案为B。"},{"id":"zz-2q18","n":18,"s":"2026年2月，《中共中央国务院关于锚定农业农村现代化扎实推进乡村全面振兴的意见》发布。文件指出，要提升农业综合生产能力和质量效益。下列表述正确的有几项？\n①坚持产量产能、生产生态、增产增收一起抓，实施新一轮万亿斤粮食产能提升行动\n②分区分类高质量推进高标准农田建设，完善立项、建设、验收和管护机制\n③加强北方地区防洪排涝体系建设，适度提高工程建设标准\n④在确保省域内耕地保护任务不降低前提下，稳妥有序退出河道湖区影响行洪安全等的不稳定耕地\n⑤深化涉农高校教育教学改革，以就业为导向加快新农科建设","o":["2项","3项","4项","5项"],"a":"B","e":"①说法错误：坚持产量产能、生产生态、增产增收一起抓，加力实施新一轮千亿斤粮食产能提升行动，促进良田良种良机良法集成增效，推进粮油作物大面积提单产。⑤说法错误：深化涉农高校教育教学改革，以需求为导向加快新农科建设，推动涉农专业人才定向培养。②③④说法正确。故本题答案为B。"},{"id":"zz-2q19","n":19,"s":"2026年8月15日，《中华人民共和国生态环境法典》正式施行。下列相关说法，正确的有几项？\n①这是中国第一部以“法典”命名的法律，也是世界上首部以“生态环境”命名的法典\n②法典中“生态保护”单独成编，为世界环境法典体例之首创\n③法典以“五编体”搭建科学完备的生态环境法治体系，促进生态环境治理系统集成、协同高效\n④法典以“完全法典化”的编纂模式，形成法典统领、单行法配套衔接的分层立法格局，探索出兼具体系性与开放性、稳定性与适应性的编纂新路\n⑤法典以习近平生态文明思想为魂和纲，是习近平生态文明思想和习近平法治思想贯通融合、交相辉映的重要结晶","o":["5项","4项","3项","2项"],"a":"D","e":"①说法错误：《中华人民共和国生态环境法典》是世界上首部以“生态环境”命名的法典，但该法典是我国第二部以“法典”命名的法律，第一部是《中华人民共和国民法典》。②说法错误：法典中“绿色低碳发展”单独成编，为世界环境法典体例之首创。④说法错误：法典采用适度法典化编纂模式，并非完全法典化。③⑤说法正确。故本题答案为D。"},{"id":"zz-2q20","n":20,"s":"习近平总书记指出，要坚持惠民生和促消费、投资于物和投资于人紧密结合。下列属于投资于人范畴的有几项？\n①全面实施育儿补贴制度、惠及3000多万婴幼儿\n②开工建设雅鲁藏布江下游水电工程，规划总装机规模约6000万千瓦\n③加大超长期特别国债投入，支持“东数西算”、特高压等新型基建项目\n④全国范围内免除公办幼儿园学前一年在园儿童保育教育费","o":["1项","2项","3项","4项"],"a":"B","e":"“投资于人”是指将资源投向教育、医疗、托育、养老等民生领域，聚焦人的能力提升、生活保障与全面发展，以此提升人力资本、释放消费潜力。“投资于物”则指向基础设施、能源工程等物质资本建设，二者共同服务于扩大内需战略。①④涉及民生，属于“投资于人”范畴。②③涉及基础设施，属于“投资于物”范畴。故本题答案为B。"}]},{"id":"zz-3","cat":"zz","title":"小黑模考五套卷 · 第三套","short":"第三套","sub":"20 题","questions":[{"id":"zz-3q1","n":1,"s":"2026年10月22日，纪念中国工农红军长征胜利90周年大会隆重举行。习近平总书记指出，红军长征创造了非凡的人间奇迹，铸就了伟大长征精神。精神所在，就是力量所在。伟大长征精神充分彰显了忠诚的力量、真理的力量、正义的力量、团结的力量，它作为中国共产党人精神谱系的重要组成部分，跨越时空、历久弥新，永远是激励我们战胜困难、勇往直前的宝贵财富和强大动力。这体现的哲学道理是：\n①社会意识具有相对独立性，先进的社会意识对社会发展起促进作用\n②精神力量通过实践可以转化为改造世界的物质力量\n③认识具有直接现实性，正确的认识对实践具有巨大的指导效果\n④人民群众是社会历史的主体，是社会变革的领导力量","o":["③④","①③","②④","①②"],"a":"D","e":"①符合题意：“伟大长征精神……跨越时空、历久弥新，永远是激励我们战胜困难、勇往直前的宝贵财富和强大动力”，说明社会意识具有相对独立性，先进的社会意识对社会发展起积极的促进作用。②符合题意：题干强调“精神所在，就是力量所在”，长征精神本身是精神力量，但它能激励人们“战胜困难、勇往直前”，即通过人们的实践活动转化为改造客观世界的物质力量，体现了精神力量通过实践可以向物质力量转化。③说法错误：实践具有直接现实性，认识不具有直接现实性。④说法错误：人民群众是社会历史的主体，是历史的创造者，人民群众是社会变革的决定力量，而非“领导力量”。故本题答案为D。"},{"id":"zz-3q2","n":2,"s":"习近平总书记强调，在革命、建设、改革中先后把党的建设作为伟大工程、新的伟大工程，党的十八大以来深入推进新时代党的建设新的伟大工程，找到“让人民来监督政府”和“自我革命”两个跳出治乱兴衰历史周期率的答案，这是中国共产党的独特创造，永载马克思主义政党建设史册。这体现的哲学道理是：\n①认识具有无限性，追求真理是一个永无止境的过程\n②事物的发展是内因和外因共同作用的结果，二者相辅相成\n③人民群众是历史的创造者，要坚持群众观点和群众路线\n④辩证否定是事物的自我否定，是事物联系和发展的环节","o":["②③④","①②","③④","①②③④"],"a":"D","e":"①符合题意：从革命、建设时期的“伟大工程”到“新的伟大工程”，从一个答案到两个答案，体现了党对执政规律和党建规律的认识不断深化，说明认识具有无限性，追求真理是一个永无止境的过程。②符合题意：“让人民来监督政府”强调外在力量的约束性（外因），“自我革命”强调内在力量的主导性（内因），两者相辅相成、内外结合，共同构成跳出历史周期率的完整路径，体现了事物的发展是内因和外因共同作用的结果。③符合题意：“让人民来监督政府”体现了唯物史观中人民群众是历史创造者的基本原理，党始终坚持以人民为中心，依靠人民监督保证权力正确运行，坚持了群众观点和群众路线。④符合题意：“自我革命”是党对自身的辩证否定，是自我批判、自我扬弃、自我革新的过程，不是全盘否定，而是在继承基础上的创新发展；从“伟大工程”到“新的伟大工程”，每个阶段都是在前一阶段基础上的继承与发展，体现了辩证否定是事物联系和发展的环节。故本题答案为D。"},{"id":"zz-3q3","n":3,"s":"习近平总书记强调，党的各级组织层层压实主体责任，把严的要求贯穿管党治党全过程，日常管理监督立足于早、着眼于小，发现苗头及时提醒，触犯纪律立即处理，多积尺寸之功，经常防微杜渐。这体现的哲学道理是：","o":["事物的发展是前进性与曲折性的统一","量变是质变的必要准备，要重视量的积累","主要矛盾的主要方面决定事物的性质","实践是检验认识真理性的唯一标准"],"a":"B","e":"B项符合题意：材料中“立足于早、着眼于小”“发现苗头及时提醒”“多积尺寸之功”“防微杜渐”等表述，强调的是在问题尚处于萌芽状态时就加以干预，防止不良因素的量变积累到一定程度引发质变。这体现了唯物辩证法中量变与质变的辩证关系原理——量变是质变的必要准备，质变是量变的必然结果。只有重视量的积累，从小处着手、从早处防范，才能有效防止消极的质变发生。A、C、D项说法正确，但是与题意无关。故本题答案为B。"},{"id":"zz-3q4","n":4,"s":"尊重自然、顺应自然、保护自然，是全面建设社会主义现代化国家的内在要求。必须牢固树立和践行绿水青山就是金山银山的理念，站在人与自然和谐共生的高度谋划发展。下列相关举措，说法正确的有几项？\n①推动经济社会发展绿色化、低碳化是实现高质量发展的关键环节\n②要全面实行排污许可制，健全现代环境治理体系\n③要以国家重点生态功能区、生态保护红线、自然保护地等为重点，加快实施重要生态系统保护和修复重大工程\n④要立足我国能源资源禀赋，坚持先立后破，毕其功于一役打赢碳达峰攻坚战","o":["1项","2项","3项","4项"],"a":"C","e":"④说法错误：实现碳达峰碳中和是一场广泛而深刻的经济社会系统性变革。立足我国能源资源禀赋，坚持先立后破，有计划分步骤实施碳达峰行动。①②③说法正确。故本题答案为C。"},{"id":"zz-3q5","n":5,"s":"人民民主是社会主义的生命，是全面建设社会主义现代化国家的应有之义。必须坚定不移走中国特色社会主义政治发展道路，坚持党的领导、人民当家作主、依法治国有机统一。下列相关说法，正确的有几项？\n①要支持和保证人民通过人民代表大会行使国家权力，保证各级人大都由民主选举产生、对人民负责、受人民监督\n②要发挥人民政协作为专门监察机关作用，完善民主监督和委员联系界别群众制度机制\n③要健全以职工代表大会为基本形式的企事业单位民主管理制度，维护职工合法权益\n④要以铸牢中华民族共同体意识为主线，坚定不移走中国特色解决民族问题的正确道路，坚持和完善民族区域自治制度","o":["1项","2项","3项","4项"],"a":"C","e":"②说法错误：要发挥人民政协作为专门协商机构作用，加强制度化、规范化、程序化等功能建设，提高深度协商互动、意见充分表达、广泛凝聚共识水平，完善人民政协民主监督和委员联系界别群众制度机制。①③④说法正确。故本题答案为C。"},{"id":"zz-3q6","n":6,"s":"党的十八大以来，我们不断推进金融实践创新、理论创新、制度创新，积累了宝贵经验，逐步走出一条中国特色金融发展之路。下列相关举措，说法正确的是：","o":["坚持把金融服务实体经济作为根本宗旨，坚持把防控风险作为金融工作的永恒主题","我国金融体系的重要特征和优势是民营金融机构占主体，但存在间接融资和债权融资比重偏高、金融服务普惠性不足等问题","我国金融机构门类齐全，关键是要同质发展、优势互补，要各司其职、各展所长","金融具有功能性和盈利性双重属性，功能发挥要服从盈利目标"],"a":"A","e":"B项说法错误：我国金融体系的重要特征和优势是国有金融机构占主体，但存在间接融资和债权融资比重偏高、金融服务普惠性不足等问题，还存在金融泛化、乱办金融、大量非法金融活动。C项说法错误：我国金融机构门类齐全，关键是要错位发展、优势互补，在服务实体经济上各司其职、各展所长。D项说法错误：金融具有功能性和盈利性双重属性，盈利要服从功能发挥。故本题答案为A。"},{"id":"zz-3q7","n":7,"s":"全面建设社会主义现代化国家，必须坚持中国特色社会主义文化发展道路，增强文化自信，围绕举旗帜、聚民心、育新人、兴文化、展形象建设社会主义文化强国。下列相关说法，正确的有几项？\n①要以全人类共同价值为引领，发展社会主义先进文化，弘扬革命文化，传承中华优秀传统文化\n②意识形态工作是为国家立心、为民族立魂的工作，要牢牢掌握党对意识形态工作领导权\n③要弘扬以伟大长征精神为源头的中国共产党人精神谱系，用好红色资源\n④要坚守中华文化立场，提炼展示中华文明的精神标识和文化精髓，加快构建中国话语和中国叙事体系，讲好中国故事、传播好中国声音，展现可信、可爱、可敬的中国形象","o":["1项","2项","3项","4项"],"a":"B","e":"①说法错误：以社会主义核心价值观为引领，发展社会主义先进文化，弘扬革命文化，传承中华优秀传统文化。③说法错误：弘扬以伟大建党精神为源头的中国共产党人精神谱系，用好红色资源，深入开展社会主义核心价值观宣传教育，深化爱国主义、集体主义、社会主义教育，着力培养担当民族复兴大任的时代新人。②④说法正确。故本题答案为B。"},{"id":"zz-3q8","n":8,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。下列属于持之以恒推进全面从严治党遵循的原则是：\n①坚持服务使命任务，坚持以党的政治建设为统领\n②坚持全面从严，坚持问题导向\n③坚持守正创新，坚持以上率下\n④坚持从严治吏，坚持依宪治党","o":["①②③④","①②③","①③④","②③④"],"a":"B","e":"④选项的“坚持从严治党”说法本身正确，但全会并未将其纳入持之以恒推进全面从严治党遵循的七大原则范畴，且“坚持依宪治党”说法错误。小黑提示，“国有宪法，党有党章”。小黑在出题的时候故意将“坚持依规治党”替换为“坚持依宪治党”，为了“骗取”同学们的注意力，还专门加入了“坚持从严治党”。①②③说法正确：全会强调，持之以恒推进全面从严治党遵循的原则是：坚持服务使命任务，坚持以党的政治建设为统领，坚持全面从严治党，坚持问题导向，坚持守正创新，坚持以上率下，坚持依规治党。故本题答案为B。"},{"id":"zz-3q9","n":9,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。下列说法正确的有几项？\n①习近平党建思想回答了“建设什么样的党、怎样建设党”的重大时代课题\n②增强党性是全面从严治党的根本性任务，要把学习、领悟、运用党的创新理论作为加强党性修养的根本途径\n③民主集中制是党的根本组织原则和领导制度，是我们党区别于其他政党的重要标志\n④纪律建设作为全面从严治党的治本之策，要始终以严的基调正风肃纪\n⑤一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本方针","o":["2项","3项","4项","5项"],"a":"C","e":"①说法错误：习近平党建思想回答的重大时代课题是“建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党”。“建设什么样的党、怎样建设党”是“三个代表”重要思想回答的课题。②③④⑤说法正确。故本题答案为C。"},{"id":"zz-3q10","n":10,"s":"2026年10月12日至13日，全国卫生与健康大会在京召开。习近平总书记出席会议并发表重要讲话。讲话指出，改革是卫生与健康事业发展的强大动力。下列相关说法，正确的是：","o":["要坚持把推进医疗、医保、医药独立发展和治理作为医药卫生体制改革的主攻方向","要以市场化为导向深化公立医院改革，加强县区、基层医疗机构运行保障","要构建多层次医疗保障体系，优化药品耗材分级采购、医保支付和资金使用政策，实现基金安全运行、医院良性运转、群众负担合理","要健全药品供应保障和使用管理机制，完善国家基本药物制度，强化药品质量安全监管"],"a":"D","e":"A项说法错误：要坚持把推进医疗、医保、医药协同发展和治理作为医药卫生体制改革的主攻方向。B项说法错误：全面落实医疗卫生事业单位改革方案，以公益性为导向深化公立医院改革，加强县区、基层医疗机构运行保障。C项说法错误：要构建多层次医疗保障体系，优化药品耗材集中采购、医保支付和资金使用政策，实现基金安全运行、医院良性运转、群众负担合理。故本题答案为D。"},{"id":"zz-3q11","n":11,"s":"2026年10月9日，《中共中央国务院关于发展新质生产力的意见》发布。下列相关说法正确的是：","o":["在国家重大工程项目中按需部署科技任务，健全需求导向的选题制度、责权利一致的管理制度、应用导向的评价制度","更好发挥社会投资基金引导带动作用，完善长期资本投早、投小、投长期、投硬科技的支持政策，壮大耐心资本","强化跨部门联合监管，创新监管方式，增加现场监管次数，探索“用数据决策、用数据管理”监管模式","加快推动科研人员考核评价激励与报项目、发论文、评奖励等紧密挂钩，防止简单按人才“帽子”定薪酬、定职称、定待遇"],"a":"A","e":"B项说法错误：更好发挥政府投资基金引导带动作用，完善长期资本投早、投小、投长期、投硬科技的支持政策，壮大耐心资本。C项说法错误：强化跨部门联合监管，创新监管方式，减少现场监管次数，探索“用数据决策、用数据管理”监管模式，提升跨部门综合监管智能化水平。D项说法错误：加快推动科研人员考核评价激励与报项目、发论文、评奖励等适度脱钩，防止简单按人才“帽子”定薪酬、定职称、定待遇。故本题答案为A。"},{"id":"zz-3q12","n":12,"s":"2026年10月21日，《中共中央办公厅国务院办公厅关于推动科技创新和产业创新深度融合的意见》发布。《意见》指出，推动科技创新和产业创新深度融合，是以高水平科技自立自强引领发展新质生产力的关键。下列相关说法，正确的有几项？\n①坚持准确把握科技革命和产业变革新趋势新特点，加强系统谋划和分类推进\n②坚持统筹科技供给和需求牵引，围绕产业链部署创新链，围绕创新链布局产业链\n③坚持强化科研院所创新主体地位，完善激励创新的市场机制，推动创新资源向科研院所集聚\n④坚持以改革激发创新活力，坚决破除阻碍科技创新和产业创新深度融合发展的思想观念和制度障碍","o":["1项","2项","3项","4项"],"a":"B","e":"①说法错误：坚持准确把握科技革命和产业变革新趋势新特点，加强系统谋划和一体推进。③说法错误：坚持强化企业创新主体地位，完善激励创新的市场机制，推动创新资源向企业集聚。②④说法正确。故本题答案为B。"},{"id":"zz-3q13","n":13,"s":"《2026年政府工作报告》指出，要坚持民生为大，加强普惠性、基础性、兜底性民生建设，努力为人民群众多办实事。下列说法正确的有几项？\n①实施稳岗扩容提质行动，支持劳动密集型行业企业稳定岗位\n②推动基础教育扩优提质，统筹义务教育优质均衡发展、学前教育优质普惠发展，完善免费学前教育政策，增加普通高中学位供给\n③加强初婚初育家庭住房保障，支持多子女家庭改善性住房需求\n④完善并落实基本养老保险全国统筹制度，稳步推动基本医疗保险省级统筹","o":["1项","2项","3项","4项"],"a":"D","e":"①②③④说法均正确。故本题答案为D。"},{"id":"zz-3q14","n":14,"s":"2026年1月，中共中央政治局就前瞻布局和发展未来产业进行第二十四次集体学习。关于未来产业的发展，下列说法正确的是：","o":["要综合考虑国家战略需求、技术成熟程度、要素支撑条件等因素，因地制宜、同质发展","要充分发挥新型举国体制优势，坚持“科技出题、产业答题”","要完善财税等政策，以发展绿色金融为重点促进未来产业发展","要加强基础研究战略性、前瞻性、体系化布局，加快科技成果转化应用"],"a":"D","e":"A项说法错误：要综合考虑国家战略需求、技术成熟程度、要素支撑条件等因素，因地制宜、错位发展。B项说法错误：要充分发挥新型举国体制优势，坚持“产业出题、科技答题”，加大重点领域关键核心技术攻关力度。C项说法错误：要完善财税等政策，大力发展科技金融。绿色金融和未来产业无关，绿色金融是指为支持环境改善、应对气候变化和资源高效利用的经济活动提供的金融服务，涵盖环保、节能、清洁能源、绿色交通等领域。故本题答案为D。"},{"id":"zz-3q15","n":15,"s":"2026年7月1日，庆祝中国共产党成立105周年大会在京举行。习近平总书记指出，中国共产党之所以能够在105年奋斗中不断铸就辉煌，历史和人民之所以选择中国共产党，根本在于我们党具有其他政党和政治力量无可比拟的优秀特质。下列属于这些优秀特质的是：\n①矢志追求真理、始终把准前进方向\n②深深植根人民、始终拥有坚实根基\n③勇担历史使命、始终掌握战略主动\n④顺应发展潮流、始终走在时代前列\n⑤敢于善于斗争、始终保持必胜信心\n⑥注重强健自身、始终充满生机活力","o":["②③④⑤","①②③④","③④⑤⑥","①②③④⑤⑥"],"a":"D","e":"①②③④⑤⑥均属于。故本题答案为D。"},{"id":"zz-3q16","n":16,"s":"2026年9月1日，习近平总书记在“上海合作组织+”会议上发表讲话指出，中国作为负责任大国，积极倡导平等有序的世界多极化。主权平等、相互尊重是根本原则，均衡有序、遵守法治是必然要求，多边主义、对话协商是关键路径，互利共赢、普惠包容是发展方向。下列说法正确的有几项？\n①要坚持各国无论大小、强弱、贫富，都权利平等、机会平等、规则平等\n②要弘扬社会主义核心价值观，摒弃双重标准、例外主义、干涉霸凌、丛林法则，推进国际关系法治化\n③联合国宪章宗旨和原则确立了国际关系基本准则，是战后国际秩序的基石\n④要聚焦发展议题，坚持开放合作，弥合数字和智能鸿沟，让技术革命和发展成果惠及各国人民\n⑤要坚持对话不对抗、结伴又结盟，坚持共商共建共享，推动各国在全球治理中平等参与、普遍受益","o":["5项","4项","3项","2项"],"a":"C","e":"②说法错误：要弘扬全人类共同价值，摒弃双重标准、例外主义、干涉霸凌、丛林法则，推进国际关系法治化。⑤说法错误：要坚持结伴不结盟、对话不对抗，坚持共商共建共享，推动各国在全球治理中平等参与、普遍受益。①③④说法正确。故本题答案为C。"},{"id":"zz-3q17","n":17,"s":"中国共产党在百年奋斗历程中铸就了一系列伟大精神，构建起中国共产党人的精神谱系。新时代以来，习近平总书记多次号召全党全社会传承弘扬这些宝贵精神，强调要从中汲取奋进力量，赓续红色血脉，将其转化为全面建设社会主义现代化国家、全面推进中华民族伟大复兴的强大精神动力。下列精神与其内涵对应正确的是：","o":["焦裕禄精神——互信、互利、平等、协商、尊重多样文明、谋求共同发展","西迁精神——胸怀大局、无私奉献、弘扬传统、艰苦创业","伟大建党精神——亲民爱民、艰苦奋斗、科学求实、迎难而上、无私奉献","伟大长征精神——坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民"],"a":"B","e":"A项说法错误：焦裕禄精神的内涵是“亲民爱民、艰苦奋斗、科学求实、迎难而上、无私奉献”。“互信、互利、平等、协商、尊重多样文明、谋求共同发展”描述的是上海精神。C项说法错误：伟大建党精神的内涵是“坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民”。D项说法错误：伟大长征精神就是把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信念，坚信正义事业必然胜利；为了救国救民，不怕任何艰难险阻，不惜付出一切牺牲；坚持独立自主、实事求是，一切从实际出发；顾全大局、严守纪律、紧密团结；紧紧依靠人民群众，同人民群众生死相依、患难与共、艰苦奋斗。故本题答案为B。"},{"id":"zz-3q18","n":18,"s":"2026年2月，《中共中央国务院关于锚定农业农村现代化扎实推进乡村全面振兴的意见》发布。文件指出，要实施常态化精准帮扶。下列表述正确的是：","o":["把常态化帮扶纳入乡村振兴战略统筹实施，保持财政投入、金融支持、资源要素配置等方面政策逐步降低","强化救济式帮扶，发挥社会救助兜底保障作用，推动帮扶政策协同集成","优化产业帮扶方式，分类推进现有产业巩固、升级、盘活、调整，发展具有市场竞争力的帮扶产业","扎实做好市县两级常态化监测，健全精准识别和快速响应机制，确保早发现、早干预、早帮扶"],"a":"C","e":"A项说法错误：把常态化帮扶纳入乡村振兴战略统筹实施，保持财政投入、金融支持、资源要素配置等方面政策总体稳定。B项说法错误：强化开发式帮扶，增强内生动力，发挥社会救助兜底保障作用，推动帮扶政策协同集成。D项说法错误：扎实做好乡村两级常态化监测，健全精准识别和快速响应机制。故本题答案为C。"},{"id":"zz-3q19","n":19,"s":"由常住地提供基本公共服务，逐步消除基本公共服务与户籍挂钩因素，促进未落户常住人口与户籍人口同等享有基本公共服务，有利于满足人民日益增长的美好生活需要，对提升城镇化质量、释放国内需求潜力、构建新发展格局具有重要意义。下列相关举措，说法正确的有几项？\n①学龄人口流入多的城市政府做好存量学位资源挖潜和整合利用，按需新增学位，巩固提升义务教育阶段随迁子女就读民办学位比例\n②推动更多城市将稳定就业居住的未落户常住人口家庭纳入公租房保障范围，推行按就业居住年限、住房困难程度确定保障对象、保障方式、保障标准、准入条件和退出机制\n③全面取消在就业地参加职工社会保险的户籍限制，大力推进全民参保计划，引导支持各类劳动者在就业地参加职工社会保险\n④加力落实持户口簿参加城乡居民基本医疗保险政策，超大特大城市等各类城市切实保障户籍地中小学生、学龄前儿童等在常住地参加城乡居民基本医疗保险的权利\n⑤对符合条件的城镇常住人口依申请认定为就业困难人员，按规定落实就业援助政策","o":["5项","4项","3项","2项"],"a":"C","e":"①说法错误：学龄人口流入多的城市政府做好存量学位资源挖潜和整合利用，按需新增学位，巩固提升义务教育阶段随迁子女就读公办学位比例。④说法错误：加力落实持居住证参加城乡居民基本医疗保险政策，超大特大城市等各类城市切实保障外地户籍中小学生、学龄前儿童等在常住地参加城乡居民基本医疗保险的权利。②③⑤说法正确。故本题答案为C。"},{"id":"zz-3q20","n":20,"s":"习近平总书记指出，2026年是“十五五”开局之年，地方各级领导班子将陆续换届，通过学习教育推动各级领导班子和领导干部树立和践行正确政绩观，十分重要，很有必要。下列相关说法正确的是：","o":["要以立党为公、为民造福、科学决策、真抓实干为总要求，以分类推进学查改为抓手","要坚持聚焦主题、简约务实，划分批次、划分阶段，认真落实学习研讨、查摆问题、整改整治、建章立制、开门教育等工作安排","要坚持实事求是、求真务实，为人民出政绩、以实干出政绩","要坚持与中央巡察整改、深入贯彻中央八项规定精神学习教育整改、“十五五”规划编制实施、生态环保督察整改等相结合"],"a":"C","e":"A项说法错误：要以立党为公、为民造福、科学决策、真抓实干为总要求，以一体推进学查改为抓手。B项说法错误：学习教育要坚持聚焦主题、简约务实，不分批次、不划阶段，认真落实学习研讨、查摆问题、整改整治、建章立制、开门教育等工作安排。D项说法错误：要坚持与中央巡视整改、深入贯彻中央八项规定精神学习教育整改、“十五五”规划编制实施、生态环保督察整改等相结合，边查边改、立行立改，对突出问题开展集中整治，持续推动整改落实。故本题答案为C。"}]},{"id":"zz-4","cat":"zz","title":"小黑模考五套卷 · 第四套","short":"第四套","sub":"20 题","questions":[{"id":"zz-4q1","n":1,"s":"2026年8月，习近平总书记作出重要指示强调，树立和践行正确政绩观是一项长期任务，必须久久为功，不断巩固拓展学习教育成果，持续推动各级党组织和广大党员、干部立党为公、为民造福、科学决策、真抓实干，努力创造经得起实践、人民、历史检验的实绩。上述指示蕴含的哲学道理是：\n①量变是质变的必要准备，干事创业要重视量的积累\n②人民群众是历史的主体，要坚持以人民为中心的价值立场\n③实践是检验认识真理性的唯一标准，政绩要经受实践的检验\n④发挥主观能动性是尊重客观规律的前提，要做到科学决策真抓实干","o":["①②③","①③","②③④","②④"],"a":"A","e":"①符合题意：“树立和践行正确政绩观是一项长期任务，必须久久为功”体现量变与质变辩证关系，伟大事业需要持续积累，重视量的不断积累，方能促成事业质变。②符合题意：“立党为公、为民造福”体现唯物史观，人民群众是社会历史的创造者，要求我们坚持人民立场，把维护人民利益作为价值追求。③符合题意：“创造经得起实践、人民、历史检验的实绩”，表明实践是检验认识真理性的唯一标准，工作成效最终要交由实践来评判。④说法错误：尊重客观规律是正确发挥主观能动性的前提和基础。故本题答案为A。"},{"id":"zz-4q2","n":2,"s":"习近平总书记强调，改革是利益格局调整的过程，不可能同时满足所有人的利益诉求。要引导干部、群众增强大局意识，正确对待改革中的利益关系调整和个人利害得失。下列选项体现的哲学道理与题干最为一致的是：","o":["牢固树立全国一盘棋思想，坚持小道理服从大道理、地方利益服从国家整体利益","改革要做到“蹄疾而步稳”，困难要一个一个克服，问题要一个一个解决","一分部署，九分落实，抓落实是做好一切工作的基础","坚持人民至上，从人民整体利益、根本利益、长远利益出发谋划和推进改革"],"a":"A","e":"A项符合题意：题干体现整体与部分的辩证关系原理，整体居于主导地位，统率着部分，要求树立大局意识，个人、局部利益要服从改革发展的整体利益。“牢固树立全国一盘棋思想，坚持小道理服从大道理、地方利益服从国家整体利益”，强调局部服从全局，正确处理局部利益同整体利益的关系，与题干哲学道理高度契合。B项不符合题意：“改革要做到‘蹄疾而步稳’，困难要一个一个克服，问题要一个一个解决”体现量变与质变的辩证关系，重视量的积累。C项不符合题意：“一分部署，九分落实，抓落实是做好一切工作的基础”突出实践的重要作用，强调把思想方案转化为客观现实。D项不符合题意：“坚持人民至上，从人民整体利益、根本利益、长远利益出发谋划和推进改革”体现的是人民群众是历史的创造者，要坚持群众观点和群众路线。故本题答案为A。"},{"id":"zz-4q3","n":3,"s":"《微短剧发展管理办法》自2026年9月1日起正式施行。该《办法》针对微短剧“单集短、传播快、AI 参与、部分内容低俗擦边”等新特点，将微短剧按投资额度与题材分为三类，实行差异化备案与审核，划定11条内容红线，同时鼓励微短剧赋能千行百业、支持群众创作与技术创新。上述内容蕴含的哲学道理是：\n①社会存在决定社会意识，社会意识对社会存在具有反作用\n②矛盾具有特殊性，要坚持具体问题具体分析\n③坚持一切从实际出发，做到主观与客观具体的历史的统一\n④辩证否定的实质是新事物的产生和旧事物的灭亡","o":["①②③","①②④","①③④","②③④"],"a":"A","e":"①符合题意：针对微短剧出现的新特点新问题出台《微短剧发展管理办法》体现社会存在决定社会意识；该办法规范行业、鼓励创新发展，体现社会意识对社会存在具有反作用。②符合题意：将微短剧按投资额度与题材分为三类，实行差异化备案与审核，体现矛盾具有特殊性，要坚持具体问题具体分析。③符合题意：面对微短剧单集短、传播快、AI参与等新情况制定管理规则，做到了主观与客观具体的历史的统一。④说法错误：辩证否定的实质是“扬弃”，“新事物的产生和旧事物的灭亡”是发展的实质。故本题答案为A。"},{"id":"zz-4q4","n":4,"s":"2026年7月，第13期《求是》杂志发表习近平总书记重要文章《做焦裕禄式的县委书记》。文章指出，做焦裕禄式的县委书记要做到心中有党、心中有民、心中有责、心中有戒。下列相关说法，不正确的是：","o":["衡量一个县委书记当得怎么样，主要是看对党忠诚这一条","要把理论学习作为基本功，深入基层、深入群众、深入实际，了解情况、问计于民","要有“功成不必在我”的境界，一张好的蓝图，只要是科学的、切合实际的、符合人民愿望的，就要像接力赛一样，一棒一棒接着干下去","要正确行使权力，依法用权、秉公用权、廉洁用权，处理好公和私、情和法、利和法的关系"],"a":"B","e":"B项说法错误：要把调查研究作为基本功，深入基层、深入群众、深入实际，了解情况、问计于民。A、C、D项说法正确。故本题答案为B。"},{"id":"zz-4q5","n":5,"s":"为民造福是立党为公、执政为民的本质要求。必须坚持在发展中保障和改善民生，鼓励共同奋斗创造美好生活，不断实现人民对美好生活的向往。下列相关举措，说法正确的是：","o":["加大税收、社会保障、转移支付等初次分配的调节力度","完善按要素分配政策制度，探索多种渠道增加中低收入群众要素收入，多渠道增加城乡居民财产性收入","努力提高居民收入在国民收入分配中的比重，提高劳动报酬在再分配中的比重","刚性要求有意愿有能力的企业、社会组织和个人积极参与公益慈善事业"],"a":"B","e":"A项说法错误：加大税收、社会保障、转移支付等再分配的调节力度。C项说法错误：努力提高居民收入在国民收入分配中的比重，提高劳动报酬在初次分配中的比重。D项说法错误：引导、支持有意愿有能力的企业、社会组织和个人积极参与公益慈善事业。故本题答案为B。"},{"id":"zz-4q6","n":6,"s":"如期实现建军一百年奋斗目标，加快把人民军队建成世界一流军队，是全面建设社会主义现代化国家的战略要求。下列相关举措，说法正确的有几项？\n①“十五五”时期要如期实现建军一百年奋斗目标、高质量推进国防和军队现代化，必须坚持好、运用好、发展好改革强军这个重要法宝，毫不动摇坚持和加强党对军队绝对领导，凝心聚力推动国防和军队现代化行稳致远\n②完成“十五五”时期国防和军队现代化目标任务，归根到底要靠各级政府来领导和推进\n③要加强我军党的领导和党的建设，选准配强高层党委班子，增强基层党组织自主抓建能力\n④要完善促进人才发展的制度和条件，体系推进联合作战指挥、新型作战力量、高层次科技创新、高水平战略管理“四类人才”培养，实现人的能力素质同强军实践协调发展\n⑤要传承和弘扬我党我军优良传统，推进新时代强军文化建设，加强先进典型培养和激励","o":["2项","3项","4项","5项"],"a":"B","e":"①说法错误：“十五五”时期要如期实现建军一百年奋斗目标、高质量推进国防和军队现代化，必须坚持好、运用好、发展好政治建军这个重要法宝，毫不动摇坚持和加强党对军队绝对领导，充分发挥政治建军特有优势，凝心聚力推动国防和军队现代化行稳致远。②说法错误：完成“十五五”时期国防和军队现代化目标任务，归根到底要靠各级党组织来领导和推进。③④⑤说法正确。故本题答案为B。"},{"id":"zz-4q7","n":7,"s":"习近平总书记指出，立足新发展阶段、贯彻新发展理念、构建新发展格局，推动高质量发展，是当前和今后一个时期全党全国必须抓紧抓好的工作。下列相关说法，正确的有几项？\n①新发展阶段是决胜全面建成小康社会，进而向第二个百年奋斗目标进军的关键阶段\n②创新是引领发展的第一动力，注重解决的是发展动力问题\n③要构建以国内大循环为主体、国内国际双循环相互促进的新发展格局\n④构建新发展格局意味着各省要实施特殊的区域优惠政策","o":["1项","2项","3项","4项"],"a":"B","e":"①说法错误：新发展阶段是全面建成小康社会、实现第一个百年奋斗目标之后，乘势而上开启全面建设社会主义现代化国家新征程、向第二个百年奋斗目标进军的阶段。“决胜全面建成小康社会”属于此前阶段的任务，时间节点错误。④说法错误：构建新发展格局不是各省单独搞特殊优惠政策，核心是畅通国民经济循环、全国统一大市场，不是各省各自出台特殊优惠。②③说法正确。故本题答案为B。"},{"id":"zz-4q8","n":8,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。下列属于对持之以恒推进全面从严治党作出系统部署的战略任务的有几项？\n①增强共产党人的党性\n②严格贯彻执行人民代表大会制度\n③锻造堪当民族复兴重任的高素质干部队伍\n④建设上下贯通、执行有力的严密组织体系\n⑤坚定不移一体推进不敢腐不能腐不想腐","o":["2项","3项","4项","5项"],"a":"C","e":"①③④⑤均属于：全会部署了持之以恒推进全面从严治党的战略任务，包括增强共产党人的党性，严格贯彻执行民主集中制，锻造堪当民族复兴重任的高素质干部队伍，建设上下贯通、执行有力的严密组织体系，驰而不息正风肃纪，坚定不移一体推进不敢腐不能腐不想腐，坚持制度治党、依规治党等7个部分。②说法错误：应为“严格贯彻执行民主集中制”，小黑将“民主集中制”替换为“人民代表大会制度”，人民代表大会制度是我国根本政治制度，但不属于党内制度，所以不选。故本题答案为C。"},{"id":"zz-4q9","n":9,"s":"2026年10月22日，纪念中国工农红军长征胜利90周年大会在京隆重举行。习近平总书记指出，红军长征粉碎上百万敌军围追堵截，宣告国民党反动派消灭中国共产党和红军的图谋彻底失败，胜利实现北上抗日的战略转移，成功开创了中国革命新局面。关于长征胜利的主要原因，下列说法正确的有几项？\n①依靠中国共产党的正确领导\n②红军将士坚定的革命意志与理想信念\n③依靠共产国际力量持续、及时的军事指导\n④我党坚持独立自主、实事求是\n⑤广大人民群众的衷心拥护和大力支持","o":["2项","3项","4项","5项"],"a":"C","e":"①②④⑤说法均正确：习近平总书记强调，90年后的今天，再次回望那段苦难辉煌，我们更加深刻认识到，长征胜利是必然的，其中蕴含着党和人民军队铿锵前进的制胜之道。这一伟大胜利之路，是依靠党的正确领导走出来的，党的正确领导和毛泽东同志核心地位的确立，对于红军长征胜利具有决定性意义。这一伟大胜利之路，是依靠坚定的革命意志走出来的，革命理想、革命信念能够迸发出克顽敌、撼山岳的无穷力量，具有崇高理想和坚定信念的队伍是不可战胜的。这一伟大胜利之路，是依靠独立自主、实事求是走出来的，马克思主义基本原理只有同中国具体实际紧密结合，才能解决中国的问题，才能展现出强大生命力。这一伟大胜利之路，是依靠广大人民群众支持走出来的，人民群众永远是党和人民军队的力量源泉和坚强后盾，只要我们深深植根人民、始终保持同人民群众的血肉联系，党的事业就无往而不胜。③说法错误：长征途中，党逐步摆脱共产国际遥控指挥，走上独立自主解决中国革命问题的道路，并非依靠共产国际持续直接军事指导。故本题答案为C。"},{"id":"zz-4q10","n":10,"s":"2026年10月12日至13日，全国卫生与健康大会在京召开。习近平总书记出席会议并发表重要讲话。下列相关说法，正确的有几项？\n①卫生与健康事业具有全局性、基础性作用，必须坚定实施健康优先发展战略\n②健全疾病防控体系，守牢不发生规模性疫情的底线\n③营造良好生态环境和生产生活环境，鼓励和支持全民健身、健康休闲\n④引导全社会树立正确健康观，进行有效的健康自塑和管理\n⑤及时治疗是最经济最有效的健康策略，要抓细抓好卫生与健康各项基础性、源头性工作","o":["2项","3项","4项","5项"],"a":"C","e":"⑤说法错误：预防是最经济最有效的健康策略，要抓细抓好卫生与健康各项基础性、源头性工作，夯实全民健康根基。①②③④说法正确。故本题答案为C。"},{"id":"zz-4q11","n":11,"s":"2026年10月9日，《中共中央国务院关于发展新质生产力的意见》发布。《意见》指出，要推动科技创新和产业创新深度融合。下列相关说法正确的是：","o":["深化产业内、产品内专业分工，促进跨行业跨区域融合，避免“内卷式”竞争","以产业链为主导、以政府为主体建立跨区域产业协作机制，支持东部地区带动中西部和东北地区因地制宜发展新兴产业","实施“西数东算”、智能制造、工业互联网创新发展等工程，建设全国一体化算力网、国家区块链网络","规范统一、分业施策布局国家人工智能行业应用中试基地和高价值应用场景"],"a":"A","e":"B项说法错误：以产业链为主导、以企业为主体建立跨区域产业协作机制，支持东部地区带动中西部和东北地区因地制宜发展新兴产业。C项说法错误：实施“东数西算”、智能制造、工业互联网创新发展等工程，建设全国一体化算力网、国家区块链网络。D项说法错误：因地制宜、分业施策布局国家人工智能行业应用中试基地和高价值应用场景，大力推动人工智能在各行业应用。故本题答案为A。"},{"id":"zz-4q12","n":12,"s":"2026年10月21日，《中共中央办公厅国务院办公厅关于推动科技创新和产业创新深度融合的意见》发布。《意见》指出，要促进创新链产业链无缝对接。下列属于相关措施的是：\n①加强科技、产业、金融、教育、人才等政策协同\n②支持高校、科研院所设立技术转移机构或岗位，强化创业孵化等专业化服务\n③实施新技术新产品新场景应用示范行动，加大场景培育和开放力度\n④健全“应用考核技术、市场考核产品”的项目验收机制，加强研发目标和产业化目标分类考核","o":["①②③","①②④","①③④","②③④"],"a":"A","e":"④说法错误：健全“应用考核技术、市场考核产品”的项目验收机制，加强研发目标和产业化目标一体考核。①②③说法正确。故本题答案为A。"},{"id":"zz-4q13","n":13,"s":"2026年1月，中国共产党第二十届中央纪律检查委员会第五次全体会议召开。全会强调，“十五五”时期是基本实现社会主义现代化夯实基础、全面发力的关键时期，全面从严治党面临新的形势任务。下列对于纪检监察机关的要求，说法正确的有几项？\n①要深刻把握实现“十五五”时期目标任务对维护党的团结统一提出的更高要求，坚定不移推动全党拥护“两个确立”、做到“两个维护”\n②要深刻把握实现“十五五”时期目标任务对把权力关进制度笼子提出的更高要求，坚定不移强化制度治权、依规用权\n③要深刻把握实现“十五五”时期目标任务对保持党的先进性纯洁性提出的更高要求，坚定不移走好中国特色反腐败之路\n④要深刻把握实现“十五五”时期目标任务对激励担当作为提出的更高要求，坚定不移促进党员干部在遵规守纪中干事创业","o":["1项","2项","3项","4项"],"a":"D","e":"①②③④说法均正确。故本题答案为D。"},{"id":"zz-4q14","n":14,"s":"2026年4月28日，中共中央政治局就提高防灾减灾救灾能力进行第二十五次集体学习。下列相关表述，正确的有几项？\n①降低灾害风险，减轻灾害损失，重在事前预防，要坚持末端管控，将安全韧性要求贯穿国土空间规划及各类建设规划之中\n②基层是抵御自然灾害的第一线，抓基层、强基础的工作始终不能放松\n③要坚决纠正重发展轻安全、重救灾轻预防等倾向\n④要树牢底线思维、极限思维，不断提升大灾巨灾应对处置能力\n⑤各地区各有关部门要守土尽责，坚持统分结合、防救分离、上下联动","o":["5项","4项","3项","2项"],"a":"C","e":"①说法错误：降低灾害风险，减轻灾害损失，重在事前预防，要坚持源头管控，将安全韧性要求贯穿国土空间规划及各类建设规划之中。⑤说法错误：各地区各有关部门要守土尽责，坚持统分结合、防救衔接、上下联动。②③④说法正确。故本题答案为C。"},{"id":"zz-4q15","n":15,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。持之以恒推进全面从严治党，是我们党作为马克思主义执政党所承担的使命和责任决定的。下列属于持之以恒推进全面从严治党重要意义的是：\n①是保持党的先进性和纯洁性、巩固党的长期执政地位的必然要求\n②是巩固和发展全党高度团结统一、党心军心民心高度凝聚良好政治局面的必然要求\n③是实现党的历史使命、推动党和国家事业行稳致远的必然要求\n④是坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化的必然要求","o":["①②③","①②④","①③④","②③④"],"a":"A","e":"①②③属于，④不属于：《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》强调，持之以恒推进全面从严治党，是我们党作为马克思主义执政党所承担的使命和责任决定的，是保持党的先进性和纯洁性、巩固党的长期执政地位的必然要求，是巩固和发展全党高度团结统一、党心军心民心高度凝聚良好政治局面的必然要求，是实现党的历史使命、推动党和国家事业行稳致远的必然要求。故本题答案为A。"},{"id":"zz-4q16","n":16,"s":"2026年10月9日，《中共中央国务院关于发展新质生产力的意见》发布。《意见》指出，要大力推进科技创新。下列相关说法正确的是：","o":["坚持基础研究从目标导向转变为自由探索，支持自由探索类基础研究开拓创新","统筹国家战略科技力量建设，以经济发展需求为导向，优化国家科研机构、高水平研究型大学、科技领军企业定位","探索建立科技项目全过程评价机制，立项时分阶段部署研发和转化任务，验收时考核应用实绩，解决技术开发与成果转化脱节问题","引导高等学校、科研院所按照先使用后付费方式把科技成果许可给中小微企业使用"],"a":"D","e":"A项说法错误：坚持目标导向和自由探索并重，通过有组织的基础研究、应用基础研究解决技术科学和工程科学薄弱问题，支持自由探索类基础研究开拓创新。B项说法错误：统筹国家战略科技力量建设，以国家战略需求为导向，优化国家科研机构、高水平研究型大学、科技领军企业定位和布局。C项说法错误：探索建立科技项目全过程评价机制，立项时一体部署研发和转化任务，验收时考核应用实绩，解决技术开发与成果转化脱节问题。故本题答案为D。"},{"id":"zz-4q17","n":17,"s":"党的十八大以来，我国先进制造业不断发展壮大，创新力、竞争力、综合实力显著增强，制造强国建设迈出坚实步伐。下列相关说法，错误的是：","o":["要顺应新一轮科技革命和产业变革趋势，以新一代智能制造为主攻方向，着力推动制造业智能化、绿色化、融合化发展","要加快构建以先进制造业为骨干的现代化产业体系，巩固壮大实体经济根基","要做大做强先进制造业，发展策略上更加注重数智赋能，技术路线上更加注重高端引进，生产方式上更加注重绿色低碳，场景业态上更加注重跨界融合","要因地制宜培育壮大先进制造业集群，分类分层推动提质升级"],"a":"C","e":"C项说法错误：要做大做强先进制造业，发展策略上更加注重数智赋能，技术路线上更加注重高端自主，生产方式上更加注重绿色低碳，场景业态上更加注重跨界融合，着力推动制造业智能化、绿色化、融合化发展。故本题答案为C。"},{"id":"zz-4q18","n":18,"s":"2026年2月，《中共中央国务院关于锚定农业农村现代化扎实推进乡村全面振兴的意见》发布。文件指出，要实施常态化精准帮扶。下列属于相关措施的有几项？\n①健全常态化帮扶政策体系\n②提高监测帮扶精准性时效性\n③提升产业和就业帮扶实效\n④集中统一帮扶欠发达地区\n⑤加强耕地保护和质量提升","o":["2项","3项","4项","5项"],"a":"B","e":"①②③说法正确，④说法错误：根据《中共中央 国务院关于锚定农业农村现代化 扎实推进乡村全面振兴的意见》，实施常态化精准帮扶的举措有：健全常态化帮扶政策体系、提高监测帮扶精准性时效性、提升产业和就业帮扶实效、分层分类帮扶欠发达地区。⑤属于“提升农业综合生产能力和质量效益”的相关举措。故本题答案为B。"},{"id":"zz-4q19","n":19,"s":"因地制宜推进宜居宜业和美乡村建设，要加强县域基本公共服务供给统筹。下列相关举措，说法不正确的是：","o":["稳慎优化农村中小学校和幼儿园布局，保留并办好必要的乡村小规模学校和幼儿园","支持紧密型县域医共体提升综合服务能力，合理扩大基层医疗卫生机构药品采购、配备、使用范围","巩固拓展农村居民医保参保成果，健全连续参保激励约束机制，稳步提高医保基金在县乡村医疗卫生机构使用比例","以机构养老为基础，鼓励有条件的地方发展助餐服务、日间照料、康复护理等养老服务"],"a":"D","e":"D项说法错误：以居家养老为基础，鼓励有条件的地方发展助餐服务、日间照料、康复护理等养老服务。故本题答案为D。"},{"id":"zz-4q20","n":20,"s":"党的十八大以来，习近平总书记多次赴地方考察调研并发表重要讲话，就各地区发展定位作出重要指示、提出明确要求，为各地因地制宜推进高质量发展指明了方向。下列地区与其发展定位对应正确的是：","o":["浙江——两岸融合发展示范区","福建——中国特色社会主义先行示范区","山西——国家资源型经济转型综合配套改革试验区","上海——中国特色自由贸易港"],"a":"C","e":"A项说法错误：浙江的定位是高质量发展建设共同富裕示范区；两岸融合发展示范区是福建。B项说法错误：福建的定位是两岸融合发展示范区；中国特色社会主义先行示范区是深圳。D项说法错误：上海的定位是社会主义现代化国际大都市；中国特色自由贸易港是海南。故本题答案为C。"}]},{"id":"zz-5","cat":"zz","title":"小黑模考五套卷 · 第五套","short":"第五套","sub":"20 题","questions":[{"id":"zz-5q1","n":1,"s":"习近平总书记强调，县委书记作为县里的权力人物和公众人物，要注意道德操守，道德上失足有时比某些工作失误杀伤力还要大。要不断体会和弘扬先人传承下来的传统美德，如“大道之行也，天下为公”、“不义而富且贵，于我如浮云”、“君子喻于义”、“言必信，行必果”、“德不孤，必有邻”、“人而无信，不知其可也”，等等，为为人处世、安身立命提供重要启示。这最能体现的哲学道理是：","o":["外因是事物发展的根据，内因是事物发展的条件","社会存在决定社会意识，社会意识是对社会存在的反映","人民群众是社会历史的主体，是历史的创造者","社会意识反作用于社会存在，先进的社会意识能够推动社会发展"],"a":"D","e":"A项说法错误：内因是事物发展的根据，外因是事物发展的条件。B、C项说法正确，但是与题意无关。D项符合题意：材料中习近平总书记强调“道德上失足有时比某些工作失误杀伤力还要大”，要求县委书记弘扬传统美德“为为人处世、安身立命提供重要启示”，体现了社会意识对社会存在具有能动的反作用，先进的社会意识能够指导人们的实践活动，对为官从政和社会发展起积极的推动作用。故本题答案为D。"},{"id":"zz-5q2","n":2,"s":"为推动人工智能更好赋能新型工业化，国家提出要以“基础大模型+行业专用模型”双轮驱动，在高端装备、新能源、生物医药等重点领域率先突破，同时要求各地因地制宜制定差异化落地方案，避免“一刀切”式推进。这一政策设计体现的哲学原理是：\n①矛盾普遍性与特殊性相互联结，要坚持共性与个性具体的历史的统一\n②要善于抓住主要矛盾，集中力量解决重点领域的关键问题\n③具体问题具体分析是正确解决矛盾的关键\n④矛盾的同一性是无条件的，斗争性是有条件的","o":["①③④","①②③","②③④","①②④"],"a":"B","e":"①符合题意：“基础大模型”体现共性（普遍性），“行业专用模型”体现个性（特殊性）。基础大模型必须与具体行业的特殊需求相结合，体现了矛盾普遍性与特殊性相互联结，要坚持共性与个性具体的历史的统一。②符合题意：“在高端装备、新能源、生物医药等重点领域率先突破”，是在众多领域中有重点地选择突破口，体现了抓主要矛盾、集中力量解决关键问题的原理。③符合题意：“各地因地制宜制定差异化落地方案，避免‘一刀切’式推进”，即根据不同地区的实际情况采取不同办法，体现了具体问题具体分析是正确解决矛盾的关键。④说法错误：矛盾的同一性是有条件的、相对的，矛盾的斗争性是无条件的、绝对的。故本题答案为B。"},{"id":"zz-5q3","n":3,"s":"最近，一种被称为全球客户“反向出差”的有趣变化正悄然发生。过去，中国企业家的行李箱里装着样品和名片，满世界飞着找订单；如今，剧本悄然翻转——海外客户转变思路主动跨洋来到中国进行商务考察和洽谈，反倒成了高频场景。对于这一变化，下列理解正确的是：\n①社会存在决定社会意识，中国产业链与技术能力的现实变化，构成了“反向出差”现象的物质基础\n②矛盾双方在一定条件下相互转化，中外企业在供需链条中的主动与被动地位随实力变化而发生反转\n③现象与本质辩证统一，要透过“客户飞来中国”的表象，把握中国创新红利与产业生态升级这一本质\n④事物发展的道路是前进的，“反向出差”说明中国外贸的竞争力和吸引力在持续提升，正从“走出去找市场”向“吸引客户来”升级","o":["①②③","①②④","①③④","②③④"],"a":"A","e":"①符合题意：海外客户主动来华，源于中国产业链完整性、技术能力提升等客观现实的变化。正是这种社会存在的实际变化，才引发了全球客户观念的转变，进而出现“反向出差”这一社会现象，体现了社会存在决定社会意识。②符合题意：“中国企业走出去”与“海外客户走进来”是主动与被动、出与进这对矛盾的两个方面。随着中国制造实力与市场吸引力的增强，中外企业在供需链条中的主客地位发生了反转，体现了矛盾双方在一定条件下相互转化。③符合题意：“客户飞来中国”只是外在表现（现象），其背后反映的是中国创新红利释放、产业生态升级这一深层原因（本质）。认识这一变化要求透过现象把握本质，体现了现象与本质相统一的道理。④说法错误：唯物辩证法认为，事物发展的方向和总趋势是前进的、上升的，而发展的道路是曲折的、迂回的。故本题答案为A。"},{"id":"zz-5q4","n":4,"s":"金融“五篇大文章”涵盖科技金融、绿色金融、普惠金融、养老金融与数字金融五大领域，旨在通过差异化金融服务推动经济高质量发展。下列说法对应正确的是：","o":["科技金融——推进金融数据共享和流通，加大公共信用信息对金融领域的开放共享力度","养老金融——强化银发经济金融支持，为建立年金的单位及其职工提供金融服务","数字金融——深入开展中小微企业金融服务能力提升工程，提升乡村振兴金融服务水平","普惠金融——统筹对绿色发展和低碳转型的支持，为助力碳达峰碳中和形成有力支撑"],"a":"B","e":"A项对应错误：推进金融数据共享、信用信息开放属于数字金融，而非科技金融。B项对应正确：银发经济是向老年人提供产品或服务，以及为老龄阶段做准备等一系列经济活动的总和。年金包括职业年金、企业年金，属于第二支柱养老保险，因此属于养老金融。C项对应错误：服务中小微企业、乡村振兴是普惠金融，而非数字金融。D项对应错误：支持“双碳”、绿色低碳转型等属于绿色金融，而非普惠金融。故本题答案为B。"},{"id":"zz-5q5","n":5,"s":"高质量推进国防和军队现代化，是推进中国式现代化的应有之义。“十五五”时期，要深入贯彻新时代强军思想，强化政治引领，推动基本实现国防和军队现代化取得决定性进展。下列相关说法，正确的是：\n①政治建军是人民军队立军之本，关乎国防和军队现代化建设方向和底色\n②高质量推进国防和军队现代化，根本指向和检验标准始终是作风优良\n③要加强无人智能技术军事应用，深化网络信息体系建设运用，逐步构建智能化军事体系\n④要深入推进反腐败斗争，健全重大项目监管体系，确保各项建设质量托底、能力托底、廉洁托底","o":["①②④","②③④","③④","①③④"],"a":"D","e":"②说法错误：高质量推进国防和军队现代化，根本指向和检验标准始终是战斗力。故本题答案为D。"},{"id":"zz-5q6","n":6,"s":"完善社会治理体系，要健全共建共治共享的社会治理制度，提升社会治理效能。下列相关举措，说法正确的有几项？\n①要在社会基层坚持和发展新时代“枫桥经验”，完善正确处理新形势下人民内部矛盾机制\n②要加快推进市域社会治理现代化，提高市域社会治理能力\n③要大幅精简政府机构，将社会治理职能逐步移交社会组织\n④要坚持发挥党委领导核心作用、基层群众性自治组织主导作用，发挥相关部门职能作用、社会各方面协同作用、广大群众主体作用，形成社会治理整体合力","o":["1项","2项","3项","4项"],"a":"B","e":"③说法错误：健全共建共治共享的社会治理制度，要推动政府和社会协同共治，而非将社会治理职能逐步移交社会组织。④说法错误：坚持发挥党委领导核心作用、政府主导作用，发挥相关部门职能作用、社会各方面协同作用、广大群众主体作用，形成社会治理整体合力。基层群众自治组织在城乡基层治理体系中发挥基础作用。①②说法正确。故本题答案为B。"},{"id":"zz-5q7","n":7,"s":"2026年6月，第12期《求是》杂志发表习近平总书记重要文章《一体推进教育科技人才发展》。文章指出，要强化教育对科技和人才的支撑作用。下列相关表述，正确的是：\n①要强化高水平应用型大学国家基础研究主力军和重大科技突破策源地作用\n②要统一推进高校改革发展，引导高校在不同领域不同赛道发挥优势、办出特色\n③要统筹职业教育、高等教育、继续教育，推进职普融通、产教融合、科教融汇\n④要推进素质教育，创新教育方法，努力形成有利于创新人才成长的育人环境\n⑤要从国家战略需求中凝练重大科技问题，持续产出原创性、颠覆性科技创新成果","o":["①②③","②④⑤","③④⑤","②③④"],"a":"C","e":"①说法错误：要强化高水平研究型大学国家基础研究主力军和重大科技突破策源地作用，建立科技创新与人才培养相互支撑、带动学科高质量发展的有效机制，从国家战略需求中凝练重大科技问题，持续产出原创性、颠覆性科技创新成果。②说法错误：分类推进高校改革发展，引导高校在不同领域不同赛道发挥优势、办出特色。③④⑤说法正确。故本题答案为C。"},{"id":"zz-5q8","n":8,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。《决定》提出，一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本方针。下列相关说法，正确的有几项？\n①增强分阶段推进不敢腐不能腐不想腐综合效能，抓实以案促改促治，提高反腐败穿透力\n②保持惩治腐败高压态势，深化权力集中、资金密集、资源富集领域腐败问题整治，重点查处政治问题和经济问题交织、政商勾连、资本向政治领域渗透等问题\n③加强对权力运行的制约和监督，健全授权用权制权相统一、清晰透明可追溯的制度机制\n④夯实崇廉拒腐思想根基，加强新时代廉洁文化建设，运用党的创新理论蕴含的理想信念、价值理念、道德观念、纪法意识涵养党员、干部清廉操守","o":["1项","2项","3项","4项"],"a":"C","e":"①说法错误：增强一体推进不敢腐不能腐不想腐综合效能，抓实以案促改促治，提高反腐败穿透力。②③④说法正确。故本题答案为C。"},{"id":"zz-5q9","n":9,"s":"2026年10月12日至13日，全国卫生与健康大会在京召开。习近平总书记出席会议并发表重要讲话。下列相关说法，不正确的是：","o":["“十五五”时期是实现到本世纪中叶建成健康中国目标的关键时期，要推动卫生与健康事业高质量发展，确保健康中国建设取得决定性进展","人民健康是民族昌盛和国家强盛的重要标志","我国建成世界上规模最大的医疗服务体系、传统医药体系、疾病防控体系、医疗保障体系","我们要建成的健康中国，是均衡普惠、优质高效的健康中国，应当具有强大的健康管理能力、疾病防控能力、医疗服务能力、医保支撑能力、医药创新能力、人才培养能力"],"a":"A","e":"A项说法错误：“十五五”时期是实现到2035年建成健康中国目标的关键时期，要坚定不移走中国特色卫生与健康发展道路，贯彻新时代卫生与健康工作方针，扬优势、固基础、补短板、强弱项，推动卫生与健康事业高质量发展，不断提高人民健康水平，确保健康中国建设取得决定性进展。故本题答案为A。"},{"id":"zz-5q10","n":10,"s":"2026年10月9日，《中共中央国务院关于发展新质生产力的意见》发布。《意见》指出，发展新质生产力是推动高质量发展的内在要求和重要着力点。下列相关说法正确的是：","o":["要坚持改革主导、创新为要、因地制宜、先立后破","要加快发展新质生产力以适应新型生产关系","发展新质生产力以产业创新为引领，以全要素生产率大幅提升为核心标志","要推动技术革命性突破、生产要素创新性配置、产业深度转型升级，推动劳动者、劳动资料、劳动对象优化组合和更新跃升"],"a":"D","e":"A项说法错误：坚持创新主导、改革为要、因地制宜、先立后破。B项说法错误：加快形成同新质生产力更相适应的生产关系。C项说法错误：以科技创新为引领，以全要素生产率大幅提升为核心标志。故本题答案为D。"},{"id":"zz-5q11","n":11,"s":"2026年10月9日，《中共中央国务院关于发展新质生产力的意见》发布。《意见》指出，要着力推进发展方式创新。下列相关说法正确的有几项？\n①健全生态产品价值实现机制，全面实施能源消耗总量和强度双控制度\n②以全国碳市场为主体完善碳定价机制，扩大全国碳排放权交易市场覆盖范围\n③实施以绿色生态为导向的农业补贴制度\n④聚焦碳达峰碳中和目标，加快推动先进核聚变能落地应用","o":["1项","2项","3项","4项"],"a":"B","e":"①说法错误：健全生态产品价值实现机制，全面实施碳排放总量和强度双控制度，健全碳排放统计核算体系、标准计量体系、产品碳标识认证制度、产品碳足迹管理体系。④说法错误：聚焦碳达峰碳中和目标，有序发展先进核裂变能。②③说法正确。故本题答案为B。"},{"id":"zz-5q12","n":12,"s":"《2026年政府工作报告》指出，2026年要继续实施更加积极的财政政策和适度宽松的货币政策。下列说法正确的是：","o":["赤字率降至4%左右安排，赤字规模比上年降低2300亿元","各级政府建立健全增收节支机制，积极盘活利用存量资源资产，增加一般性支出","把促进经济稳定增长、物价合理回升作为货币政策的重要考量，灵活高效运用降准降息等多种政策工具","畅通货币政策传导机制，引导金融机构加力支持扩大内需、科技创新、国有上市公司等重点领域"],"a":"C","e":"A项说法错误：从近年我国赤字率安排来看，2024年为3%，2025年提高到4%左右，2026年继续拟按4%左右安排，赤字规模比上年增加2300亿元。B项说法错误：各级政府要更好“当家理财”，建立健全增收节支机制，积极盘活利用存量资源资产，严肃财经纪律，强化预算约束，严控一般性支出。D项说法错误：畅通货币政策传导机制，引导金融机构加力支持扩大内需、科技创新、中小微企业等重点领域。故本题答案为C。"},{"id":"zz-5q13","n":13,"s":"2026年9月20日，《关于分类推进高校改革的意见》印发。《意见》指出，要激发分类发展动能。下列相关举措，说法正确的是：\n①打造服务国家重大战略支撑力量，发挥好“双一流”建设对研究型大学改革的牵引作用\n②建强服务区域经济社会发展基础力量，实施优质特色研究型本科院校和学科专业建设工程，优化实施高水平高等职业学校和专业建设计划\n③夯实服务行业创新发展支点力量，发挥行业特色高校传统优势，强化服务实体经济能力\n④构建高等教育融合发展新形态，探索国家拔尖创新人才培养新模式","o":["①②③","①②④","①③④","②③④"],"a":"C","e":"②说法错误：建强服务区域经济社会发展基础力量，实施优质特色应用型本科院校和学科专业建设工程，优化实施高水平高等职业学校和专业建设计划。故本题答案为C。"},{"id":"zz-5q14","n":14,"s":"2026年1月，习近平总书记在省部级主要领导干部学习贯彻党的二十届四中全会精神专题研讨班开班仪式上发表重要讲话强调，要全面深刻准确领会和把握党的二十届四中全会的战略部署。下列相关说法正确的是：","o":["各地区各行业要找准定位，坚持智能化、绿色化、融合化方向，充分发挥比较优势，形成上下游产业相互衔接、各展其长、同向发力的生动局面","发展新质生产力是建设现代化产业体系的必然要求，不能一哄而上、跟风冒进，更不能停滞不前，要逐步替代传统产业","要以做强国际循环提升扩大高水平对外开放的自主性，以拓展国内大循环增强国内改革发展的活力，努力实现内外联通、互促共进","促进社会发展，发展经济是重点，要把发展经济和改善民生有机统一起来"],"a":"A","e":"B项说法错误：发展新质生产力是建设现代化产业体系的必然要求。要坚持因地制宜，不能一哄而上、跟风冒进，更不能喜新厌旧、把传统产业优势丢掉。C项说法错误：要以做强国内大循环提升扩大高水平对外开放的自主性，以拓展国际循环增强国内改革发展的活力，努力实现内外联通、互促共进。D项说法错误：促进社会发展，改善民生是重点，要把发展经济和改善民生有机统一起来。故本题答案为A。"},{"id":"zz-5q15","n":15,"s":"习近平总书记指出，科技创新是人类文明进步的不竭动力，新一轮科技革命和产业变革深刻改变人类生产生活方式和世界发展格局，科技实力和创新能力越来越成为国家的核心竞争力。下列相关说法，正确的有几项？\n①要坚持四个面向战略导向，提高科技攻关组织化程度，提升国家创新体系整体效能\n②要突出科技创新供给和产业需求牵引，推动产学研融通创新，打通科技加速向现实生产力转化的通道\n③要优化科教协同育人机制，坚持在培养中使用、在使用中培养，注重在科研一线发现和培养更多优秀青年科技人才\n④要持续深化科教界“帽子”治理，防止简单以称号头衔确定薪酬待遇、配置创新资源\n⑤要深度主导全球科技治理，广泛宣介中国主张和中国方案，提升国际规则制定话语权和影响力","o":["5项","4项","3项","2项"],"a":"B","e":"⑤说法错误：要深度参与全球科技治理，广泛宣介中国主张和中国方案，提升国际规则制定话语权和影响力。①②③④说法正确。故本题答案为B。"},{"id":"zz-5q16","n":16,"s":"2026年8月17日，习近平总书记在纪念江泽民同志诞辰100周年大会上发表重要讲话指出，我们要学习江泽民同志与时俱进的创新精神。江泽民同志提出党的全部理论和工作要体现时代性、把握规律性、富于创造性，集中全党智慧创立“三个代表”重要思想。下列关于江泽民同志的主要理论贡献，说法正确的是：\n①创造性回答了“什么是社会主义、怎样建设社会主义”的问题\n②强调我们党始终代表中国先进生产力的发展要求、代表中国先进文化的前进方向、代表中国最广大人民的根本利益\n③确定社会主义初级阶段的基本路线，提出“三步走”发展战略\n④确立社会主义市场经济体制的改革目标和基本框架，确立公有制为主体、多种所有制经济共同发展的基本经济制度和按劳分配为主体、多种分配方式并存的分配制度","o":["①③","①④","②③","②④"],"a":"D","e":"①说法错误：“三个代表”重要思想进一步回答了“什么是社会主义、怎样建设社会主义”，创造性回答的是“建设什么样的党、怎样建设党”的问题。③说法错误：社会主义初级阶段基本路线、“三步走”的发展战略，属于邓小平理论的主要成果。②④说法正确。故本题答案为D。"},{"id":"zz-5q17","n":17,"s":"习近平总书记指出，“十五五”时期是科技强国建设的关键攻坚期，要全力抓好党中央关于科技事业各项部署的落实。下列属于“十五五”时期推进科技事业重要举措的有几项？\n①增强科技创新体系化攻关能力\n②推动科技创新和产业创新深度融合\n③大力培养优秀青年科技人才\n④提高科技创新投入效能\n⑤建设具有全球影响力的重要文化中心","o":["5项","4项","3项","2项"],"a":"B","e":"习近平总书记在国家科学技术奖励大会、两院院士大会、中国科协第十一次全国代表大会上的讲话指出，“十五五”时期是科技强国建设的关键攻坚期，要全力抓好党中央关于科技事业各项部署的落实。要增强科技创新体系化攻关能力、推动科技创新和产业创新深度融合、大力培养优秀青年科技人才、提高科技创新投入效能、用好科技评价指挥棒、加强科技伦理和安全治理。故①②③④均属于。⑤属于文化强国建设的举措，和科技强国无关。故本题答案为B。"},{"id":"zz-5q18","n":18,"s":"习近平总书记指出，农业农村现代化关系中国式现代化全局和成色，要锚定农业农村现代化，扎实推进乡村全面振兴。下列说法正确的有几项？\n①强化价格、补贴、保险等政策支持和协同，健全种粮农民收益保障机制\n②落实好农民工稳岗就业支持政策，支持重点行业企业减负拓岗\n③全面开展第二轮土地承包到期后再延长三十年整省试点，妥善解决延包中的矛盾纠纷，确保绝大多数农户原有承包地优化调整、顺利延包\n④有序推进农村宅基地入市，支持入市土地优先用于发展集体经济和乡村产业，鼓励用于建设商品住房\n⑤依法维护进城落户农民土地承包权、宅基地使用权、集体收益分配权，探索建立强制有偿退出的办法","o":["2项","3项","4项","5项"],"a":"A","e":"③说法错误：全面开展第二轮土地承包到期后再延长三十年整省试点，妥善解决延包中的矛盾纠纷，确保绝大多数农户原有承包地保持稳定、顺利延包。④说法错误：有序推进农村集体经营性建设用地入市，支持入市土地优先用于发展集体经济和乡村产业，禁止用于建设商品住房。⑤说法错误：依法维护进城落户农民土地承包权、宅基地使用权、集体收益分配权，探索建立自愿有偿退出的办法。①②说法正确。故本题答案为A。"},{"id":"zz-5q19","n":19,"s":"习近平总书记指出，新时代新征程，各级党委和政府要坚持以人民为中心，加强对民政工作的领导，加强普惠性、基础性、兜底性民生建设，解决好人民最关心最直接最现实的利益问题，不断推动民政事业高质量发展。下列相关举措，说法正确的有几项？\n①加快建立长期护理保险制度，起步阶段保障重度失能人员\n②以满足群众就近就便看病就医需求为出发点，以实施医疗卫生强基工程为支撑，加快建设分级诊疗体系\n③深化住房公积金制度改革，扩大使用范围，支持灵活就业人员参加住房公积金制度\n④全面推进常住地提供基本公共服务，逐步消除基本公共服务与户籍挂钩因素，促进未落户常住人口与户籍人口同等享有基本公共服务","o":["4项","3项","2项","1项"],"a":"A","e":"①②③④说法均正确，故本题答案为 A。"},{"id":"zz-5q20","n":20,"s":"2026年9月，习近平主席同美国总统特朗普在白宫举行会谈。下列相关说法，正确的是：","o":["中美两国要朝着竞争为主、合作有度、分歧可控、和平可期的方向努力，走出一条两个大国的正确相处之道","合作是双行道，中美经贸关系的稳定既需要拉长合作清单，也需要压缩问题清单","要秉持平等、尊重、互惠的精神，坚持零和博弈导向，推动中美经贸关系持续稳定向好发展","双方同意构建“基于尊重、公平、对等的中美全面战略协作伙伴关系”"],"a":"B","e":"A项说法错误：中美两国要朝着合作为主、竞争有度、分歧可控、和平可期的方向努力，走出一条两个大国的正确相处之道。C项说法错误：要秉持平等、尊重、互惠的精神，坚持互利共赢导向，推动中美经贸关系持续稳定向好发展。D项说法错误：双方同意构建“基于尊重、公平、对等的建设性战略稳定关系”。故本题答案为B。"}]},{"id":"cg-1","cat":"zz","title":"超格考前五套卷 · 第一套","short":"超格第一套","sub":"20 题","questions":[{"id":"cg-1q1","n":1,"s":"党的二十届五中全会回顾党100多年来的奋斗历程，总结了中国共产党能够从胜利走向胜利的经验。下列相关说法不准确的是：","o":["胸怀共产主义远大理想，立志于中华民族千秋伟业，坚持为中国人民谋幸福、为中华民族谋复兴","在各个历史时期都高度重视管党治党，勇于坚持真理、修正错误，在依靠自身力量和人民支持解决自身问题中不断强大","在革命、建设、改革中先后把党的建设作为伟大工程、新的伟大工程，党的十八大以来深入推进新时代党的建设新的伟大工程","找到“为民造福”和“自我革命”两个跳出治乱兴衰历史周期率的答案，这是中国共产党的独特创造"],"a":"D","e":"党的二十届五中全会回顾党100多年来的奋斗历程，指出中国共产党能够从胜利走向胜利，就在于胸怀共产主义远大理想，立志于中华民族千秋伟业，坚持为中国人民谋幸福、为中华民族谋复兴，在各个历史时期都高度重视管党治党，勇于坚持真理、修正错误，在依靠自身力量和人民支持解决自身问题中不断强大，成为党和人民事业的坚强领导核心。在革命、建设、改革中先后把党的建设作为伟大工程、新的伟大工程，党的十八大以来深入推进新时代党的建设新的伟大工程，找到“让人民来监督政府”和“自我革命”两个跳出治乱兴衰历史周期率的答案，这是中国共产党的独特创造，永载马克思主义政党建设史册。故选D。"},{"id":"cg-1q2","n":2,"s":"2026年6月，中央党的建设工作领导小组印发《关于学习贯彻习近平党建思想的通知》，《通知》强调，要深入学习领会习近平党建思想的科学内涵。关于习近平党建思想的科学内涵，以下说法正确的有几项？\n①深刻领会“坚持全面从严治党”是新时代党的建设的战略方针\n②深刻领会“坚持不忘初心、牢记使命”是党的宗旨立场和价值取向\n③深刻领会“坚持用党的创新理论凝心铸魂”是新时代党的建设的根本要求\n④深刻领会“坚持以党的政治建设为统领”是党的思想建设的根本任务\n⑤深刻领会“坚持用严明的纪律管全党治全党”是全面从严治党的治本之策","o":["2项","3项","4项","5项"],"a":"B","e":"2026年6月，中央党的建设工作领导小组印发《关于学习贯彻习近平党建思想的通知》，《通知》强调，要深入学习领会习近平党建思想的科学内涵。深刻领会“坚持党的领导是中国特色社会主义最本质的特征”；深刻领会“坚持党中央集中统一领导”是党的领导的最高原则；深刻领会“坚持全面从严治党”是新时代党的建设的战略方针；深刻领会“坚持不忘初心、牢记使命”是党的宗旨立场和价值取向；深刻领会“坚持以党的政治建设为统领”是新时代党的建设的根本要求；深刻领会“坚持用党的创新理论凝心铸魂”是党的思想建设的根本任务；深刻领会“坚持锤炼坚强党性”是党员、干部的终身课题；深刻领会“坚持健全上下贯通、执行有力的组织体系”是党的优势所在、力量所在；深刻领会“坚持建设堪当民族复兴重任的高素质干部队伍”是关系党和国家事业的关键性问题；深刻领会“坚持推进作风建设常态化长效化”是保持党同人民群众血肉联系的有效途径；深刻领会“坚持用严明的纪律管全党治全党”是全面从严治党的治本之策；深刻领会“坚持一体推进不敢腐不能腐不想腐”是全面从严治党的重要方略和反腐败斗争的基本方针；深刻领会“坚持制度治党、依规治党”是全面从严治党的长远和根本之策；深刻领会“坚持落实管党治党政治责任”是全面从严治党需要牢牢牵住的“牛鼻子”。③④说法不准确，故本题选B。"},{"id":"cg-1q3","n":3,"s":"2026年6月国务院印发的《实施就业优先战略“十五五”规划》指出，就业是最基本的民生，事关人民群众切身利益，事关经济社会健康发展，事关国家长治久安。关于实施就业优先战略，以下说法不准确的是：","o":["以实现高质量充分就业为底线，健全就业促进机制，构建就业友好型发展方式","“十五五”时期，就业保持总体稳定，确保零就业家庭至少一人实现就业","要围绕就业领域人力资源供需不匹配的主要矛盾，坚持投资于物和投资于人紧密结合","做好宏观政策取向一致性评估，慎重出台对就业有明显收缩效应的政策"],"a":"A","e":"2026年6月，国务院印发《实施就业优先战略“十五五”规划》，《规划》指出，全面贯彻劳动者自主就业、市场调节就业、政府促进就业和鼓励创业的方针，聚焦促进高质量充分就业目标，围绕就业领域人力资源供需不匹配的主要矛盾，坚持投资于物和投资于人紧密结合，以推动高质量发展为基础，以实施就业优先战略为引领，以强化就业优先政策为抓手，以破解结构性就业矛盾为着力点，以深化就业体制机制改革为动力，以不发生规模性失业风险为底线，健全就业促进机制，构建就业友好型发展方式，加强人力资源开发利用，强化择业和用人观念引导，持续促进就业质的有效提升和量的合理增长，不断增强广大劳动者获得感幸福感安全感，为以中国式现代化全面推进强国建设、民族复兴伟业提供有力支撑。A项说法有误，C项说法正确。“十五五”时期，就业保持总体稳定，高质量充分就业取得新进展。就业机会更加充分。城镇就业稳定增长，失业水平有效控制，重点群体就业保持稳定，确保零就业家庭至少一人实现就业。B项说法正确。做好宏观政策取向一致性评估，慎重出台对就业有明显收缩效应的政策。强化重大政策、重大项目、重大生产力布局对就业影响的评估，将吸纳就业情况作为投资项目建设的重要参考。加强事中事后监测评估，跟踪监测分析用工变化、岗位增减、失业风险等情况，动态优化调整实施中的政策和项目。D项说法正确。故本题选A。"},{"id":"cg-1q4","n":4,"s":"习近平总书记在纪念中国工农红军长征胜利90周年大会上的讲话指出，90年后的今天，再次回望那段苦难辉煌，我们更加深刻认识到，长征胜利是必然的，其中蕴含着党和人民军队铿锵前进的制胜之道。下列属于长征胜利“制胜之道”的是：\n①红军长征的伟大胜利之路，是依靠党的正确领导走出来的\n②红军长征的伟大胜利之路，是依靠坚定的革命意志走出来的\n③红军长征的伟大胜利之路，是依靠独立自主、实事求是走出来的\n④红军长征的伟大胜利之路，是依靠广大人民群众支持走出来的\n⑤红军长征的伟大胜利之路，是依靠完善的后勤保障体系支撑走出来的","o":["①②④","①②③④","①③④⑤","①②③④⑤"],"a":"B","e":"习近平总书记在纪念中国工农红军长征胜利90周年大会上的讲话指出，我们重温历史，是为了汲取奋进的智慧和力量。90年后的今天，再次回望那段苦难辉煌，我们更加深刻认识到，长征胜利是必然的，其中蕴含着党和人民军队铿锵前进的制胜之道。红军长征的伟大胜利之路，是依靠党的正确领导走出来的。红军长征的伟大胜利之路，是依靠坚定的革命意志走出来的。红军长征的伟大胜利之路，是依靠独立自主、实事求是走出来的。红军长征的伟大胜利之路，是依靠广大人民群众支持走出来的。⑤不属于。故选B。"},{"id":"cg-1q5","n":5,"s":"习近平总书记强调，“十五五”时期是实现到2035年建成健康中国目标的关键时期，要坚定不移走中国特色卫生与健康发展道路。关于建设健康中国，下列说法正确的是：\n①新时代卫生与健康工作方针是“以基层为重点，以改革创新为动力，中医为主，西医为辅，把健康融入所有政策，人民共建共享”\n②健全公共卫生体系要求深化社会共治、医防协同、医防融合，强化传染病预防控制、监测预警、医疗救治、应急处置、物资保障和监督管理\n③深化公立医院改革和医保支付方式改革，健全药品价格形成机制、优化药品和医用耗材集中采购政策，提高医保资金使用效率，完善医疗、医保、医药协同发展和治理机制\n④走中国特色卫生与健康发展道路，要坚持人民至上、生命至上，坚持基本医疗卫生事业的公益性","o":["①②③","②③④","①②④","①③④"],"a":"B","e":"2026年第15期《求是》杂志发表习近平署名文章《加快建设健康中国》。①错误，文章指出：在2016年的全国卫生与健康大会上，中共中央明确提出新时代卫生与健康工作方针，即以基层为重点，以改革创新为动力，预防为主，中西医并重，把健康融入所有政策，人民共建共享。②正确，文章指出：健全公共卫生体系，要求深化社会共治、医防协同、医防融合，强化传染病预防控制、监测预警、医疗救治、应急处置、物资保障和监督管理。③正确，文章指出：要深化公立医院改革和医保支付方式改革，健全药品价格形成机制、优化药品和医用耗材集中采购政策，提高医保资金使用效率，完善医疗、医保、医药协同发展和治理机制。④正确，文章指出：我国是社会主义国家，是人口规模巨大、城乡区域差距仍然较大的发展中国家，这决定我们必须坚持党对卫生与健康工作的领导，坚持人民至上、生命至上，坚持健康优先发展战略，坚持基本医疗卫生事业的公益性，走中国特色卫生与健康发展道路。故本题选B。"},{"id":"cg-1q6","n":6,"s":"全面从严治党关键在从严治党，锻造堪当民族复兴重任的高素质干部队伍，建设一支政治过硬、本领高强、作风优良、纪律严明的高素质干部队伍，是持之以恒推进全面从严治党的重要任务。下列相关说法正确的是：","o":["坚持党管干部原则，坚持德才兼备、以才为先，坚持五湖四海、任人唯贤，坚持事业为上、公道正派","坚持个体强整体优、功能服从结构，选优配强各级领导班子特别是“一把手”","落实廉政意见由党委（党组）书记或纪委书记（派驻纪检监察组组长）签字确认的规定","提高培养选拔优秀年轻干部质量，把基层一线作为培养年轻干部的基础阵地"],"a":"D","e":"《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》指出，A 错误，坚持党管干部原则，坚持德才兼备、以德为先，坚持五湖四海、任人唯贤，坚持事业为上、公道正派。B 错误，坚持个体强整体优、结构服从功能，选优配强各级领导班子特别是“一把手”。C 错误，落实廉政意见由党委（党组）书记和纪委书记（派驻纪检监察组组长）共同签字确认的规定。D 正确，提高培养选拔优秀年轻干部质量。把基层一线作为培养年轻干部的基础阵地，推动年轻干部到艰苦地区、复杂环境、吃劲岗位墩苗锻炼，砥砺品质、改进作风、增长才干。故本题选D。"},{"id":"cg-1q7","n":7,"s":"保持土地承包关系稳定并长久不变，第二轮土地承包到期后再延长30年，是以习近平同志为核心的党中央作出的重大决策部署。对此，下列说法正确的是：","o":["坚持稳中求进、守正创新，牢牢把住提升农业规模化经营水平这条主线","工作中要做到打破原集体土地所有权的界限，在全村范围内推进落实平均承包","坚持延包原则，以户为单位开展延包，以农村承包地确权登记颁证成果为基础开展延包试点","以行政手段推动确权确股不确地的条件和程序，由省级政府农业农村主管部门依法作出规定"],"a":"C","e":"2026年3月，中共中央办公厅、国务院办公厅印发《关于做好第二轮土地承包到期后再延长30年试点工作的意见》。A 项错误，《意见》指出：坚持稳中求进、守正创新，牢牢把住处理好农民和土地关系这条主线，锚定加快建设农业强国目标，坚持把依法维护农民权益作为出发点和落脚点。B 项错误，《意见》指出：坚持集体所有制不动摇，严禁打破原集体土地所有权的界限在全村范围内搞平均承包，充分维护农民集体对承包地发包、调整、监督、收回等各项权能，探索和丰富农村土地集体所有制的有效实现形式。C 项正确，《意见》指出：开展延包试点，以农村承包地确权登记颁证成果为基础，以第二轮土地承包合同到期为起点再延长承包期30年。以户为单位开展延包，确保绝大多数农户原有承包地继续保持稳定，不能推倒重来、打乱重分，不能借机违法调整或收回农户承包地。D 项错误，《意见》指出：坚持确权到户到地，不得违背农民意愿以行政手段推动确权确股不确地，也不得简单以少数服从多数的名义强迫不愿确股的农民确股。实行确权确股不确地的条件和程序，由省级政府农业农村主管部门依法作出规定。故本题选 C。"},{"id":"cg-1q8","n":8,"s":"习近平总书记强调，“全球南方群体性崛起，是世界大变局的鲜明标志。”“当前，世界百年变局加速演进，全球南方群体性崛起，成为推动世界多极化的关键动力。”关于壮大全球南方力量，使其在国际事务中更好发挥积极、稳定、向善作用，下列说法错误的是：","o":["共同捍卫国际法治，确保国际法和国际规则平等适用、不搞双重标准","共同应对传统和非传统安全威胁，推动把安全置于国际经贸议程中心地位","坚持以人民为中心的发展思想，推动落实联合国2030年可持续发展议程","高举多边主义旗帜，维护联合国权威和作用，支持多边机构改革增效，为各国平等参与国际事务提供保障"],"a":"B","e":"A 正确，2026年9月13日，习近平总书记在金砖国家领导人第十八次会晤第二阶段会议的讲话指出，全球南方国家要共同捍卫国际法治，维护主权平等、不干涉内政、和平解决争端等国际关系基本准则，确保国际法和国际规则平等适用、不搞双重标准。B 错误，2026年9月13日，习近平总书记在金砖国家领导人第十八次会晤第二阶段会议的讲话指出，全球南方国家要携手推进安全治理，共同应对传统和非传统安全威胁。2024年10月24日，习近平总书记在 “金砖+” 领导人对话会上的讲话指出，“全球南方” 为发展而起，因发展而兴。我们要做共同发展的中坚力量，积极参与和引领全球经济治理体系改革，推动把发展置于国际经贸议程中心地位。C 正确，2026年9月13日，习近平总书记在金砖国家领导人第十八次会晤第二阶段会议的讲话指出，全球南方国家要坚持以人民为中心的发展思想，推动落实联合国2030年可持续发展议程。D 正确，2026年9月13日，习近平总书记在金砖国家领导人第十八次会晤第二阶段会议的讲话指出，全球南方国家要高举多边主义旗帜，维护联合国权威和作用，支持多边机构改革增效，为各国平等参与国际事务提供保障。推动世界贸易组织改革保持正确方向，维护最惠国待遇等原则，积极探索制定面向未来的新规则。故本题选 B。"},{"id":"cg-1q9","n":9,"s":"习近平总书记高度重视制造业发展，将制造业喻为立国之本、强国之基，曾明确要求“立足实体经济这个根基，做大做强先进制造业”。下列相关说法错误的是：","o":["制造业的核心就是创新，就是掌握关键核心技术，必须靠自力更生奋斗，靠自主创新争取","要以智能制造为主攻方向推动产业技术变革和优化升级，推动制造业产业模式和企业形态根本性转变，以存量带动增量，促进我国产业迈向全球价值链中高端","坚持智能化、绿色化、融合化方向，加快构建以先进制造业为骨干的现代化产业体系，巩固壮大实体经济根基","推动我国制造业转型升级，建设制造强国，必须加强技术研发，提高国产化替代率，把科技的命脉掌握在自己手中"],"a":"B","e":"A 正确，2018年10月，习近平总书记在广东考察时强调，从大国到强国，实体经济发展至关重要，任何时候都不能脱实向虚。制造业是实体经济的一个关键，制造业的核心就是创新，就是掌握关键核心技术，必须靠自力更生奋斗，靠自主创新争取，希望所有企业都朝着这个方向去奋斗。B 错误，2018年5月，习近平总书记在中国科学院第十九次院士大会、中国工程院第十四次院士大会上指出，要推进互联网、大数据、人工智能同实体经济深度融合，做大做强数字经济。要以智能制造为主攻方向推动产业技术变革和优化升级，推动制造业产业模式和企业形态根本性转变，以 “鼎新” 带动 “革故”，以增量带动存量，促进我国产业迈向全球价值链中高端。C 正确，2026年9月，习近平总书记就发展先进制造业作出重要指示指出，统筹高质量发展和高水平安全，坚持智能化、绿色化、融合化方向，持续做大做强先进制造业，提升产业链自主可控水平，加快构建以先进制造业为骨干的现代化产业体系，巩固壮大实体经济根基，为推进中国式现代化提供有力支撑。D 正确，2022年6月，习近平总书记在湖北武汉考察时强调，高端制造是经济高质量发展的重要支撑。推动我国制造业转型升级，建设制造强国，必须加强技术研发，提高国产化替代率，把科技的命脉掌握在自己手中，国家才能真正强大起来。故本题选 B。"},{"id":"cg-1q10","n":10,"s":"习近平总书记强调，基础研究是整个科学体系的源头，是所有技术问题的总机关。要以更大力度、更实举措加强基础研究，提升我国原始创新能力，进一步打牢科技强国建设根基。关于加强基础研究，下列表述不准确的是：","o":["强化企业引领作用，推动国家科研机构、高水平研究型大学等主导的产学研用深度融合，打通基础研究、应用开发、成果转化的创新链条","注重在科研一线发现和培养人才，坚持任务牵引、以老带新，大力扶持青年人才","逐步提高基础研究经费占比，形成多元化投入格局，健全符合基础研究特点的分类评价体系，营造开放包容、宽容失败的创新环境","要主动融入全球创新网络，深化基础研究国际交流合作，联合开展气候变化、能源环境、生命健康等重大科学问题攻关，积极参与全球科技治理"],"a":"A","e":"2026年4月30日上午，中共中央总书记、国家主席、中央军委主席习近平在上海出席加强基础研究座谈会并发表重要讲话。A 项错误，强化国家科研机构、高水平研究型大学等引领作用，推动企业主导的产学研用深度融合，打通基础研究、应用开发、成果转化的创新链条。B 项正确，注重在科研一线发现和培养人才，坚持任务牵引、以老带新，大力扶持青年人才。C 项正确，逐步提高基础研究经费占比，形成多元化投入格局，健全符合基础研究特点的分类评价体系，营造开放包容、宽容失败的创新环境。D 项正确，要主动融入全球创新网络，联合开展气候变化、能源环境、生命健康等重大科学问题攻关，积极参与全球科技治理。故本题选 A。"},{"id":"cg-1q11","n":11,"s":"“十五五”时期在基本实现社会主义现代化进程中具有承前启后的重要地位，是夯实基础、全面发力的关键时期。关于我国“十五五”相关专项规划目标，下列说法正确的是：","o":["根据《美丽中国建设“十五五”规划》，到2030年生态环境根本好转，美丽中国目标基本实现","根据《知识产权保护和运用“十五五”规划》，到2030年知识产权强国基本建成","根据《“十五五”碳达峰行动方案》，到2030年确保如期实现碳达峰目标，为实现2035年国家自主贡献目标、推进碳中和奠定坚实基础","根据《国民健康“十五五”规划》，到2030年人均预期寿命达到80岁，建成健康中国"],"a":"C","e":"A 项错误，《美丽中国建设 “十五五” 规划》指出，到2030年，生态环境质量全面改善，美丽中国建设取得新的重大进展。绿色生产生活方式基本形成，碳达峰目标如期实现；到2035年，生态环境根本好转，美丽中国目标基本实现。B 项错误，《知识产权保护和运用 “十五五” 规划》指出，到2030年，我国知识产权综合实力和国际竞争力进一步增强。展望2035年，我国知识产权综合竞争力跻身世界前列，中国特色、世界水平的知识产权强国基本建成。C 项正确，《 “十五五” 碳达峰行动方案》——到2030年，我国单位国内生产总值二氧化碳排放比2025年降低17%，非化石能源消费占比达到25%，确保如期实现碳达峰目标，为实现2035年国家自主贡献目标、推进碳中和奠定坚实基础。D 项错误，《国民健康“十五五”规划》——到2030年，面向人民生命健康的教育科技人才一体发展格局基本形成，健康生活方式加快普及，重大慢性病发病率上升趋势得到有效控制，人均预期寿命达到80岁，主要健康指标进入高收入国家行列，为2035年建成健康中国打下坚实基础。故本题选 C。"},{"id":"cg-1q12","n":12,"s":"由常住地提供基本公共服务，有利于满足人民日益增长的美好生活需要，对提升城镇化质量、释放国内需求潜力、构建新发展格局具有重要意义。关于推行常住地提供基本公共服务，以下说法不准确的是：","o":["加力落实持居住证参加城乡居民基本医疗保险政策，各地对持居住证参保人员按照户籍人口相同标准给予财政补助，巩固扩大参保覆盖面","逐步将未落户常住人口纳入常住地儿童关爱、养老助老、社会救助、扶残助残等基本公共服务范围，开放放宽户籍限制","促进基本公共服务资源公平有序分配，逐步拉开梯度层次和差异、降低享有门槛","人口流入城市和县城要加大基本公共服务供给力度，尽力而为、量力而行，增量资源优先保障未落户常住人口公平享有基本公共服务"],"a":"C","e":"2026年5月，《国务院关于推行常住地提供基本公共服务的实施意见》对外发布，《实施意见》指出，加力落实持居住证参加城乡居民基本医疗保险政策，超大特大城市等各类城市切实保障外地户籍中小学生、学龄前儿童等在常住地参加城乡居民基本医疗保险的权利，各地对持居住证参保人员按照户籍人口相同标准给予财政补助，巩固扩大参保覆盖面。加强异地就医直接结算管理服务，提升异地就医备案管理和结算报销可及性、便利性。各地不得将办理职工医保退休人员待遇与在当地按月领取基本养老金绑定。A项说法正确。逐步将未落户常住人口纳入常住地儿童关爱、养老助老、社会救助、扶残助残等基本公共服务范围，放宽户籍限制。支持流动儿童融入城市，推动各地出台流动儿童在居住地享有关爱服务基础清单，促进流动儿童均等享有基本公共服务。B项说法正确。对供需矛盾突出的基本公共服务，各地可通过积分制等方式，在一定时期内采取以就业、居住等时间因素为主要条件的梯度供给办法，促进基本公共服务资源公平有序分配，逐步减少梯度层次和差异、降低享有门槛。C项说法不准确。人口流入城市和县城要加大基本公共服务供给力度，尽力而为、量力而行，增量资源优先保障未落户常住人口公平享有基本公共服务，逐步提高服务质量；其中，超大城市要按照常住人口规模目标，转变城市发展方式，优化人口和公共服务设施空间布局，因城施策积极探索。人口总量稳定或流出的城市和县城要根据实际居住人口的数量和结构，优化公共服务资源配置，实现提质增效。D项说法正确。故本题选C。"},{"id":"cg-1q13","n":13,"s":"培育发展未来产业，对于我们抢占科技和产业制高点、牢牢把握发展主动权，对于发展新质生产力、建设现代化产业体系，对于提高人民生活品质、促进人的全面发展和社会全面进步，都具有重要意义。下列相关说法不准确的是：","o":["科技突破的程度，很大程度上决定未来产业发展的速度、广度、深度","要着眼长远，加强基础研究战略性、前瞻性、体系化布局，强化科学研究、技术开发应用导向，努力从根本上解决原理性、基础性问题","中央企业是科技创新的国家队，也应成为未来产业的主力军","大力发展科技金融，构建与未来产业全生命周期融资需求相适应的金融服务体系，引导长期资本投早、投小、投长期、投硬科技"],"a":"B","e":"2026年6月1日，《求是》杂志发表习近平总书记重要文章《前瞻布局和发展未来产业》，文章指出，科技突破的程度，很大程度上决定未来产业发展的速度、广度、深度。要充分发挥新型举国体制优势，强化国家战略科技力量作用，坚持“产业出题、科技答题”，大力提升科技支撑引领能力。要立足当前，采取超常规措施，加大重点领域关键核心技术攻关力度，尽快解决制约未来产业发展的“卡脖子”问题；着眼长远，加强基础研究战略性、前瞻性、体系化布局，强化科学研究、技术开发原始创新导向，努力从根本上解决原理性、基础性问题；推动科技创新和产业创新深度融合，加快科技成果转化应用，努力将科研创造力转化为现实生产力。A项正确，B项“应用导向”表述有误。中央企业是科技创新的国家队，也应成为未来产业的主力军。要支持中央企业结合主责主业发展未来产业，切实增强核心功能，提升核心竞争力。C项说法正确。大力发展科技金融，构建与未来产业全生命周期融资需求相适应的金融服务体系，引导长期资本投早、投小、投长期、投硬科技。D 项说法正确。故本题选 B。"},{"id":"cg-1q14","n":14,"s":"2026年5月，国务院印发《城市更新“十五五”规划》，《规划》指出，要营造高品质城市生活空间，以下不属于营造高品质城市生活空间的举措的是：","o":["持续推动城镇老旧小区改造","加快建设完整社区","提升风险防控和应急保障能力","完善城市综合交通体系"],"a":"C","e":"2026年5月，国务院印发《城市更新“十五五”规划》，《规划》指出，要营造高品质城市生活空间：推进“好房子”建设；持续推动城镇老旧小区改造；加快建设完整社区；推进老旧街区厂区改造提升；提升城市公共服务品质；完善城市综合交通体系。ABD属于营造高品质城市生活空间的举措。C项属于增强城市安全韧性的举措。故本题选C。"},{"id":"cg-1q15","n":15,"s":"建立长期护理保险制度，是解决群众急难愁盼、健全社会保障体系的一项重大的制度安排。关于长期护理保险制度资金筹集，下列说法正确的是：","o":["未就业城乡居民长期护理保险按年筹集资金，与城乡居民基本医疗保险费共同缴纳","退休人员由原用人单位和个人共同缴费，缴费基数为当地人均可支配收入","灵活就业人员筹资由个人缴费和政府补助构成，政府补助由中央财政和地方财政共同承担","18周岁以下未就业人员不参加长期护理保险，不单独筹资，符合待遇享受条件的按未就业城乡居民待遇标准享受待遇"],"a":"A","e":"2026年3月26日，国家医保局等八部门印发《加快建立长期护理保险制度实施方案》，推进长期护理保险制度落地。A 项正确，《方案》指出：未就业城乡居民长期护理保险按年筹集资金，与城乡居民基本医疗保险费共同缴纳。筹资由个人缴费和政府补助构成，二者比例为1:1左右。政府补助由中央财政和地方财政共同承担。B 项错误，《方案》指出：退休人员由个人缴费，原用人单位不缴费。费率同单位职工个人费率，为0.15% 左右，缴费基数为本人基本养老金。C 项错误，《方案》指出：鼓励灵活就业人员按单位职工费率标准参保，由个人按规定缴费，费率0.3% 左右，缴费基数可按统筹地区上年度社会平均工资的一定比例（不低于60%）确定；灵活就业人员也可选择按未就业城乡居民参保政策参保缴费。D 项错误，《方案》指出：18周岁以下未就业人员跟随父母或其他法定抚养人等参保，不单独筹资，符合待遇享受条件的按未就业城乡居民待遇标准享受待遇。故本题选 A。"},{"id":"cg-1q16","n":16,"s":"习近平总书记强调，人们对建设优质高效医疗服务体系的期望很高，要继续优化体系布局，实施医疗卫生强基工程，促进分级诊疗。关于分级诊疗，下列说法正确的有几项？\n①以紧密型医联体为抓手完善分级诊疗协同机制\n②县域内推进以城带乡、以乡带村和县乡一体、乡村一体的紧密型县域医共体建设\n③以常见病、慢性病为重点引导群众到二、三级医院首诊\n④以提升就医连续性为导向加强转诊服务管理\n⑤完善基本医保同病同付政策","o":["2项","3项","4项","5项"],"a":"B","e":"2026年4月，国务院办公厅印发《关于加快建设分级诊疗体系的若干措施》的通知。\n①项正确，以紧密型医联体为抓手完善分级诊疗协同机制。\n②项正确，县域内推进以城带乡、以乡带村和县乡一体、乡村一体的紧密型县域医共体建设。\n③项错误，以常见病、慢性病为重点引导群众基层首诊。\n④项正确，以提升就医连续性为导向加强转诊服务管理。\n⑤项错误，完善基本医保差异性支付政策。故本题选 B。"},{"id":"cg-1q17","n":17,"s":"关于习近平总书记的重要指示，下列对应关系正确的是：","o":["服务业发展——坚持智能化、绿色化、融合化发展方向","哲学社会科学高质量发展——牢牢守住教育公平底线，弘扬教育家精神","基础教育高质量发展——落实立德树人根本任务，坚持健康第一教育理念","先进制造业发展——突出需求牵引、改革攻坚、科技赋能、开放合作"],"a":"C","e":"A 项错误，智能化、绿色化、融合化是先进制造业的发展方向。B 项错误，守住教育公平底线、弘扬教育家精神属于基础教育相关指示。C 项正确，基础教育指示要求，全面贯彻党的教育方针，落实立德树人根本任务，落实健康第一教育理念。D 项错误，需求牵引、改革攻坚、科技赋能、开放合作是服务业发展的要求。故本题选 C。"},{"id":"cg-1q18","n":18,"s":"2026年10月16日，《求是》杂志发表习近平总书记重要文章《以更高标准、更实举措推进全面从严治党》，文章指出，更加清醒坚定地推进反腐败斗争，以下相关说法不准确的是：","o":["党中央关于“反腐败斗争形势仍然严峻复杂，铲除腐败滋生土壤和条件任务仍然艰巨繁重”的判断是完全正确的，反腐败斗争永远在路上、永远是进行时","要聚焦权力集中、资金密集、资源富集领域，紧盯政商勾连、权力为资本提供保护、资本向政治领域渗透等问题，加大对“一把手”、年轻干部等贪腐问题查处力度","必须不断提高反腐败穿透力，要深化风腐同查同治，透过“风”的表象，揭开“腐”的本质","不敢腐、不能腐、不想腐环环相扣，要做好衔接，在工作中分阶段、分环节做好反腐实效"],"a":"D","e":"2026年10月16日，《求是》杂志发表习近平总书记重要文章《以更高标准、更实举措推进全面从严治党》，文章指出，事实再次表明，党中央关于“反腐败斗争形势仍然严峻复杂，铲除腐败滋生土壤和条件任务仍然艰巨繁重”的判断是完全正确的，反腐败斗争永远在路上、永远是进行时，必须以愚公移山、精卫填海的精神一抓到底；再次警示我们，腐败是我们党面临的最大风险、最大威胁、最大挑战，是党和国家事业发展进程中的拦路虎、绊脚石。A 项说法正确。要聚焦权力集中、资金密集、资源富集领域，紧盯政商勾连、权力为资本提供保护、资本向政治领域渗透等问题，加大对“一把手”、年轻干部等贪腐问题查处力度，着力清除不收敛不收手、肆意妄为的贪腐者，坚决查处明知故犯、一犯再犯的行贿人。B 项说法正确。要把握腐败新动向新特点，创新手段方式，进一步及时发现、准确识别、有效治理各类腐败问题。要深化风腐同查同治，透过“风”的表象，揭开“腐”的本质，深挖不作为乱作为背后的以商养官、以官护商、官商一体，彻查违规吃喝背后的请托办事、利益输送，严惩结交政治掮客、政治骗子等行为。C 项说法正确。一体推进不敢腐、不能腐、不想腐，重在“一体”，也难在“一体”，要强化系统观念，做到同时发力、同向发力、综合发力。实践中可以有所侧重，但不能割裂和偏废，防止阶段论、环节论影响反腐败实效。D 项说法有误。故本题选 D。"},{"id":"cg-1q19","n":19,"s":"习近平总书记指出：“只要保持战略定力，一步一个脚印坚定朝前走，一个阶段一个阶段扎实推进，党和国家事业就一定会不断积小胜为大胜，我们的目标就一定能实现。”这句话最能体现的哲学原理是：","o":["量变必然引起质变","社会规律由人的意志决定","量变是质变的前提和必要准备","事物发展是前进性和曲折性的统一"],"a":"C","e":"A 说法错误，量变达到一定程度必然引起质变。B 说法错误，社会规律属于规律的范畴，具有客观性，不以人的意志为转移。C 正确，题干 “一步一个脚印” “一个阶段一个阶段扎实推进” “积小胜为大胜” 强调的是通过持续、扎实的量的积累，为最终实现质的飞跃创造条件，体现了量变是质变的前提和必要准备。D 说法正确，但题干未涉及。故本题选 C。"},{"id":"cg-1q20","n":20,"s":"习近平总书记指出，要树立工匠精神，把第一线的大国工匠一批一批培养出来。“工匠精神”是指工匠对自己的产品精雕细琢、精益求精的精神理念。要倡导工匠精神，在全社会营造“人人重视质量、人人创造质量、人人享受质量”的浓厚氛围。重视商品质量的经济依据是（）。","o":["商品是用来交换的劳动产品","商品的使用价值与价格密不可分","商品是使用价值与价值的统一体","重视商品质量就能提高经济效益"],"a":"C","e":"商品是使用价值和价值的统一体，使用价值是价值的物质承担者，是商品价值实现的基础。商品生产者和经营者必须保证产品质量，才能实现价值。故本题选 C。"}]},{"id":"cg-2","cat":"zz","title":"超格考前五套卷 · 第二套","short":"超格第二套","sub":"20 题","questions":[{"id":"cg-2q1","n":1,"s":"党的二十届五中全会高度评价新时代全面从严治党的工作。下列相关说法错误的是：","o":["剥住了一些长期没有剥住的歪风，纠治了一些多年未除的顽瘴痼疾","消除了党、国家、军队内部存在的严重隐患，党在革命性锻造中更加坚强有力","开辟了百年大党自我革命新境界，推动党和国家事业取得历史性成就、发生历史性变革，党和人民赢得强党强国的历史主动","要清醒认识到管党治党不严不实不力的情况仍然存在，管党治党宽松软状况尚未根本扭转"],"a":"D","e":"党的二十届五中全会高度评价新时代全面从严治党取得的伟大成就。一致认为，以习近平同志为核心的党中央以巨大的政治勇气和强烈的责任担当，直面一度出现党的领导弱化虚化淡化、管党治党不严不实不力、党内一些问题触目惊心的严峻现实，坚定不移全面从严治党，刀刃向内、重典治乱，持续解决突出问题，从根本上扭转了管党治党宽松软状况，刹住了一些长期没有刹住的歪风，纠治了一些多年未除的顽瘴痼疾，消除了党、国家、军队内部存在的严重隐患，党在革命性锻造中更加坚强有力。新时代全面从严治党开辟了百年大党自我革命新境界，推动党和国家事业取得历史性成就、发生历史性变革，党和人民赢得强党强国的历史主动。故本题选D。"},{"id":"cg-2q2","n":2,"s":"习近平总书记强调，中国式现代化是全体人民共同富裕的现代化。下列与之有关的说法正确的是：\n①扎实推进共同富裕，最艰难最繁重的任务仍然在农村，必须逐步缩小城乡差距\n②坚持把实现人民对美好生活的向往作为现代化建设的出发点和落脚点，着力促进全体人民共同富裕\n③实现共同富裕，要先把“蛋糕”做大，然后通过合理的制度安排把“蛋糕”分好，水涨船高、各得其所\n④社会主义市场经济体制是促进共同富裕的基础性制度，要推动有效市场和有为政府更好结合","o":["①②③","②③④","①②④","①③④"],"a":"A","e":"①正确，全面建设社会主义现代化国家，扎实推进共同富裕，最艰巨最繁重的任务仍然在农村，必须逐步缩小城乡差距。②正确，共同富裕是中国特色社会主义的本质要求，也是一个长期的历史过程。我们坚持把实现人民对美好生活的向往作为现代化建设的出发点和落脚点，着力维护和促进社会公平正义，着力促进全体人民共同富裕，坚决防止两极分化。③正确，中国要实现共同富裕，但不是搞平均主义，而是要先把“蛋糕”做大，然后通过合理的制度安排把“蛋糕”分好，水涨船高、各得其所，让发展成果更多更公平惠及全体人民。④错误，分配制度是促进共同富裕的基础性制度。坚持按劳分配为主体、多种分配方式并存，构建初次分配、再分配、第三次分配协调配套的制度体系。故本题选 A。"},{"id":"cg-2q3","n":3,"s":"2026年10月，《中共中央 国务院关于发展新质生产力的意见》重磅发布，《意见》指出，大力推进科技创新，以下说法正确的是：","o":["强化目标导向转向自由探索主导，通过有组织的基础研究、应用基础研究解决技术科学和工程科学薄弱问题","以市场迫切需要为导向，优化国家科研机构、高水平研究型大学、科技领军企业定位和布局","加强普惠激励政策供给，建立财政研发准备金制度，强化政府科技投入主导作用","探索建立科技项目全过程评价机制，立项时一体部署研发和转化任务，验收时考核应用实绩"],"a":"D","e":"2026年10月，《中共中央 国务院关于发展新质生产力的意见》重磅发布，《意见》指出，大力推进科技创新。坚持面向世界科技前沿、面向经济主战场、面向国家重大需求、面向人民生命健康，聚焦战略性、标志性、引领性产品组织重大科技项目。坚持目标导向和自由探索并重，通过有组织的基础研究、应用基础研究解决技术科学和工程科学薄弱问题，支持自由探索类基础研究开拓创新。A 项说法不正确。发挥国家实验室组织国家重大科技项目、建设国家重大创新平台等方面作用，在体制机制改革上先行先试。以国家战略需求为导向，优化国家科研机构、高水平研究型大学、科技领军企业定位和布局。B 项说法不正确。加强普惠激励政策供给，建立企业研发准备金制度，强化企业科技投入主导作用。鼓励科技型中小企业加大研发投入，提高企业研发费用加计扣除比例。C 项说法不正确。探索建立科技项目全过程评价机制，立项时一体部署研发和转化任务，验收时考核应用实绩，解决技术开发与成果转化脱节问题。引导高等学校、科研院所按照先使用后付费方式把科技成果许可给中小微企业使用。推动大企业向中小微企业开放供应链，支持中小微企业成为成果产业化的重要力量。D 项说法正确。故本题选 D。"},{"id":"cg-2q4","n":4,"s":"习近平总书记在二十届中央纪委五次全会上发表重要讲话强调，要以更高标准更实举措推进全面从严治党。下列相关说法正确的有几项？\n①贯彻落实党中央重大决策部署，是维护党中央权威和集中统一领导的根本要求，也是党和人民事业不断发展进步的重要历史经验\n②党的自我革命重在治权，把权力关进制度笼子是新时代全面从严治党的一项重要任务\n③把权力关进制度笼子，既要不断完善制度规定，使制度密而不繁、有效管用，又要着力提高制度执行力，增强刚性约束\n④我们党成功走出一条在党中央集中统一领导下，标本兼治、一体推进不敢腐不能腐不想腐的中国特色反腐败之路，要坚定走下去⑤要在一体推进上下更大功夫，强化系统观念，加强联动配合，把各方面监督贯通起来，以全链条协作促进一体化治理","o":["2项","3项","4项","5项"],"a":"D","e":"习近平总书记在二十届中央纪委五次全会上发表重要讲话强调，贯彻落实党中央重大决策部署，是维护党中央权威和集中统一领导的根本要求，也是党和人民事业不断发展进步的重要历史经验。①说法正确。党的自我革命重在治权，把权力关进制度笼子是新时代全面从严治党的一项重要任务。党的十八大后，党中央以制定实施中央八项规定开局破题，立铁规矩、强硬约束，推动党风政风焕然一新。把权力关进制度笼子，既要不断完善制度规定，使制度密而不繁、有效管用，又要着力提高制度执行力，增强刚性约束。要坚持法规制度面前人人平等、遵守法规制度没有特权、执行法规制度没有例外，确保制度规定真正成为带电的高压线。②③说法正确。腐败是党和国家事业发展进程中的拦路虎、绊脚石，反腐败是一场输不起也决不能输的重大斗争。党的十八大以来，我们党成功走出一条在党中央集中统一领导下，标本兼治、一体推进不敢腐不能腐不想腐的中国特色反腐败之路，要坚定走下去。当前，反腐败斗争形势仍然严峻复杂，铲除腐败滋生土壤和条件任务仍然艰巨繁重。要保持高压态势不动摇，有腐必反、有贪必肃、除恶务尽，让腐败分子没有藏身之地。要把握腐败的新动向新特点，创新手段方式，完善反腐败责任落实机制，及时发现、准确识别、有效治理各类腐败问题，不断提高反腐败穿透力。要在一体推进上下更大功夫，强化系统观念，加强联动配合，把各方面监督贯通起来，以全链条协作促进一体化治理。④⑤说法正确。故本题选 D。"},{"id":"cg-2q5","n":5,"s":"习近平总书记强调，要高质量推进国防和军队现代化，如期实现建军一百年奋斗目标。下列关于高质量推进国防和军队现代化的表述不正确的是：\n①依法治军是人民军队立军之本，关乎国防和军队现代化建设方向和底色\n②高质量推进国防和军队现代化，根本指向和检验标准始终是凝聚力\n③巩固提高一体化国家战略体系和能力，是高质量推进国防和军队现代化的必由之路\n④高质量推进国防和军队现代化，是推进中国式现代化的应有之义","o":["①②","③④","①③","②④"],"a":"A","e":"2026年7月30日，中共中央政治局就高质量推进国防和军队现代化进行第二十七次集体学习。习近平总书记主持学习并发表重要讲话。①错误，讲话指出：政治建军是人民军队立军之本，关乎国防和军队现代化建设方向和底色。②错误，讲话指出：高质量推进国防和军队现代化，根本指向和检验标准始终是战斗力。③正确，讲话指出：巩固提高一体化国家战略体系和能力，是高质量推进国防和军队现代化的必由之路。④正确，讲话指出：高质量推进国防和军队现代化，是推进中国式现代化的应有之义。本题为选非题，故本题选 A。"},{"id":"cg-2q6","n":6,"s":"习近平总书记赴多地考察调研，立足各地资源禀赋作出一系列重要部署。下列对应关系正确的有：\n①河北雄安新区——牢牢把握作为北京非首都功能疏解集中承载地的首要功能定位\n②上海——注重“算电协同”、“算水协同”，搞好算力中心项目建设和运营\n③山东德州——以扎实举措推进农业农村现代化，因地制宜推进宜居宜业和美乡村建设\n④北京——建设社会主义现代化强国，关键在科技自立自强，要发挥自身优势在这方面作出更大贡献","o":["4项","3项","2项","1项"],"a":"B","e":"①对应正确，2026年3月23日，习近平总书记在河北雄安新区考察时强调，要牢牢把握雄安新区作为北京非首都功能疏解集中承载地的首要功能定位，保持战略定力和历史耐心，进一步解放思想、开拓思路、加强协调、凝聚合力，以改革创新为引领增强内生发展动力，以要素资源合理集聚为重点激发新区活力，努力建设新时代创新高地和推动高质量发展样板。②对应错误，2026年10月16日，习近平总书记在内蒙古乌兰察布考察时强调，绿色发展是高质量发展的应有之义，要统筹高质量发展和高水平保护，坚持山水林田湖草沙一体化保护和系统治理，协同推进降碳、减污、扩绿、增长，坚定不移走生态优先、绿色发展之路。习近平总书记指出，希望大家认真落实高效、绿色、安全的要求，注重“算电协同”、“算水协同”，搞好算力中心项目建设和运营，积极推动绿色算力产业发展，为推进数字中国建设、促进新质生产力发展多作贡献。2026年7月15日，习近平在上海考察时强调，高质量推进城市更新是城市现代化建设的重要抓手，要全面践行人民城市理念，坚持问需于民、问计于民、问效于民，做深做细做实城市更新各项工作，不断增强居民群众的获得感、幸福感、安全感。③对应正确，2026年6月24日，习近平在山东德州考察时强调，农业农村现代化关系中国式现代化全局和成色，要以扎实举措做好各项工作，着力提升农业综合生产能力和质量效益，确保粮食等重要农产品稳定供给，因地制宜推进宜居宜业和美乡村建设，引导广大农民群众用勤劳和智慧创造更加美好生活。④对应正确，2026年2月9日，习近平在北京考察时强调，建设社会主义现代化强国，关键在科技自立自强，北京要发挥自身优势，在这方面作出更大贡献。综上，①③④对应正确，共3项。故本题选 B。"},{"id":"cg-2q7","n":7,"s":"强大国内市场是中国式现代化的战略依托。关于建设强大国内市场，加快构建新发展格局，下列说法正确的是：","o":["强化公平竞争审查刚性约束，消除要素获取、资质认定、招标投标、政府采购等方面壁垒","深化汽车消费从使用管理向购买管理转变，拓展汽车改装、租赁等后市场消费","完善市场准入制度，严格落实“全国一张清单”管理要求，持续扩充市场准入负面清单","完善协调统一的国家标准体系，缩减强制性国家标准覆盖面，推进新兴产业标准建设"],"a":"A","e":"2026年3月12日，十四届全国人大四次会议表决通过《中华人民共和国国民经济和社会发展第十五个五年规划纲要》的决议。A 项正确，《纲要》指出：制定重点领域公平竞争合规指引，强化公平竞争审查刚性约束，消除要素获取、资质认定、招标投标、政府采购等方面壁垒。B 项错误，《纲要》指出：深化汽车消费从购买管理向使用管理转变，完善充换电、停车场等基础设施，拓展汽车改装、租赁等后市场消费。C 项错误，《纲要》指出：完善市场准入制度，动态修订市场准入负面清单，严格落实“全国一张清单”管理要求。D 项错误，《纲要》指出：完善协调统一的国家标准体系，扩大强制性国家标准覆盖面，推进新兴产业标准建设，提升标准国际化水平。故本题选 A。"},{"id":"cg-2q8","n":8,"s":"我国金融机构门类齐全、数量众多，要引导金融机构深耕主业、错位发展，持续提升金融体系的适应性和竞争力。下列金融机构与其定位对应不正确的是：","o":["国有大型金融机构——更好发挥服务实体经济的主力军和维护金融稳定的压舱石作用","政策性金融机构——聚焦服务国家战略，主要做商业性金融机构干不了、干不好的业务","地方中小金融机构——促进其减量提质、扎根当地开展特色化经营","资管、非银等机构——引导其充分发挥经济减震器和社会稳定器功能"],"a":"D","e":"支持国有大型金融机构更好发挥服务实体经济的主力军和维护金融稳定的压舱石作用。推动政策性金融机构聚焦服务国家战略，主要做商业性金融机构干不了、干不好的业务。对于地方中小金融机构，促进其减量提质、扎根当地开展特色化经营。对于保险业，引导其充分发挥经济减震器和社会稳定器功能。对于资管、非银等机构，督促其在做优财富管理、畅通直接融资、丰富多元金融服务等方面发挥独特作用。故本题选 D。"},{"id":"cg-2q9","n":9,"s":"党的二十届五中全会提出，一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本方针。下列各项不属于一体推进不敢腐不能腐不想腐措施的是：","o":["夯实崇廉拒腐思想根基","加强对权力运行的制约和监督","坚持和完善“第一议题”制度","保持惩治腐败高压态势"],"a":"C","e":"一体推进不敢腐不能腐不想腐举措包括：保持惩治腐败高压态势；加强对权力运行的制约和监督；夯实崇廉拒腐思想根基；增强一体推进不敢腐不能腐不想腐综合效能。“坚持和完善‘第一议题’制度”属于增强共产党人的党性的举措。故本题选 C。"},{"id":"cg-2q10","n":10,"s":"习近平总书记在纪念中国工农红军长征胜利90周年大会上的讲话指出，红军长征创造了非凡的人间奇迹，铸就了伟大长征精神。关于伟大长征精神，以下说法正确的有几项？\n①就是把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信念，坚信正义事业必然胜利的精神\n②就是为了救国救民，不怕任何艰难险阻，不惜付出一切牺牲的精神\n③就是坚持独立自主、实事求是，一切从实际出发的精神\n④就是顾全大局、严守纪律、紧密团结的精神\n⑤就是紧紧依靠人民群众，同人民群众生死相依、患难与共、艰苦奋斗的精神","o":["2项","3项","4项","5项"],"a":"D","e":"红军长征创造了非凡的人间奇迹，铸就了伟大长征精神。伟大长征精神，就是把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信念，坚信正义事业必然胜利的精神；就是为了救国救民，不怕任何艰难险阻，不惜付出一切牺牲的精神；就是坚持独立自主、实事求是，一切从实际出发的精神；就是顾全大局、严守纪律、紧密团结的精神；就是紧紧依靠人民群众，同人民群众生死相依、患难与共、艰苦奋斗的精神。故本题选D。"},{"id":"cg-2q11","n":11,"s":"习近平总书记强调，一切向前走，都不能忘记走过的路，走得再远、走到再光辉的未来，也不能忘记走过的过去，不能忘记为什么出发。这段论述体现了习近平总书记治国理政的哪种思维？","o":["系统思维","底线思维","历史思维","创新思维"],"a":"C","e":"习近平总书记在党史学习教育动员大会上的讲话指出，历史是最好的老师，我们党的历史是中国近现代以来历史最为可歌可泣的篇章，历史在人民探索和奋斗中造就了中国共产党，我们党团结带领人民又造就了历史悠久的中华文明新的历史辉煌。一切向前走，都不能忘记走过的路，走得再远、走到再光辉的未来，也不能忘记走过的过去，不能忘记为什么出发。这段论述强调从历史中汲取智慧、在历史纵深中把握现实和未来，体现了以史为鉴、知古鉴今的历史思维。故本题选C。"},{"id":"cg-2q12","n":12,"s":"习近平总书记指出，必须持之以恒推进全面从严治党，深入推进新时代党的建设新的伟大工程。关于党的建设，以下说法正确的是：","o":["严明党的纪律，首要的就是严明群众纪律，群众纪律是最重要、最根本、最关键的纪律","加强党内法规制度建设是全面从严治党的长远之策、根本之策","党要管党，首先要从党内组织生活管起；从严治党，首先要从党内组织生活严起","领导干部要把锤炼党性、提高思想觉悟作为终身课题，把理论修养摆在党性修养的首位，从党的创新理论中汲取党性滋养"],"a":"B","e":"2026年6月23日，《习近平党建文选》第一卷、第二卷出版发行。《习近平党建文选》指出，我们党是靠革命理想和铁的纪律组织起来的马克思主义政党，纪律严明是党的光荣传统和独特优势。严明党的纪律，首要的就是严明政治纪律。政治纪律是最重要、最根本、最关键的纪律，遵守党的政治纪律是遵守党的全部纪律的重要基础。强调：党章是我们党的总章程、总规矩。严明政治纪律就要从遵守和维护党章入手。遵守党的政治纪律，最核心的，就是坚持党的领导，同党中央保持高度一致，自觉维护中央权威。A项说法不准确。加强党内法规制度建设是全面从严治党的长远之策、根本之策。必须坚持依法治国与制度治党、依规治党统筹推进、一体建设。B项说法正确。严肃党内政治生活是全面从严治党的基础。党要管党，首先要从党内政治生活管起；从严治党，首先要从党内政治生活严起。党的执政地位，决定了党内监督在党和国家各种监督形式中是最基本的、第一位的。C项说法不准确。领导干部要把锤炼党性、提高思想觉悟作为终身课题，把政治修养摆在党性修养的首位，从党的创新理论中汲取党性滋养，把学习遵守贯彻党章党规党纪作为党性修养的重要内容，活到老、学到老、修养到老。D项说法不准确。故本题选 B。"},{"id":"cg-2q13","n":13,"s":"2026年5月16日《求是》发表习近平总书记重要文章《做强做优做大实体经济》，下列相关说法正确的是：","o":["供给侧结构性改革是振兴实体经济的主要任务，振兴实体经济要向供给侧结构性改革发力、聚力","实体经济是一国经济的立身之本，是财富创造的根本源泉，是国家强盛的重要支柱","以科技创新为引领、以实体经济为根基，在全面推进传统产业转型升级的基础上有序发展新兴产业、布局未来产业","实体经济是金融的根基，金融是实体经济的血脉，金融要致力于实现自我循环、自我膨胀"],"a":"D","e":"2026年5月16日《求是》发表习近平总书记重要文章《做强做优做大实体经济》，文章指出，振兴实体经济是供给侧结构性改革的主要任务，供给侧结构性改革要向振兴实体经济发力、聚力。不论经济发展到什么时候，实体经济都是我国经济发展、我们在国际经济竞争中赢得主动的根基。A项说法不准确。实体经济是一国经济的立身之本，是财富创造的根本源泉，是国家强盛的重要支柱。要深化供给侧结构性改革，加快发展先进制造业，推动互联网、大数据、人工智能同实体经济深度融合，推动资源要素向实体经济集聚、政策措施向实体经济倾斜、工作力量向实体经济加强。B项说法正确。“十五五”时期，必须把因地制宜发展新质生产力摆在更加突出的战略位置，以科技创新为引领、以实体经济为根基，坚持全面推进传统产业转型升级、积极发展新兴产业、超前布局未来产业并举，加快建设现代化产业体系。C项说法不准确。坚持把金融服务实体经济作为根本宗旨。实体经济是金融的根基，金融是实体经济的血脉，服务实体经济是金融的天职。如果热衷于自我循环、自我膨胀，金融就会变成无源之水、无本之木，迟早酿成危机。D项说法不准确。故本题选 B。"},{"id":"cg-2q14","n":14,"s":"2026年5月13日至15日，应国家主席习近平邀请，美国总统对中国进行国事访问。两国元首一致赞同将构建 “中美建设性战略稳定关系” 作为中美关系新定位。关于 “中美建设性战略稳定关系”，下列说法正确的有几项？\n①应该是合作为主的积极稳定，中美作为世界前两大经济体，你中有我、我中有你，谁也离不开谁，合则两利、斗则俱伤\n②应该是竞争有度的良性稳定，中美之间即便有竞争，也应是相互借鉴的良性竞争，你追我赶的积极竞争，遵守规则的公平竞争\n③应该是分歧可控的常态稳定，双方都应保持政策的连续性和稳定性，尤其要信守作出的承诺，始终相向而行\n④应该是和平可期的持久稳定，不能发生冲突对抗甚至战争，和平共处是中美两国的最大公约数，中美冲突对抗的后果是谁都不能承受的","o":["1项","2项","3项","4项"],"a":"B","e":"两国元首同意将“中美建设性战略稳定关系”作为两国关系的新定位，为未来3年乃至更长时间的中美关系作出战略指引，受到两国人民和国际社会的欢迎。中方认为：这应该是合作为主的积极稳定，通过交流合作不断增强中美关系的韧性。中美作为世界前两大经济体，你中有我、我中有你，谁也离不开谁，合则两利、斗则俱伤。对抗对两国和世界注定是一场灾难，合作则可以办成许多有利于两国和世界的大事。这应该是竞争有度的良性稳定，不搞你输我赢的零和博弈。大国之间存在竞争不足为奇，但不能以竞争来定义全部中美关系。中美之间即便有竞争，也应是相互借鉴的良性竞争，你追我赶的积极竞争，遵守规则的公平竞争。竞争的目的是为了彼此做更好的自己。这应该是分歧可控的常态稳定，不能像过山车一样起伏不定。双方都应保持政策的连续性和稳定性，尤其要信守作出的承诺，始终相向而行，以中美合作的正面预期为各自发展和国际形势提供更多的确定性。这应该是和平可期的持久稳定，不能发生冲突对抗甚至战争。和平共处是中美两国的最大公约数，中美冲突对抗的后果是谁都不能承受的。关键在于遵守中美三个联合公报，尊重彼此社会制度和发展道路，尊重对方核心利益和重大关切，尊重各自的发展权利。故本题选D。"},{"id":"cg-2q15","n":15,"s":"2026年6月16日，《求是》杂志发表习近平总书记重要文章《一体推进教育科技人才发展》，文章指出，培养人才是国家和民族长远发展的大计。关于培养人才，以下说法正确的是：","o":["中国是一个大国，对人才数量、质量、结构的需求是全方位的，满足这样庞大的人才需求必须完全依靠自己培养，提高人才供给自主可控能力","人才培养首先要聚焦解决基础研究人才数量不足、质量不高问题","发挥企业特别是创新型企业人才培养主力军作用，加强国家急需高层次人才培养","要以应用研究为牵引，着眼提高创新能力，完善高校学科设置调整机制和人才培养模式，超常布局急需学科专业"],"a":"B","e":"2026年6月16日，《求是》杂志发表习近平总书记重要文章《一体推进教育科技人才发展》，文章指出，培养人才是国家和民族长远发展的大计，当今世界人才的竞争首先是人才培养的竞争。中国是一个大国，对人才数量、质量、结构的需求是全方位的，满足这样庞大的人才需求必须主要依靠自己培养，提高人才供给自主可控能力。A项说法不准确。人才培养首先要聚焦解决基础研究人才数量不足、质量不高问题。高校特别是“双一流”大学要发挥培养基础研究人才主力军作用，全方位谋划基础学科人才培养，突破常规，创新模式，更加重视科学精神、创新能力、批判性思维的培养教育。B项说法正确。要坚持走基础研究人才自主培养之路，深入实施“中学生英才计划”“强基计划”“基础学科拔尖学生培养计划”，优化基础学科教育体系，发挥高校特别是“双一流”高校基础研究人才培养主力军作用，加强国家急需高层次人才培养，源源不断地造就规模宏大的基础研究后备力量。C项说法不准确。要以科技发展、国家战略需求为牵引，着眼提高创新能力，完善高校学科设置调整机制和人才培养模式，超常布局急需学科专业，加强基础学科、新兴学科、交叉学科建设和拔尖人才培养。强化高水平研究型大学国家基础研究主力军和重大科技突破策源地作用，提高基础研究组织化程度，实施基础学科和交叉学科突破计划，建立科技创新与人才培养相互支撑、带动学科高质量发展的有效机制，从国家战略需求中凝练重大科技问题，持续产出原创性、颠覆性科技创新成果。D项说法不准确。故本题选 B。"},{"id":"cg-2q16","n":16,"s":"中共中央办公厅、国务院办公厅印发《关于加快建立长期护理保险制度的意见》，提出长期护理保险制度是我国社会保障体系的重要组成部分，是实施积极应对人口老龄化国家战略的重要内容。下列与长期护理保险制度有关的说法正确的是：\n①统一保险统筹层次，长期护理保险从省级统筹起步，全省基金统收统支\n②合理确定保障对象，长期护理保险制度起步阶段保障各类失能老年人\n③统筹城乡制度安排，长期护理保险基金统一建账，资金统筹使用\n④建立稳定筹资渠道，建立健全单位、个人、政府、社会等多元筹资渠道","o":["①②","③④","①③","②④"],"a":"B","e":"2026年3月，中共中央办公厅、国务院办公厅印发《关于加快建立长期护理保险制度的意见》。①错误，《意见》指出：统一保险统筹层次。长期护理保险从市地级统筹起步。市地级统筹地区制度政策统一、基金统收统支、管理服务一体。②错误，《意见》指出：合理确定保障对象。长期护理保险制度起步阶段保障重度失能人员。③正确，《意见》指出：统筹城乡制度安排。长期护理保险基金统一建账，资金统筹使用。④正确，《意见》指出：建立稳定筹资渠道。建立健全单位、个人、政府、社会等多元筹资渠道。故本题选 B。"},{"id":"cg-2q17","n":17,"s":"根据2026年中央一号文件《中共中央 国务院关于锚定农业农村现代化 扎实推进乡村全面振兴的意见》，下列说法正确的是：\n①推进农产品进口多元化，支持扩大优势特色农产品出口\n②健全连续参保激励约束机制，稳步提高医保基金在县乡村医疗卫生机构使用比例\n③加强农产品市场监测预警和信息发布，统筹做好市场化收购和政策性收储\n④把常态化帮扶纳入乡村振兴战略统筹实施，保持财政投入、金融支持、资源要素配置等方面政策总体稳定","o":["①②③","①③④","②③④","①②③④"],"a":"D","e":"①正确，促进农产品贸易和生产相协调。推进农产品进口多元化。培育具有国际竞争力的农业企业。支持扩大优势特色农产品出口。②正确，巩固拓展农村居民医保参保成果，健全连续参保激励约束机制，稳步提高医保基金在县乡村医疗卫生机构使用比例。③正确，加强农产品市场监测预警和信息发布，统筹做好市场化收购和政策性收储，促进粮食等重要农产品价格保持在合理水平。④正确，把常态化帮扶纳入乡村振兴战略统筹实施，保持财政投入、金融支持、资源要素配置等方面政策总体稳定。故本题选 D。"},{"id":"cg-2q18","n":18,"s":"法律是治国理政最大最重要的规矩，全面依法治国为制度之治提供最基本最稳定最可靠的保障。关于全面依法治国，以下说法不准确的是：","o":["中国特色社会主义法治道路的核心要义，就是要坚持党的领导，坚持中国特色社会主义制度，贯彻中国特色社会主义法治理论","党的领导是中国特色社会主义法治之魂，是我们的法治同西方资本主义国家的法治最大的区别","建设中国特色社会主义法治体系、建设社会主义法治国家是全面推进依法治国的总目标，建设中国特色社会主义法治体系是全面推进依法治国的总抓手","法治国家是法治建设的目标，法治社会建设是全面依法治国的重点任务和主体工程"],"a":"D","e":"中国特色社会主义法治道路的核心要义，就是要坚持党的领导，坚持中国特色社会主义制度，贯彻中国特色社会主义法治理论。A 项说法正确。党的领导是中国特色社会主义法治之魂，是我们的法治同西方资本主义国家的法治最大的区别。B 项说法正确。党的十八届四中全会将建设中国特色社会主义法治体系、建设社会主义法治国家确定为全面推进依法治国的总目标，将建设中国特色社会主义法治体系确定为全面推进依法治国的总抓手。C 项说法正确。坚持法治国家、法治政府、法治社会一体建设。法治国家是法治建设的目标。法治政府建设是全面依法治国的重点任务和主体工程。法治社会是构筑法治国家的基础。D 项说法不正确。故本题选 D。"},{"id":"cg-2q19","n":19,"s":"习近平总书记指出，矛盾是普遍存在的，矛盾是事物联系的实质内容和事物发展的根本动力，人的认识活动和实践活动，从根本上说就是不断认识矛盾、不断解决矛盾的过程。关于马克思主义矛盾观，下列说法正确的是：","o":["矛盾的主要方面和次要方面交替决定事物的性质","矛盾存在于一切事物之中、贯通于一切事物发展的始终","同一性寓于斗争性之中，斗争性通过同一性来体现","矛盾普遍性构成这个事物区别于其他事物的特殊本质"],"a":"B","e":"A 错误，事物的性质由主要矛盾的主要方面决定。B 正确，矛盾存在于一切事物之中并贯穿于整个事物的始终，即事事有矛盾、处处有矛盾。C 错误，矛盾的同一性和斗争性是矛盾的两种基本属性，斗争性寓于同一性之中，同一性通过斗争性来体现。D 错误，矛盾的特殊性是世界上诸事物之所以千差万别的内在原因，构成这个事物区别于其他事物的特殊本质。故本题选 B。"},{"id":"cg-2q20","n":20,"s":"党的十八大以来，以习近平同志为核心的党中央以前所未有的决心力度推进全面从严治党，以党的政治建设统领党的建设各项工作，系统构建全面从严治党体系。习近平党建思想是对全面从严治党实践经验的概括和凝练，是习近平新时代中国特色社会主义思想的重要组成部分，为深入推进新时代党的建设新的伟大工程提供了根本遵循和行动指南。这说明了：","o":["认识总是来源于实践并能够指导实践","认识决定于实践并始终落后于实践","实践是探索世界规律的科学实验活动","实践的需要始终是认识正确与否的检验标准"],"a":"A","e":"A 项正确，习近平党建思想提炼自全面从严治党实践经验，又为新时代党的建设提供根本遵循和行动指南，体现认识来源于实践，并能够指导实践。B 说法错误，认识具有相对独立性，可以超前于实践，并非始终落后于实践。C 说法错误，实践不只是科学实验活动，还包括生产实践、社会政治实践等。D 说法错误，实践是检验认识正确与否的唯一标准，不是实践的需要。故本题选 A。"}]},{"id":"cg-3","cat":"zz","title":"超格考前五套卷 · 第三套","short":"超格第三套","sub":"20 题","questions":[{"id":"cg-3q1","n":1,"s":"2026年10月26日至29日，党的二十届五中全会在北京举行，对持之以恒推进全面从严治党作出系统部署，提出一系列战略任务和重大举措。关于全面从严治党，下列说法正确的是：","o":["民主集中制是党的生命线和根本工作路线","党的各级组织是全面从严治党的主体","一体推进不敢腐不能腐不想腐是全面从严治党的根本性任务","锻造堪当民族复兴重任的高素质干部队伍是全面从严治党的长远之策、根本之策"],"a":"B","e":"A 错误，民主集中制是党的根本组织原则和领导制度，贯彻执行民主集中制是全面从严治党的内在要求。群众路线是我们党的生命线和根本工作路线。B 正确，党的各级组织是全面从严治党的主体。C 错误，增强党性是全面从严治党的根本性任务。一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本方针。D 错误，加强党内法规制度建设是全面从严治党的长远之策、根本之策。故本题选 B。"},{"id":"cg-3q2","n":2,"s":"习近平党建思想源自于马克思主义科学理论，植根于中华优秀传统文化，孕育于新时代全面从严治党的伟大实践，下列相关说法正确的是：","o":["我们党是马克思主义政党，党的根基和血脉在马克思主义科学理论指导","必须坚持依法治国与制度治党、依规治党统筹推进、一体建设","党的执政地位，决定了接受人民监督在党和国家各种监督形式中是最基本的、第一位的","党的思想建设决定党的建设方向和效果，不抓党的思想建设或背离党的思想建设指引的方向，党的其他建设就难以取得预期成效"],"a":"B","e":"2026年6月23日，《习近平党建文选》第一卷、第二卷出版发行。《习近平党建文选》指出，我们党来自于人民，党的根基和血脉在人民。为人民而生，因人民而兴，始终同人民在一起，为人民利益而奋斗，是我们党立党兴党强党的根本出发点和落脚点。A 项说法不准确。加强党内法规制度建设是全面从严治党的长远之策、根本之策。必须坚持依法治国与制度治党、依规治党统筹推进、一体建设。要突出重点，重在管用有效，全方位扎紧制度笼子，更多用制度治党、管权、治吏。B 项说法正确。加强和规范党内政治生活、加强党内监督就是重点发力的抓手。严肃党内政治生活是全面从严治党的基础。党要管党，首先要从党内政治生活管起；从严治党，首先要从党内政治生活严起。党的执政地位，决定了党内监督在党和国家各种监督形式中是最基本的、第一位的。强调：全面加强和规范党内政治生活，要抓好思想教育这个根本，抓好严明纪律这个关键，抓好选人用人这个导向，用好组织生活这个经常性手段，抓住继承和创新这两个关键环节。C 项说法不准确。党的政治建设决定党的建设方向和效果，不抓党的政治建设或背离党的政治建设指引的方向，党的其他建设就难以取得预期成效。D 项说法不准确。故本题选 B。"},{"id":"cg-3q3","n":3,"s":"习近平总书记指出，我国经济是靠实体经济起家的，也要靠实体经济走向未来。关于发展实体经济，以下说法正确的是：","o":["实体经济是制造业的基础，是我国发展的本钱，是构筑未来发展战略优势的重要支撑","坚持把发展经济的着力点放在实体经济上，推进新型工业化，加快建设制造强国、质量强国、航天强国、交通强国、网络强国、数字中国","要加强人力资源开发，促进由重物质资本向重人力资本转变，做到投资于物转向投资于人","我国仍处于工业化发展阶段，制造业占比居高不下，要加强政策引导，下调制造业比重"],"a":"B","e":"2026年5月16日《求是》发表习近平总书记重要文章《做强做优做大实体经济》，文章指出，制造业是实体经济的基础，实体经济是我国发展的本钱，是构筑未来发展战略优势的重要支撑。A 项“实体经济是制造业的基础”说法有误。坚持把发展经济的着力点放在实体经济上，推进新型工业化，加快建设制造强国、质量强国、航天强国、交通强国、网络强国、数字中国。实施产业基础再造工程和重大技术装备攻关工程，支持专精特新企业发展，推动制造业高端化、智能化、绿色化发展。B 项说法正确。必须坚持投资于物和投资于人紧密结合。既要扩大对实体经济和科技创新的有效投资，又要加强人力资源开发，促进物质资本和人力资本积累相协调，做到投资于物和投资于人双向赋能、相互促进。C 项说法有误。制造业是立国之本、强国之基。我国仍处于工业化发展阶段，却已出现制造业占经济比重过快下降问题，必须引起高度关注。要把制造业高质量发展放到更加突出的位置，采取有力措施，推动先进制造业和现代服务业深度融合，坚定不移建设制造强国。D 项说法有误。故本题选 B。"},{"id":"cg-3q4","n":4,"s":"习近平总书记在全国卫生与健康大会上强调，坚定不移走中国特色卫生与健康发展道路，确保“十五五”时期健康中国建设取得决定性进展。关于卫生与健康事业，以下说法不正确的是：","o":["我们要建成的健康中国，是均衡普惠、优质高效的健康中国，应当具有强大的健康管理能力、疾病防控能力、医疗服务能力、医保支撑能力、医药创新能力、人才培养能力","分级诊疗是最经济最有效的健康策略，要抓细抓好卫生与健康各项基础性、源头性工作，夯实全民健康根基","要坚持把推进医疗、医保、医药协同发展和治理作为医药卫生体制改革的主攻方向","要把保障人民健康融入各项政策，体现到各方面工作之中，规划制定、政策设计、项目论证、工程建设等都优先考虑对人民健康的影响"],"a":"B","e":"习近平总书记在全国卫生与健康大会上强调，我们要建成的健康中国，是均衡普惠、优质高效的健康中国，应当具有强大的健康管理能力、疾病防控能力、医疗服务能力、医保支撑能力、医药创新能力、人才培养能力，能够有效满足人民群众日益增长的健康需求，主要健康指标持续稳步提升。A 项说法正确。预防是最经济最有效的健康策略，要抓细抓好卫生与健康各项基础性、源头性工作，夯实全民健康根基。引导全社会树立正确健康观，进行有效的健康自塑和管理。B 项说法不正确。改革是卫生与健康事业发展的强大动力，要坚持把推进医疗、医保、医药协同发展和治理作为医药卫生体制改革的主攻方向。全面落实医疗卫生事业单位改革方案，以公益性为导向深化公立医院改革，加强县区、基层医疗机构运行保障。C 项说法正确。卫生与健康事业具有全局性、基础性作用，必须坚定实施健康优先发展战略。要把保障人民健康融入各项政策，体现到各方面工作之中，规划制定、政策设计、项目论证、工程建设等都优先考虑对人民健康的影响。D 项说法正确。故本题选 B。"},{"id":"cg-3q5","n":5,"s":"“十五五”规划纲要提出，加快构建高水平社会主义市场经济体制，增强高质量发展动力。下列举措不符合这一政策要求的有几项？\n①深化国资国企改革，增强国有企业核心功能、提升核心竞争力\n②发展壮大民营经济，持续推进基础设施竞争性领域向民营企业公平开放\n③完善主要由市场竞争关系决定价格机制，加强和改进价格治理\n④适当加强中央事权、提高中央财政支出比重，增加地方自主财力\n⑤降低直接税比重，完善综合和分类相结合的个人所得税制度","o":["5项","4项","3项","2项"],"a":"D","e":"①正确，《纲要》指出：深化国资国企改革。做强做优做大国有企业和国有资本，增强国有企业核心功能、提升核心竞争力。②正确，《纲要》指出：发展壮大民营经济。持续推进基础设施竞争性领域向民营企业公平开放。③错误，《纲要》指出：完善主要由市场供求关系决定价格机制，加强和改进价格治理。④正确，《纲要》指出：健全地方税体系，推进消费税征收环节后移并稳步下划地方，增加地方自主财力。适当加强中央事权、提高中央财政支出比重，减少委托地方代行的中央财政事权。⑤错误，《纲要》指出：提高直接税比重，完善综合和分类相结合的个人所得税制度，逐步扩大综合征收范围，健全经营所得、资本所得、财产所得税收政策。综上，③⑤说法错误，共2项。故本题选 D。"},{"id":"cg-3q6","n":6,"s":"2026年9月23日，习近平主席抵达华盛顿对美国进行国事访问，这是习近平主席时隔11年再次对美国进行国事访问，也是中美元首半年内实现互访，具有历史性、里程碑意义。下列与之相关说法正确的是：\n①两国元首同意进一步丰富中美关系定位的内涵，共同构建“基于尊重、公平、对等的全面战略合作伙伴关系”\n②乒乓外交叩开了尘封已久的交往大门，中美老一辈政治家以“小球转动大球”的政治智慧，开启了中美关系正常化的伟大进程\n③中美双方应该相向而行，推动形成竞争为主、合作有度、分歧可控、和平可期的稳定关系，走出一条新时代中美两个大国正确相处之道\n④中美两个大国合则两利、斗则俱伤。双方必须守住不冲突、不对抗的底线。“修昔底德陷阱”是可以跨越的","o":["①③","①④","②③","②④"],"a":"D","e":"①错误，2026年9月25日，国家主席习近平和夫人彭丽媛同美国总统特朗普夫妇茶叙，两国元首同意进一步丰富中美关系定位的内涵，共同构建“基于尊重、公平、对等的建设性战略稳定关系”。②正确，2026年9月24日，国家主席习近平和夫人彭丽媛出席特朗普总统夫妇举行的欢迎国宴指出，50多年前，乒乓外交叩开了尘封已久的交往大门，中美老一辈政治家以“小球转动大球”的政治智慧，开启了中美关系正常化的伟大进程。\n③错误，2026年9月23日，习近平主席乘专机抵达华盛顿发表书面讲话指出，中美双方应该相向而行，推动形成合作为主、竞争有度、分歧可控、和平可期的稳定关系，走出一条新时代中美两个大国正确相处之道。④正确，2026年9月24日，习近平主席出席美国总统特朗普在白宫举行的欢迎仪式指出，中美两个大国合则两利、斗则俱伤。双方必须守住不冲突、不对抗的底线。“修昔底德陷阱”是可以跨越的。故本题选 D。"},{"id":"cg-3q7","n":7,"s":"习近平总书记强调，政绩观问题是一个根本性问题，关乎立党为公、执政为民。只有不断以良好政绩推动党和国家事业发展、造福人民，才能践行好党的宗旨，也才能完成好党的历史使命。关于树立和践行正确政绩观，下列表述正确的有几项？\n①中国共产党把为民办事、为民造福作为最重要的政绩，把为老百姓办了多少好事实事作为检验政绩的重要标准\n②树立和践行正确政绩观，起决定性作用的是党性，衡量党性强弱的根本尺子是公、私二字\n③政绩观问题，与权力任性滥用关联度很高，必须把权力关进制度的笼子\n④树立和践行正确政绩观，最终要落到为民造福上","o":["1项","2项","3项","4项"],"a":"D","e":"2026年4月1日出版的第7期《求是》杂志发表习近平总书记的重要文章《树立和践行正确政绩观》。①正确，中国共产党把为民办事、为民造福作为最重要的政绩，把为老百姓办了多少好事实事作为检验政绩的重要标准。党员、干部特别是领导干部要清醒认识到，自己手中的权力、所处的岗位，是党和人民赋予的，是为党和人民做事用的，只能用来为民谋利。②正确，文章指出，树立和践行正确政绩观，起决定性作用的是党性。衡量党性强弱的根本尺子是公、私二字。只有党性坚强、摒弃私心杂念，才能保证政绩观不出偏差。③正确，政绩观问题，与权力任性滥用关联度很高，必须把权力关进制度的笼子。要从这次学习教育查改的问题中发现制度漏洞、短板、弱项，切实把制度规矩补齐立好，把什么能干、什么不能干、为了谁干、应当怎样干搞得清清楚楚，并且配套完善问责办法，让制度硬起来，充分发挥引导激励、规范约束作用。④正确，习近平总书记到山东德州考察，指出“树立和践行正确政绩观，最终要落到为民造福上”“广大党员、干部要强化公仆意识，厚植为民情怀，多为群众做好事、办实事、解难事，实实在在增强老百姓的获得感幸福感安全感”。故本题选 D。"},{"id":"cg-3q8","n":8,"s":"习近平总书记出席2026世界人工智能大会暨人工智能全球治理高级别会议指出，人工智能发展不应该是某个国家的独奏，而应当是全球合作的交响。关于促进全球人工智能向善普惠发展，下列相关表述正确的有几项？\n①坚持开放共赢，鼓励开源开放、合作共享，让人工智能赋能千行百业\n②筑牢安全底线，防范滥用恶用，确保人工智能始终处于人类控制之下\n③共同反对在人工智能领域泛化国家安全概念、把本国安全凌驾于他国安全之上的做法\n④倡导培育以市场为主体、以企业为牵引、以应用为导向、以科研为基础、以人才为根本的创新生态\n⑤人工智能具有鲜明赋能属性，应当培育以大模型为基础、智能体驱动为引领的词元经济新模式","o":["2项","3项","4项","5项"],"a":"C","e":"2026年7月17日上午，国家主席习近平在上海世界会客厅出席2026世界人工智能大会暨人工智能全球治理高级别会议开幕式并发表主旨讲话。①正确，坚持开放共赢，鼓励开源开放、合作共享，让人工智能赋能千行百业。②正确，筑牢安全底线，防范滥用恶用，确保人工智能始终处于人类控制之下。③正确，共同反对在人工智能领域泛化国家安全概念、把本国安全凌驾于他国安全之上的做法。④错误，创新是人工智能发展的核心驱动力。我们倡导培育以企业为主体、以市场为牵引、以应用为导向、以科研为基础、以人才为根本的创新生态。⑤正确，人工智能具有鲜明赋能属性，应当打造智能经济新形态，培育以大模型为基础、智能体驱动为引领的词元经济新模式。故本题选 C。"},{"id":"cg-3q9","n":9,"s":"2026年7月30日，中共中央政治局召开会议，会议分析研究当前经济形势，部署下半年经济工作。下列相关表述不准确的是：","o":["加大逆周期调节力度，加力扩大内需、优化供给，切实保障和改善民生","充分发挥各项存量政策效能，及时谋划出台务实管用的增量政策","有效减缓财政支出和债券资金使用进度，有力推进“两重”建设和“两新”工作","综合运用并适时调整货币政策工具，优化实施财政金融协同促内需政策"],"a":"C","e":"A 项正确，加大逆周期调节力度，加力扩大内需、优化供给，切实保障和改善民生。B 项正确，实施好更加积极的财政政策和适度宽松的货币政策，充分发挥各项存量政策效能，及时谋划出台务实管用的增量政策。C 项不正确，加快财政支出和债券资金使用进度，有力推进 “两重” 建设和 “两新” 工作。D 项正确，综合运用并适时调整货币政策工具，优化实施财政金融协同促内需政策。故本题选 C。"},{"id":"cg-3q10","n":10,"s":"二十届五中全会提出，坚持制度治党、依规治党，为持之以恒推进全面从严治党提供有力制度保障。关于坚持制度治党、依规治党，下列举措不恰当的是：","o":["坚持把党章作为全党的根本行为规范","完善党内法规制度体系，建章立制要针对突出问题，确保便利管用","大力破除潜规则，坚决纠治“搭天线拜码头”“关系不如原则”“条子不如章子”等乱象","强化制度刚性约束，坚持制度面前人人平等、遵守制度没有特殊、执行制度没有例外"],"a":"C","e":"A 正确，必须坚持把党章作为全党的根本行为规范，深化党的建设制度改革，推动依法治国和依规治党有机统一。B 正确，完善党内法规制度体系。建章立制要针对突出问题，确保便利管用。C 错误，大力破除潜规则。坚决纠治“搭天线拜码头”“原则不如关系”“章子不如条子”、不给好处不办事、暗箱操作等乱象，坚决抵制商品交换原则和人身依附关系侵蚀党内生活。D 正确，强化制度刚性约束，坚持制度面前人人平等、遵守制度没有特殊、执行制度没有例外。故本题选 C。"},{"id":"cg-3q11","n":11,"s":"2026年1月16日，《求是》杂志刊发了习近平总书记的重要文章《在中央城市工作会议上的讲话》，文章指出，大力推动城市结构优化、动能转换、品质提升、绿色转型、文脉赓续、治理增效，牢牢守住城市安全底线，走出一条中国特色城市现代化新路子。下列相关说法正确的有几项？\n①转变城市工作重心，更加注重建设投入，打破“缝缝补补”的传统思维和习惯做法，以大建设推动城市高质量更新\n②把京津冀、长江中游、粤港澳大湾区城市群打造成世界级城市群，推动成渝、长三角城市群等成为高质量发展增长极\n③要高质量开展城市更新，推进土地混合开发利用、用途合理转换，有效推动城市低效土地再开发，推动各类产业园区改造提升\n④要坚持人口、产业、城镇、交通一体规划，建设创新型产业社区、商务社区，逐步构建产业、居住、商业等功能分区模式\n⑤城市人口、资源、经济社会活动高度密集，安全风险也相对集中，必须树牢安全发展理念，不断提高安全韧性水平","o":["2项","3项","4项","5项"],"a":"A","e":"2026年1月16日，《求是》杂志刊发了习近平总书记的重要文章《在中央城市工作会议上的讲话》，文章指出，转变城市工作重心，更加注重治理投入。打破“重建设、轻治理”的传统思维和习惯做法，推动城市高质量更新、高水平运营、高效能治理。①说法不准确。优化现代化城市体系，首先要着眼于提高城市对人口和经济社会发展的综合承载能力，发展组团式、网络化的现代化城市群和都市圈。把京津冀、长三角、粤港澳大湾区城市群打造成世界级城市群，推动成渝、长江中游城市群等成为高质量发展增长极，增强中西部和东北的城市群、都市圈对区域协调发展的支撑作用。城市群内，要加强产业链协作，构建跨行政区合作发展新机制；城市群之间，要优化产业分工和空间联系。对于都市圈，有条件的地方可以推进同城化发展，促进通勤便捷高效、产业梯次配套、公共服务便利共享。②说法不准确。要高质量开展城市更新，推进土地混合开发利用、用途合理转换，有效推动城市低效土地再开发，推动各类产业园区改造提升。要创新财政金融政策工具，吸引和规范社会资金参与，稳慎推进公用事业价格改革，建立可持续的城市建设运营投融资体系。③说法正确。宜居是践行人民城市理念的基本要求。要坚持人口、产业、城镇、交通一体规划，建设创新型产业社区、商务社区，逐步破除传统的产业、居住、商业等功能分隔模式。④说法不准确。城市人口、资源、经济社会活动高度密集，安全风险也相对集中，必须树牢安全发展理念，不断提高安全韧性水平。⑤说法正确。故本题选 A。"},{"id":"cg-3q12","n":12,"s":"科技创新和产业创新，是发展新质生产力的基本路径，关于推动科技创新和产业创新深度融合的意见，以下说法正确的是：","o":["以发展新质生产力、建设现代化产业体系为目标，以构建企业主导、各主体协同的产学研融通创新体系为重点","健全企业牵头项目的管理规定，完善“揭榜挂帅”“业主制”等组织方式和“里程碑”管理、一次性全额拨付等资助方式","健全研用一体的成果转化应用机制，产业应用目标明确的国家科技计划项目，原则上由国家实验室牵头实施并主导成果转化","政府出资的创业投资基金和国有资本创业投资基金强化投早、投小、投长期、投硬科技，健全长周期考核、统一标准的监管和退出机制"],"a":"A","e":"2026年10月，《中共中央办公厅 国务院办公厅关于推动科技创新和产业创新深度融合的意见》对外发布，《意见》指出，深入实施创新驱动发展战略，以发展新质生产力、建设现代化产业体系为目标，以构建企业主导、各主体协同的产学研融通创新体系为重点，推动全链条贯通、全领域覆盖、全要素融通、全方位保障，形成科技创新和产业创新互融共促新格局。A 项说法正确。强化国家科技计划项目的产业应用导向，常态化征集企业需求，在指南编制、立项评审、项目验收中，合理增加来自企业和创业投资机构的专家数量，推动科技界、产业界、用户等多方参与。健全企业牵头项目的管理规定，完善“揭榜挂帅”“业主制”等组织方式和“里程碑”管理、分阶段拨款等资助方式。健全“应用考核技术、市场考核产品”的项目验收机制，加强研发目标和产业化目标一体考核。B 项说法不准确。健全研用一体的成果转化应用机制，产业应用目标明确的国家科技计划项目，原则上由企业牵头实施并主导成果转化。支持高校、科研院所设立技术转移机构或岗位，强化知识产权、创业孵化、科技金融等专业化服务，通过技术转让、许可、作价投资等方式加快成果应用。深化职务科技成果赋权和资产单列管理改革，鼓励科技成果完成人全过程参与成果转化，引导高校、科研院所按照先使用后付费方式把科技成果许可给中小微企业使用。健全全国一体化技术市场，促进专业化市场化技术转移机构发展，加强技术经理人队伍建设。C 项说法不准确。构建与科技企业全生命周期融资需求相适应的科技金融体系。发挥国家创业投资引导基金作用。政府出资的创业投资基金和国有资本创业投资基金强化投早、投小、投长期、投硬科技，健全长周期考核、差异化监管和退出机制。D 项说法不准确。故本题选A。"},{"id":"cg-3q13","n":13,"s":"2026年6月，国务院印发《实施就业优先战略“十五五”规划》，《规划》指出，深入实施就业优先战略、促进高质量充分就业，以下相关说法正确的是：","o":["以深化就业体制机制改革为动力，以破解结构性就业矛盾为底线，健全就业促进机制","发挥民营企业就业引领作用，深入开展扩岗增招专项行动，稳定民营企业招聘规模","建设国家人才供需对接大数据平台，推动高等教育人才培养与经济社会发展需要相适配","十五五时期，服务业吸纳就业作用进一步发挥，城镇就业占全部就业比重保持稳定"],"a":"C","e":"2026年6月，国务院印发《实施就业优先战略“十五五”规划》，《规划》指出，围绕就业领域人力资源供需不匹配的主要矛盾，坚持投资于物和投资于人紧密结合，以推动高质量发展为基础，以实施就业优先战略为引领，以强化就业优先政策为抓手，以破解结构性就业矛盾为着力点，以深化就业体制机制改革为动力，以不发生规模性失业风险为底线，健全就业促进机制，构建就业友好型发展方式，加强人力资源开发利用，强化择业和用人观念引导，持续促进就业质的有效提升和量的合理增长 A项说法不准确。发挥国有企业就业引领作用，深入开展扩岗增招专项行动，稳定国有企业招聘规模。发挥民营企业和中小企业对就业的重要作用，切实降低企业负担，促进民营经济高质量发展，持续优化各类经营主体公平竞争发展环境。B 项说法不准确。建设国家人才供需对接大数据平台，推动高等教育人才培养与经济社会发展需要相适配。深入实施高等教育学科专业设置调整优化行动，加强战略性新兴产业和未来产业所需人才培养。推动高校学科专业设置与区域发展相匹配，打造特色优势学科专业集群。C 项说法正确。“十五五”时期，就业保持总体稳定，高质量充分就业取得新进展。就业机会更加充分。城镇就业稳定增长，失业水平有效控制，重点群体就业保持稳定，确保零就业家庭至少一人实现就业。就业环境更加公平。统一规范的人力资源市场体系进一步健全，促进劳动力、人才流动的体制机制更加完善，影响平等就业的不合理限制和就业歧视得到有效治理。就业结构更加优化。服务业吸纳就业作用进一步发挥，城镇就业占全部就业比重稳步提高，区域就业结构更趋合理，灵活就业、新就业形态健康发展。D 项说法不准确。故本题选 C。"},{"id":"cg-3q14","n":14,"s":"习近平总书记在出席十四届全国人大四次会议解放军和武警部队代表团全体会议时强调，凝心聚力推动国防和军队现代化行稳致远。下列相关说法不准确的是：","o":["必须坚持好、运用好、发展好政治建军这个重要法宝，毫不动摇坚持和加强党对军队绝对领导，充分发挥政治建军特有优势","就要立起从严监管硬规矩，加强重大项目监管，强化军地融合监督，确保在不影响建设前提下从严推进监管","把基层作为赓续优良传统的沃土，重视抓好管根本、利长远、增后劲的工作，把部队建设和战斗力基础打得更加牢靠","坚持不懈用党的创新理论铸魂育人，打牢官兵听党话、跟党走的思想根基，确保现代化武器装备掌握在革命化人才队伍手中"],"a":"B","e":"2026年3月7日，习近平总书记出席十四届全国人大四次会议解放军和武警部队代表团全体会议并发表重要讲话。A 项正确，讲话指出：“十五五”时期要如期实现建军一百年奋斗目标、高质量推进国防和军队现代化，必须坚持好、运用好、发展好政治建军这个重要法宝，毫不动摇坚持和加强党对军队绝对领导，充分发挥政治建军特有优势，凝心聚力推动国防和军队现代化行稳致远。B 项错误，讲话指出：“十五五”一开局就要立起从严监管硬规矩，紧盯资金流向、权力运行和质量管控等关键环节，加强重大项目监管，强化军地融合监督，确保在监管前提下搞建设。C 项正确，讲话指出：要把基层作为赓续优良传统的沃土，积极探索新形势下基层建设规律和有益做法，重视抓好管根本、利长远、增后劲的工作，把部队建设和战斗力基础打得更加牢靠。D 项正确，讲话指出：要加强革命化专业化人才队伍建设，坚持不懈用党的创新理论铸魂育人，打牢官兵听党话、跟党走的思想根基，确保现代化武器装备掌握在革命化人才队伍手中。本题为选非题，故本题选 B。"},{"id":"cg-3q15","n":15,"s":"当前我国新兴领域迅速发展，尤其是以互联网平台为支撑的新业态大量涌现，聚集了规模庞大的新就业群体。关于加强新就业群体服务管理，下列说法错误的是：","o":["探索采取流出地流入地相配合、线下线上相结合的方式，加强和改进新就业群体中流动党员教育、管理、监督和服务","推行由常住地提供基本公共服务，结合实际逐步推动相关公共服务随人走","推广使用适应行业特点、紧贴新就业群体需求的劳动合同、书面协议参考文本，完全根据合同、协议确定权利义务","健全劳动争议协商调解工作机制，加强一站式调解，完善新就业群体劳动争议裁判规则"],"a":"C","e":"2026年4月，首个专门关于新就业群体服务管理的中央文件《中共中央办公厅 国务院办公厅关于加强新就业群体服务管理的意见》指出，A项正确，针对不同类型新就业群体的工作方式、活动范围，发挥属地、企业、行业优势，创新党组织设置和活动方式，持续扩大党的组织覆盖和党的工作覆盖。探索采取流出地流入地相配合、线下线上相结合的方式，加强和改进新就业群体中流动党员教育、管理、监督和服务。B 项正确，推行由常住地提供基本公共服务，结合实际逐步推动相关公共服务随人走。C 项不正确，推动互联网平台企业、快递企业等完善用工管理制度，推广使用适应行业特点、紧贴新就业群体需求的劳动合同、书面协议参考文本，根据用工事实等依法合理确定权利义务。D 项正确，健全劳动争议协商调解工作机制，加强一站式调解，完善新就业群体劳动争议裁判规则。故本题选 C。"},{"id":"cg-3q16","n":16,"s":"2026年10月1日《求是》杂志发表了习近平总书记重要文章《加强普惠性、基础性、兜底性民生建设》，文章指出，我们的目标很宏伟，也很朴素，归根到底就是让老百姓过上更好的日子。下列相关说法正确的是：","o":["一些结构性改革会带来部分职工下岗失业、收入降低等阵痛，要更好发挥第三次分配的社会稳定器作用，把重点放在提高生活品质上","既要避免像一些国家那样盲目进行“福利赶超”落入“中等收入陷阱”，又要避免像一些国家那样实行“泛福利化”导致社会活力不足","民生无小事，政府要什么都包，重点是加强基础性、普惠性、兜底性民生保障建设","要把发展经济和改善民生有机统一起来，保障和改善民生要以发展经济为根本目的"],"a":"B","e":"2026年10月1日《求是》杂志发表了习近平总书记重要文章《加强普惠性、基础性、兜底性民生建设》，文章指出，一些结构性改革会带来部分职工下岗失业、收入降低等阵痛，要更好发挥社会保障的社会稳定器作用，把重点放在兜底上，保障群众基本生活，保障基本公共服务。A 项说法不准确。要拓展国际视野，关注国外社会保障发展情况，汲取经验教训，既避免像一些国家那样盲目进行“福利赶超”落入“中等收入陷阱”，又避免像一些国家那样实行“泛福利化”导致社会活力不足。B 项说法正确。要统筹需要和可能，把保障和改善民生建立在经济发展和财力可持续的基础之上，不要好高骛远，吊高胃口，作兑现不了的承诺。政府不能什么都包，重点是加强基础性、普惠性、兜底性民生保障建设。C 项说法不正确。发展经济的根本目的是更好保障和改善民生。D项说法不正确。故本题选 B。"},{"id":"cg-3q17","n":17,"s":"2026年10月23日，国务院召开常务会议，研究统筹人口与经济社会发展有关工作，会议指出，人口是经济社会发展的基础条件。关于人口与经济社会发展，以下说法不准确的是：","o":["要持续积累和释放人口综合红利，以经济社会高质量发展更好支撑人口高质量发展","要广泛开展技能培训，强化教育、培训与产业发展协同联动，促进高质量充分就业","要加强区域人口发展分类指导，推动公共服务资源与常住人口变化动态适配","要优化面向家庭的财税、社保、住房等支持举措，努力稳定新出生人口规模"],"a":"A","e":"2026年10月23日，国务院召开常务会议，研究统筹人口与经济社会发展有关工作，会议指出，人口是经济社会发展的基础条件，要更好统筹人口与经济社会、资源环境的关系，进一步完善相关政策，持续积累和释放人口综合红利，以人口高质量发展更好支撑经济社会高质量发展。要更加突出人的全面发展，提高人口科学文化、职业技能、身心健康等水平，加快完善全民终身学习机制，广泛开展技能培训，强化教育、培训与产业发展协同联动，促进高质量充分就业。要加强区域人口发展分类指导，引导城乡人口有序流动，稳步推进基本公共服务均等化，根据人口分布情况优化基础设施布局，推动公共服务资源与常住人口变化动态适配。要加快建设生育友好型社会，持续完善婚嫁、生育、养育、教育等政策，优化面向家庭的财税、社保、住房等支持举措，努力稳定新出生人口规模。故本题选A。"},{"id":"cg-3q18","n":18,"s":"“十五五”时期是基本实现社会主义现代化夯实基础、全面发力的关键时期，也是美丽中国建设承前启后、扩面提质，实现生态环境根本好转的关键阶段。关于建设美丽中国，下列说法正确的是：","o":["加快温室气体自愿减排交易市场建设，实现全国碳排放权交易市场全行业全覆盖","坚持减缓与适应并重，全面控制温室气体排放，积极应对气候变化不利影响和风险","深入推进生态环境全域统一标准管控，建立健全以国家公园为主体的自然保护地体系","以健全生态文明制度体系为牵引，以碳达峰碳中和为保障，协同推进降碳、减污、扩绿、增长"],"a":"B","e":"2026年3月12日，十四届全国人大四次会议表决通过《中华人民共和国国民经济和社会发展第十五个五年规划纲要》的决议。A 项错误，《纲要》指出：扩大全国碳排放权交易市场覆盖范围，加快温室气体自愿减排交易市场建设。B 项正确，《纲要》指出：坚持减缓与适应并重，全面控制温室气体排放，积极应对气候变化不利影响和风险。C 项错误，《纲要》指出：深入推进生态环境分区管控，加强同国土空间规划衔接，协同优化产业布局。实施自然保护地整合优化，落实分级管理和分区管控，建立健全以国家公园为主体的自然保护地体系。D 项错误，《纲要》指出：牢固树立和践行绿水青山就是金山银山的理念，以碳达峰碳中和为牵引，以健全生态文明制度体系为保障，协同推进降碳、减污、扩绿、增长，改善生态环境质量，筑牢生态安全屏障，增强绿色发展动能。故本题选 B。"},{"id":"cg-3q19","n":19,"s":"习近平总书记指出，一体推进教育科技人才事业发展，构筑人才竞争优势。科技创新靠人才，人才培养靠教育，教育、科技、人才内在一致、相互支撑。要深化教育科技人才体制机制一体改革，完善科教协同育人机制，加快培养造就一支规模宏大、结构合理、素质优良的创新型人才队伍。这蕴含的哲理是：","o":["集中力量解决主要矛盾","分清事物的主流与支流","用系统优化的方法解决问题","注意把握规律的客观性"],"a":"C","e":"题干强调教育、科技、人才内在一致、相互支撑，一体推进、体制机制一体改革，把三者看作有机整体统筹安排，体现系统优化的方法，着眼于事物的整体性。C 项符合题意。ABD 表述正确，但题干未涉及。故本题选C。"},{"id":"cg-3q20","n":20,"s":"近年来，人工智能技术不断取得突破，企业“智”造、“机器人换人”不断让机器人在生产车间“唱主角”。下列相关理解正确的是：","o":["会导致资本技术构成提高","说明商品价值可以由机器创造","可以提高单位商品的价值量","会提高商品的使用价值"],"a":"A","e":"资本技术构成是指资本在物质形态上由生产资料的数量同使用这些生产资料的劳动力数量所构成的比例。为了进行剩余价值的生产，资本家必须购买一定数量的生产资料和相应数量的劳动力，这两者之间存在着一定的比例，这个比例取决于生产技术的发展水平，技术水平愈高，每个工人所能运用的生产资料数量愈多，反之，运用的生产资料数量愈少。因此，“机器人换人”会导致资本技术构成提高，A 项表述正确。商品价值只能由劳动者创造，B 项错误。企业通过技术创新可以提高个别劳动生产率，但单位商品的价值量不会提高，C 项表述错误。智能技术的运用与商品的使用价值没有直接的对应关系，D 项表述不正确。故本题选 A。"}]},{"id":"cg-4","cat":"zz","title":"超格考前五套卷 · 第四套","short":"超格第四套","sub":"20 题","questions":[{"id":"cg-4q1","n":1,"s":"党的二十届五中全会审议通过的《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》，将“增强共产党人的党性”摆在七项战略任务和重大举措的首位，提出推动党员、干部把加强党性修养作为终身课题。下列与之相关说法正确的有几项？\n①坚持把对党忠诚摆在党性修养的突出位置\n②把学习、领悟、运用中华优秀传统文化作为加强党性修养的根本途径\n③坚持集中教育和经常教育相结合，着力解决党性方面存在的突出问题\n④教育引导党员、干部坚定对马克思主义的信仰、对共产主义的信念、对中国特色社会主义的信心","o":["1项","2项","3项","4项"],"a":"C","e":"①正确，坚持把对党忠诚摆在党性修养的突出位置。②错误，加强马克思主义学习型政党建设，把学习、领悟、运用党的创新理论作为加强党性修养的根本途径，推动全党用习近平新时代中国特色社会主义思想统一思想、统一意志、统一行动。用党的优良传统和中华优秀传统文化涵养党性。③正确，坚持集中教育和经常教育相结合，着力解决党性方面存在的突出问题。④正确，教育引导党员、干部坚定对马克思主义的信仰、对共产主义的信念、对中国特色社会主义的信心，做到虔诚而执着、至信而深厚。故本题选 C。"},{"id":"cg-4q2","n":2,"s":"习近平总书记高度重视系统思维，多次突出强调要树立系统思维，运用系统思维分析解决问题。下列属于系统思维的论述中，正确的有几项？\n①把国家安全贯穿到党和国家工作各方面全过程，同经济社会发展一起谋划、一起部署\n②从生态系统整体性和流域系统性出发，追根溯源、系统治疗，防止头痛医头、脚痛医脚\n③以实现中华民族伟大复兴为出发点和落脚点，统筹谋划和推进新时代党的民族工作\n④把人口高质量发展同人民高品质生活紧密结合起来，促进人的全面发展和全体人民共同富裕","o":["1项","2项","3项","4项"],"a":"D","e":"①正确，做好新时代国家安全工作，要坚持总体国家安全观，抓住和用好我国发展的重要战略机遇期，把国家安全贯穿到党和国家工作各方面全过程，同经济社会发展一起谋划、一起部署，坚持系统思维，构建大安全格局，促进国际安全和世界和平，为建设社会主义现代化国家提供坚强保障。②正确，要从生态系统整体性和流域系统性出发，追根溯源、系统治疗，防止头痛医头、脚痛医脚。要找出问题根源，从源头上系统开展生态环境修复和保护。③正确，必须从中华民族伟大复兴战略高度把握新时代党的民族工作的历史方位，以实现中华民族伟大复兴为出发点和落脚点，统筹谋划和推进新时代党的民族工作。④正确，要以系统观念统筹谋划人口问题，以改革创新推动人口高质量发展，把人口高质量发展同人民高品质生活紧密结合起来，促进人的全面发展和全体人民共同富裕。故本题选 D。"},{"id":"cg-4q3","n":3,"s":"2026年6月1日，《求是》杂志发表习近平总书记重要文章《前瞻布局和发展未来产业》，文章指出，未来产业具有前瞻性、战略性、颠覆性等特点，需要科学谋划、全局统筹。下列相关说法正确的是：","o":["新一代信息技术、新能源、新材料、智能网联新能源汽车、机器人、生物医药、高端装备、航空航天等领域是“十五五”时期我国未来产业发展的主攻方向","综合考虑国家战略需求、技术成熟程度、要素支撑条件等因素，把需要和可能统一起来，分门别类制定实施规划，做到先易后难、由近及远，积极稳步推进","要引导各地牢固树立和践行正确政绩观，坚持全国一盘棋，步调一致、同步发展，防止盲目“跟风”上项目、乱“烧钱”","未来产业基础薄、潜力大，要强化单兵突进，科研资金、科研人才要向未来产业倾斜，推动未来产业取得长足进步"],"a":"B","e":"2026年6月1日，《求是》杂志发表习近平总书记重要文章《前瞻布局和发展未来产业》，文章指出，未来产业具有前瞻性、战略性、颠覆性等特点，需要科学谋划、全局统筹。要把准发展方向。方向明，才能路子正、步履坚。党的二十届四中全会提出，要推动量子科技、生物制造、氢能和核聚变能、脑机接口、具身智能、第六代移动通信等成为新的经济增长点。这些领域是“十五五”时期我国未来产业发展的主攻方向，要聚焦发力、精准施策，确保取得明显进展。要科学论证技术路线。重点是提升前沿技术战略预判能力，加强多元技术路线探索并及时动态调整。要把握发展节奏。综合考虑国家战略需求、技术成熟程度、要素支撑条件等因素，把需要和可能统一起来，分门别类制定实施规划，做到先易后难、由近及远，积极稳步推进。特别是要引导各地牢固树立和践行正确政绩观，坚持全国一盘棋，因地制宜、错位发展，防止盲目“跟风”上项目、乱“烧钱”。要强化产业协同。未来产业与传统产业、新兴产业相辅相成、相互促进，传统产业底子雄厚，未来产业、新兴产业发展就会有后劲。要坚持联动发展，防止单兵突进，推动未来产业同新兴产业、传统产业相得益彰。故本题选B。"},{"id":"cg-4q4","n":4,"s":"防灾减灾救灾事关人民生命财产安全，事关社会和谐稳定，是衡量执政党领导力、检验政府执行力、评判国家动员力、体现民族凝聚力的一个重要方面。关于提高防灾减灾救灾能力，下列表述正确的有几项？\n①做好防灾减灾救灾工作，必须坚持党的全面领导，坚持人民至上、生命至上，坚持尊重自然规律，坚持减灾救灾为主，坚持改革创新，坚持系统观念，坚持社会共治\n②合理提高重要城市和灾害多发地区关键基础设施设防标准，推进城市平急两用公共基础设施建设，加紧补齐北方地区防洪排涝抗灾基础设施短板\n③统筹做好综合救援、过渡安置和恢复重建工作，防止自然灾害风险向经济安全、能源资源安全、粮食安全、社会安全等领域传导和扩散\n④要鼓励和支持社会应急力量建设，发挥群团、志愿服务等组织作用，完善群测群防群治体系","o":["1项","2项","3项","4项"],"a":"C","e":"2026年第16期《求是》杂志发表习近平总书记署名文章《提高防灾减灾救灾能力》。①错误，文章指出：实践中我们深刻认识到，做好防灾减灾救灾工作，必须坚持党的全面领导，坚持人民至上、生命至上，坚持尊重自然规律，坚持预防为主，坚持改革创新，坚持系统观念，坚持社会共治。②正确，文章指出：要强化工程治理，针对关键领域和薄弱环节深入实施自然灾害防治重点工程，合理提高重要城市和灾害多发地区关键基础设施设防标准，推进城市平急两用公共基础设施建设，加紧补齐北方地区防洪排涝抗灾基础设施短板。③正确，文章指出：大灾巨灾影响面广、关联性强、破坏力大，要统筹做好综合救援、过渡安置和恢复重建工作，防止自然灾害风险向经济安全、能源资源安全、粮食安全、社会安全等领域传导和扩散。④正确，文章指出：基层是抵御自然灾害的第一线，抓基层、强基础的工作始终不能放松。要推动资源和力量下沉，完善基层应急救援力量体系，依规配齐配强应急救援力量，强化应急场所建设和物资装备保障。要鼓励和支持社会应急力量建设，发挥群团、志愿服务等组织作用，完善群测群防群治体系。综上，②③④表述正确，共3项。故本题选C。"},{"id":"cg-4q5","n":5,"s":"党的十八大以来，习近平总书记始终把海洋事业摆在党和国家事业发展全局的重要位置，强调发展海洋经济、建设海洋强国，提高海洋开发能力，让海洋经济成为新的增长点。关于推动海洋经济高质量发展，下列相关表述不准确的是：","o":["加强顶层设计和政策支持，鼓励引导社会资本积极参与发展海洋经济","加强海洋环境风险源头防范，推进蓝色海湾、美丽岸滩、和美海岛建设行动","加强全球海洋科研调查、防灾减灾、蓝色经济合作，推进“一带一路”国际港口联盟建设","加强海洋生态环境保护，制定统一化用海标准规范，积极推进海域分层立体利用"],"a":"D","e":"2026年第6期《求是》杂志发表习近平总书记署名文章《推动海洋经济高质量发展》。A 项正确，文章指出：加强顶层设计和政策支持。鼓励引导社会资本积极参与发展海洋经济。B 项正确，文章指出：加强海洋环境风险源头防范，接续实施重点海域综合治理，推进蓝色海湾、美丽岸滩、和美海岛建设行动。C 项正确，文章指出：加强全球海洋科研调查、防灾减灾、蓝色经济合作，推进 “一带一路” 国际港口联盟建设，完善同21世纪海上丝绸之路沿线国家的合作机制。D 项错误，文章指出：加强海洋生态环境保护。制定差异化用海标准规范，积极推进海域分层立体利用。探索开展海洋碳汇核算。本题为选非题，故本题选D。"},{"id":"cg-4q6","n":6,"s":"习近平总书记强调，金融是国民经济的血脉，是国家核心竞争力的重要组成部分，要加快建设金融强国。关于建设金融强国，下列说法正确的是：","o":["我国金融模式以资本自我增殖为终极目的，通过资本的自我循环推动高质量发展","加快构建结构合理的金融市场体系，发展多层次股权市场，深化常态化退市机制","我国金融机构门类齐全，要引导金融机构同质化发展，增强发展的内生动力和活力","中国特色金融文化明确金融具有功能性和盈利性双重属性，功能要服从盈利追求"],"a":"B","e":"2026年第3期《求是》文章《走好中国特色金融发展之路，建设金融强国》指出，A 错误，我们党领导的金融事业，归根到底要造福人民，与一些国家金融为资本服务、为少数有钱人服务的本质截然不同。服务实体经济是金融的天职。如果热衷于自我循环、自我膨胀，金融就会变成无源之水、无本之木，迟早酿成危机。B 正确，加快构建结构合理的金融市场体系。发展多层次股权市场，提高上市公司质量，深化常态化退市机制。C 错误，我国金融机构门类齐全，关键是要错位发展、优势互补，在服务实体经济上各司其职、各展所长。D 错误，要以义取利，不唯利是图。中华优秀传统文化强调 “先义而后利者荣，先利而后义者辱”，见利忘义一向为君子所不齿。金融具有功能性和盈利性双重属性，盈利要服从功能发挥。故本题选 B。"},{"id":"cg-4q7","n":7,"s":"2026年9月1日，习近平主席在“上海合作组织+”会议积极倡导平等有序的世界多极化，推动实现更加公正合理的全球治理，携手推动构建人类命运共同体。关于平等有序的世界多极化的核心要义，下列理解正确的是：\n①主权平等、相互尊重是根本原则。世界多极化、发展道路自主化、国际关系民主化是人间正道\n②均衡有序、遵守法治是必然要求。要摒弃双重标准、例外主义、干涉霸凌、丛林法则，推进国际关系法治化\n③多边主义、对话协商是关键路径。推行大国共治、几方共治与集团政治，国际规则由各国共同制定\n④互利共赢、普惠包容是发展方向。保护主义、脱钩断链没有未来","o":["①②③","①②④","①③④","②③④"],"a":"B","e":"①正确，主权平等、相互尊重是根本原则。世界历史由各国人民共同书写，世界多极化、发展道路自主化、国际关系民主化是人间正道。②正确，均衡有序、遵守法治是必然要求。联合国宪章宗旨和原则确立了国际关系基本准则，是战后国际秩序的基石。我们要弘扬全人类共同价值，摒弃双重标准、例外主义、干涉霸凌、丛林法则，推进国际关系法治化。③错误，多边主义、对话协商是关键路径。少数国家主导国际事务是历史不公，一国独霸、几方共治、集团政治不是真正的多边主义。世界上的事应该由各国商量着办，国际规则要由各国共同制定。④正确，互利共赢、普惠包容是发展方向。保护主义、脱钩断链没有未来。我们要聚焦发展议题，坚持开放合作，弥合数字和智能鸿沟，让技术革命和发展成果惠及各国人民。故本题选 B。"},{"id":"cg-4q8","n":8,"s":"二十届五中全会提出，正风肃纪是全面从严治党的有力举措。必须坚持党性党风党纪一起抓、正风肃纪反腐相贯通，深化运用从抓作风入手推进全面从严治党经验。关于正风肃纪，下列说法错误的是：","o":["未经组织批准，党政领导干部不得公开出版个人著作","驰而不息正风肃纪，防止和克服命令主义、“尾巴主义”，持续强化作风问题“小节论”“特殊论”","坚持抓早抓小、防微杜渐，对苗头性、倾向性问题及时提醒纠正，防止小毛病演化成大问题","落实领导干部宣传党的路线方针政策下基层、调查研究下基层、信访接待下基层、现场办公下基层制度"],"a":"B","e":"A 正确，未经组织批准，党政领导干部不得公开出版个人著作。B 错误，驰而不息正风肃纪。在服务群众中教育引导群众、带领群众前进，防止和克服命令主义、“尾巴主义”。把作风建设融入日常、抓在经常，防止消极应付和疲劳厌战，纠正作风问题“小节论”“特殊论”。C 正确，强化从严执纪。坚持抓早抓小、防微杜渐，对苗头性、倾向性问题及时提醒纠正，防止小毛病演化成大问题。D 正确，落实领导干部宣传党的路线方针政策下基层、调查研究下基层、信访接待下基层、现场办公下基层制度，落实党员、干部直接联系服务群众制度。故本题选 B。"},{"id":"cg-4q9","n":9,"s":"习近平总书记强调，要以新时代中国特色社会主义思想为指导，深入贯彻新时代强军思想，开展思想整风，深化政治整训，加强我军干部队伍革命性锻造，始终保持人民军队纯洁光荣，以崭新政治面貌迎接建军一百周年。下列相关表述不准确的是：","o":["要认真学习党的创新理论，掌握贯穿其中的马克思主义立场观点方法，以政治上的坚定保证理论上的清醒","军队领导干部特别是高级干部要带头严肃党内政治生活，当好讲真话的表率，涵养能容人的雅量，营造说实话、建诤言、敢斗争的浓厚氛围","我们党是始终代表最广大人民根本利益的马克思主义政党，没有任何自己的特殊利益，一切谋私贪腐的思想和行为都同党的性质宗旨格格不入","要懂法纪、明规矩、知敬畏，做到法规制度面前人人平等，遵守法规制度没有特殊，执行法规制度没有例外"],"a":"A","e":"A 项错误、B 项正确，习近平在全军高级干部培训班开班式上发表重要讲话，讲话指出，要认真学习党的创新理论，掌握贯穿其中的马克思主义立场观点方法，以理论上的清醒保证政治上的坚定。军队领导干部特别是高级干部要带头严肃党内政治生活，当好讲真话的表率，涵养能容人的雅量，营造说实话、建诤言、敢斗争的浓厚氛围。C 项正确，习近平强调，我们党是始终代表最广大人民根本利益的马克思主义政党，没有任何自己的特殊利益，一切谋私贪腐的思想和行为都同党的性质宗旨格格不入。D 项正确，高级干部要带头恢复和弘扬我党我军优良传统，放下官架子、回归革命军人本色，让新风正气在部队更加充盈。要懂法纪、明规矩、知敬畏，做到法规制度面前人人平等，遵守法规制度没有特殊，执行法规制度没有例外。故本题选 A。"},{"id":"cg-4q10","n":10,"s":"习近平总书记指出，科技创新是人类文明进步的不竭动力，新一轮科技革命和产业变革深刻改变人类生产生活方式和世界发展格局，科技实力和创新能力越来越成为国家的核心竞争力。关于科技强国建设，下列说法不正确的是：","o":["推动科技创新和产业创新深度融合是以高水平科技自立自强引领发展新质生产力的关键","科技创新要突出应用导向，支持高校、科研院所对接企业开展科研攻关和人才培养，以高质量科技供给赋能产业创新","项目评审、机构评估、人才评价都要强化创新能力、质量、实效、贡献导向，要强化评价指标的一致性，不能各行其是","要构建同科技创新相适应的科技金融体制，畅通企业投融资渠道，引导金融资本投早、投小、投长期、投硬科技"],"a":"C","e":"2026年7月8日上午，国家科学技术奖励大会、中国科学院第二十二次院士大会和中国工程院第十八次院士大会、中国科学技术协会第十一次全国代表大会在北京人民大会堂隆重召开。中共中央总书记、国家主席、中央军委主席习近平出席大会并发表重要讲话。A 项、B 项正确，推动科技创新和产业创新深度融合，是以高水平科技自立自强引领发展新质生产力的关键。科技创新要突出应用导向，支持高校、科研院所对接企业开展科研攻关和人才培养，以高质量科技供给赋能产业创新。产业创新要提出科学问题，强化企业创新主体地位，支持企业与高校、科研院所共建平台、共克难题，以高端化、绿色化、智能化产业需求牵引科技创新。C 项错误，项目评审、机构评估、人才评价都要强化创新能力、质量、实效、贡献导向，体现不同类别的差异性，不能评价指标权重模糊甚至本末倒置，不能搞“一刀切”“一锅煮”。D 项正确，科技成果转化率不高，要构建同科技创新相适应的科技金融体制，推动创业投资市场健康稳定发展，畅通企业投融资渠道，引导金融资本投早、投小、投长期、投硬科技。故本题选 C。"},{"id":"cg-4q11","n":11,"s":"2026年1月20日，省部级主要领导干部学习贯彻党的二十届四中全会精神专题研讨班在中央党校（国家行政学院）开班。习近平总书记在开班式上发表重要讲话强调，要把学习贯彻党的二十届四中全会精神不断引向深入，更好统一思想、凝心聚力，在党中央坚强领导下扎实做好各项工作。下列相关说法正确的是：","o":["要胸怀全局、登高望远，在战术上保持定力，在战略上精心运筹，不断增强我国发展的确定性和可持续性","建设现代化产业体系、实现产业体系整体跃升，是“十五五”时期的重要战略任务，要持续提升制造业比重，大力发展先进制造业","要坚持以国内大循环为主体，正确处理消费和投资、需求和供给的关系，促进投资于物转向投资于人","要把改善民生作为促进社会发展的重点，在发展经济的同时稳步提高人民生活品质"],"a":"D","e":"2026年1月20日，省部级主要领导干部学习贯彻党的二十届四中全会精神专题研讨班在中央党校（国家行政学院）开班。习近平总书记指出，要胸怀全局、登高望远，在战略上保持定力，在战术上精心运筹，不断增强我国发展的确定性和可持续性。A 项说法不正确。建设现代化产业体系、实现产业体系整体跃升，是“十五五”时期的重要战略任务。各地区各行业要找准定位，坚持智能化、绿色化、融合化方向，发挥比较优势，形成上下游产业相互衔接、各展其长、同向发力的生动局面。要保持制造业合理比重，大力发展先进制造业。B 项说法不正确。要坚持以国内大循环为主体，正确处理消费和投资、需求和供给的关系，坚持惠民生和促消费、投资于物和投资于人紧密结合，努力提高国民经济循环质量和效率，让内需成为经济发展的主动力。C 项说法不正确。经济发展和社会发展相辅相成，必须协调并进。要把改善民生作为促进社会发展的重点，在发展经济的同时稳步提高人民生活品质。D 项说法正确。故本题选 D。"},{"id":"cg-4q12","n":12,"s":"习近平总书记在庆祝中国共产党成立105周年大会上的讲话指出，我们党胸怀共产主义远大理想、立志于中华民族千秋伟业，坚定地把历史和人民赋予的重任扛在肩上，坚持长远目标和阶段目标相统一，适应社会主要矛盾变化确立中心任务，制定和实施正确的路线方针政策，确保牢牢掌握事业发展的领导权和主动权。这一论述体现了我们党哪一优秀特质？","o":["矢志追求真理，始终把准前进方向","勇担历史使命，始终掌握战略主动","深深植根人民，始终拥有坚实根基","顺应发展潮流，始终走在时代前列"],"a":"B","e":"习近平总书记在庆祝中国共产党成立105周年大会上的讲话指出，勇担历史使命，始终掌握战略主动。我们党胸怀共产主义远大理想、立志于中华民族千秋伟业，坚定地把历史和人民赋予的重任扛在肩上，坚持长远目标和阶段目标相统一，适应社会主要矛盾变化确立中心任务，制定和实施正确的路线方针政策，确保牢牢掌握事业发展的领导权和主动权。故本题选 B。"},{"id":"cg-4q13","n":13,"s":"2026年5月，国务院印发《城市更新“十五五”规划》，《规划》指出，城市是现代化建设的重要载体、人民幸福生活的重要空间。关于推动城市更新，以下说法不正确的是：","o":["要坚持规划引领，坚持统筹发展和安全，坚持保护第一、应保尽保、以用促保，因地制宜、分类指导","到2030年，创新、宜居、美丽、韧性、文明、智慧的现代化人民城市基本建成","推进超大特大城市治理现代化，以城市群、都市圈为依托构建大中小城市协调发展格局","实施房屋品质提升工程，兼顾增量建设与存量更新，全链条提升住房标准、设计、材料、建造、运维水平"],"a":"B","e":"2026年5月，国务院印发《城市更新“十五五”规划》，《规划》指出，坚持以人民为中心，坚持系统观念，坚持规划引领，坚持统筹发展和安全，坚持保护第一、应保尽保、以用促保，因地制宜、分类指导，尽力而为、量力而行，建立可持续的城市更新体制机制和政策法规，高质量推进城市更新。A 项说法正确。到2030年，城市更新行动取得重要进展，城市开发建设方式转型初见成效，安全发展基础更加牢固，服务效能不断提高，人居环境明显改善，新旧动能加快转换，文化遗产有效保护，风貌特色更加彰显，治理水平大幅提高，城市成为人民群众高品质生活的空间。到2035年，城市更新体制机制更加完善，城市结构优化、动能转换、品质提升、绿色转型、文脉赓续、治理增效取得显著成效，创新、宜居、美丽、韧性、文明、智慧的现代化人民城市基本建成。B 项说法不正确。落实区域重大战略，因地制宜实施城市更新，优化现代化城市体系。推进超大特大城市治理现代化，以城市群、都市圈为依托构建大中小城市协调发展格局。坚持城乡融合发展，推进宜居县城建设，开展县城体检，因地制宜发展小城镇，加强边境小城镇建设，推动城镇基础设施和公共服务向乡村延伸覆盖。C项说法正确。实施房屋品质提升工程，兼顾增量建设与存量更新，全链条提升住房标准、设计、材料、建造、运维水平，建设改造安全舒适绿色智慧的“好房子”。鼓励居民开展既有住房装修和局部升级改造，推广装配式装修和适老化、无障碍改造，应用性能优异的新型建材。D项说法正确。故本题选 B。"},{"id":"cg-4q14","n":14,"s":"2026年6月16日，《求是》杂志发表习近平总书记重要文章《一体推进教育科技人才发展》，文章指出，综合国力竞争归根到底是人才竞争。哪个国家拥有人才上的优势，哪个国家最后就会拥有实力上的优势。下列相关说法正确的是：\n①走创新发展之路，首先要重视集聚创新人才\n②人才资源是第一资源，也是创新活动中最为活跃、最为积极的因素\n③我国面临科技人才总量不足的突出矛盾，解决这个矛盾，关键是要改革和完善人才发展机制\n④要用好用活人才，建立更为灵活的人才管理机制，完善经费支持这个指挥棒，打通人才流动、使用、发挥作用中的体制机制障碍","o":["①②","③④","②③","①④"],"a":"A","e":"2026年6月16日，《求是》杂志发表习近平总书记重要文章《一体推进教育科技人才发展》，文章指出，综合国力竞争归根到底是人才竞争。中国这么多人，教育上去了，将来人才就会像井喷一样涌现出来。这是最有竞争力的。走创新发展之路，首先要重视集聚创新人才。①说法正确。人才资源是第一资源，也是创新活动中最为活跃、最为积极的因素。要把科技创新搞上去，就必须建设一支规模宏大、结构合理、素质优良的创新人才队伍。我国一方面科技人才总量不少，另一方面又面临人才结构性不足的突出矛盾，特别是在重大科研项目、重大工程、重点学科等领域领军人才严重不足。解决这个矛盾，关键是要改革和完善人才发展机制。一是要用好用活人才，建立更为灵活的人才管理机制，完善评价这个指挥棒，打通人才流动、使用、发挥作用中的体制机制障碍，统筹加强高层次创新人才、青年科技人才、实用技术人才等方面人才队伍建设，最大限度支持和帮助科技人员创新创业。二是要深化教育改革，推进素质教育，创新教育方法，提高人才培养质量，努力形成有利于创新人才成长的育人环境。②说法正确，③④说法有误。故本题选 A。"},{"id":"cg-4q15","n":15,"s":"习近平总书记在纪念江泽民同志诞辰100周年大会上的讲话指出，江泽民同志的一生，是光辉的一生、战斗的一生，他为争取民族独立、人民解放和实现国家富强、人民幸福鞠躬尽瘁、奋斗终身。下列不属于江泽民同志做出的重大历史贡献的是：","o":["他深刻总结国内外经验教训，强调治国必先治党、治党务必从严，越是改革开放、发展经济，越要加强党的领导、抓好党的建设","他深刻指出，发展经济的根本目的是提高全国人民生活水平和质量，强调要全面建设惠及十几亿人口的更高水平的小康社会","他领导我们确定党在社会主义初级阶段的基本纲领，确立社会主义市场经济体制的改革目标和基本框架","在党的十二大上，他鲜明提出“走自己的道路，建设有中国特色的社会主义”"],"a":"D","e":"2026年8月17日，习近平在纪念江泽民同志诞辰100周年大会上发表重要讲话指出，面对20世纪80年代末90年代初国际风云变幻和国内发生严重政治风波的重大考验时，他毫不动摇坚持经济建设这个中心，旗帜鲜明坚持四项基本原则，坚持改革开放，开展治理整顿，进行外交斗争，坚决维护了国家的独立、尊严、安全、稳定。他深刻总结国内外经验教训，强调治国必先治党、治党务必从严，越是改革开放、发展经济，越要加强党的领导、抓好党的建设。A 项属于江泽民同志作出的重大历史贡献。我们要学习江泽民同志真挚深厚的为民情怀。他深刻指出，发展经济的根本目的是提高全国人民生活水平和质量，强调要全面建设惠及十几亿人口的更高水平的小康社会。他要求党员、干部始终深怀爱民之心，恪守为民之责，善谋富民之策，多办利民之事，把最广大人民的根本利益实现好、维护好、发展好，把人民群众的积极性引导好、保护好、发挥好。B 项属于江泽民同志作出的重大历史贡献。我们要学习江泽民同志与时俱进的创新精神。他领导我们确定党在社会主义初级阶段的基本纲领，确立社会主义市场经济体制的改革目标和基本框架，确立公有制为主体、多种所有制经济共同发展的基本经济制度和按劳分配为主体、多种分配方式并存的分配制度，推动经济体制、政治体制、文化体制等各方面改革。C 项属于江泽民同志作出的重大历史贡献。D 项属于邓小平同志作出的重大历史贡献。故本题选 D。"},{"id":"cg-4q16","n":16,"s":"作为习近平党建思想“十四个坚持”的内涵要义之一，“坚持落实管党治党政治责任”是全面从严治党需要牢牢牵住的“牛鼻子”。关于坚持落实管党治党政治责任，下列说法正确的有几项？\n①对各级各部门党组织负责人特别是党委（党组）书记的考核，首先要看抓党建的实效\n②要真正把落实管党治党政治责任作为最根本的政治担当，紧紧咬住“责任”二字，抓住“问责”这个要害\n③党委书记要做管党治党的书记，当好第一责任人，对党负责，对本地区本单位的政治生态负责，对干部健康成长负责\n④纪委要把专责监督履行好，聚焦主责、干好主业，既不能去行使党委和政府的职权，也不能代替职能部门去抓监管","o":["1项","2项","3项","4项"],"a":"D","e":"2026年第17期《求是》文章《坚持落实管党治党政治责任》指出，①正确，对各级各部门党组织负责人特别是党委（党组）书记的考核，首先要看抓党建的实效，考核其他党员领导干部工作也要加大这方面的权重。②正确，各级党组织和全体党员、干部要真正把落实管党治党政治责任作为最根本的政治担当，紧紧咬住“责任”二字，抓住“问责”这个要害，把党的领导体现到统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局各个方面。③正确，党委书记要做管党治党的书记，当好第一责任人，对党负责，对本地区本单位的政治生态负责，对干部健康成长负责。④正确，党委要主动抓、主动管，不能用纪委的监督责任代替自身的主体责任，更不能放弃责任、一推了之。纪委要把专责监督履行好，聚焦主责、干好主业，既不能去行使党委和政府的职权，也不能代替职能部门去抓监管。故本题选 D。"},{"id":"cg-4q17","n":17,"s":"2026年4月，国务院印发《中国（内蒙古）自由贸易试验区总体方案》，至此，中国已设立23个自由贸易试验区，形成沿海、沿边、内陆全方位开放格局。下列自由贸易试验区与其战略定位对应不正确的是：","o":["中国（内蒙古）自由贸易试验区——建设沿边内陆开发开放战略高地和服务保障全国高质量发展示范区","中国（新疆）自由贸易试验区——着力打造开放型经济发展先行区、实体经济创新发展和产业转型升级示范区","中国（海南）自由贸易试验区——建设全面深化改革开放试验区、国家生态文明试验区、国际旅游消费中心和国家重大战略服务保障区","中国（山东）自由贸易试验区——加快推进新旧发展动能接续转换、发展海洋经济，形成对外开放新高地"],"a":"B","e":"A 项正确，中国（内蒙古）自由贸易试验区：因地制宜发挥内蒙古“内联八省近京畿、外接俄蒙通欧亚”的区位优势，深入参与共建“一带一路”和中蒙俄经济走廊建设，着力打造联通内外、辐射周边的信息交流中心、交通物流中心、要素资源配置中心、重点领域科技创新中心和产业合作中心，建设沿边内陆开发开放战略高地和服务保障全国高质量发展示范区域，打造稳边固边、经略周边、服务全国的战略支点。B 项错误，中国（新疆）自由贸易试验区：努力打造促进中西部地区高质量发展的示范样板，构建新疆融入国内国际双循环的重要枢纽，服务“一带一路”核心区建设，助力创建亚欧黄金通道和我国向西开放的桥头堡，为共建中国—中亚命运共同体作出积极贡献。中国（江苏）自由贸易试验区：着力打造开放型经济发展先行区、实体经济创新发展和产业转型升级示范区。C 项正确，中国(海南)自由贸易试验区：紧紧围绕建设全面深化改革开放试验区、国家生态文明试验区、国际旅游消费中心和国家重大战略服务保障区，把海南打造成为我国面向太平洋和印度洋的重要对外开放门户。D 项正确，中国（山东）自由贸易试验区：全面落实中央关于增强经济社会发展创新力、转变经济发展方式、建设海洋强国的要求，加快推进新旧发展动能接续转换、发展海洋经济，形成对外开放新高地。故本题选 B。"},{"id":"cg-4q18","n":18,"s":"“十五五”规划纲要提出，推进国家安全体系和能力现代化，建设更高水平平安中国。下列举措不属于建设更高水平平安中国的是：","o":["完善公共安全体系，推动公共安全治理模式向事前预防转型，切实维护人民群众生命财产安全","完善涉外国家安全机制，构建海外安全保障体系，加强反制裁、反干预、反“长臂管辖”斗争","推进新域新质作战力量规模化、实战化、体系化发展，加快无人智能作战力量及反制能力建设","强化源头防控，统筹推进房地产、地方政府债务、中小金融机构等风险有序化解，严防系统性风险"],"a":"C","e":"ABD项属于，建设更高水平平安中国侧重加强国家安全体系和能力建设、保障国家经济安全、提高公共安全治理水平、完善社会治理体系。C项不属于，该举措属于“如期实现建军一百年奋斗目标，高质量推进国防和军队现代化”。本题为选非题，故本题选C。"},{"id":"cg-4q19","n":19,"s":"全球生态治理关乎人类共同命运，人与自然是相互依存、密不可分的生命共同体。应对全球性生态问题，世界各国拥有保护生态环境、守护地球家园的共同责任，但各国发展阶段不同、国情禀赋各异，需要立足自身实际、因地制宜承担差异化责任，协同推进全球生态环境持续改善。这一论述主要蕴含的哲理是（）。\n①辩证的否定是事物自我的否定\n②矛盾的普遍性寓于特殊性之中\n③矛盾双方共处于一个统一体中\n④事物的发展总是从量变开始的","o":["①②","②③","①④","③④"],"a":"B","e":"“人与自然是相互依存、密不可分的生命共同体” 体现矛盾双方共处于一个统一体中，③正确；世界各国拥有共同责任（矛盾普遍性），同时立足国情因地制宜承担差异化责任（矛盾特殊性），体现矛盾普遍性寓于特殊性之中，②正确。材料没有体现辩证否定、量变，①④不符合题意。故本题选B。"},{"id":"cg-4q20","n":20,"s":"如果某企业在市场竞争中，率先采用新技术、新设备提高劳动生产率，将直接导致的结果是（）。","o":["降低社会必要劳动时间","获得产品超额利润","降低单位商品的价值量","获得行业垄断利润"],"a":"B","e":"当个别企业率先采用新技术、新设备时，意味着该企业的个别生产时间缩短，个别生产效率提高，成本降低，而此时的社会必要劳动时间没变，该企业生产的同类商品市场价值量不变，此时该企业能够获取的高于正常水平的利润，即超额利润。故本题选 B。"}]},{"id":"cg-5","cat":"zz","title":"超格考前五套卷 · 第五套","short":"超格第五套","sub":"20 题","questions":[{"id":"cg-5q1","n":1,"s":"党的二十届五中全会强调，必须体系化推进各层级各领域党组织建设，强化党组织政治功能和组织功能，确保贯彻落实党的路线方针政策和党中央决策部署上下协同、精准高效。下列相关说法不正确的是：","o":["把地方党委建设成为坚决听从党中央指挥、执行有力、管理严格、班子团结、风气纯正的坚强组织","强化大抓基层鲜明导向，坚持补短板、填空白和提质量、强功能并举，把基层党组织建设成为有效实现党的领导的坚强战斗堡垒","加强平台企业、科技创新型企业等党建工作，建立互联网企业党组织同级管理动态调整机制","坚持把政治标准放在首位，严格程序、严格把关、严肃纪律，提高发展党员质量，防止动机不纯的人入党"],"a":"C","e":"党的二十届五中全会指出，坚持地方党委在本地区发挥总揽全局、协调各方的领导作用，履行把方向、管大局、作决策、保落实职责，把地方党委建设成为坚决听从党中央指挥、执行有力、管理严格、班子团结、风气纯正的坚强组织。A 项说法正确。强化大抓基层鲜明导向，坚持补短板、填空白和提质量、强功能并举，把基层党组织建设成为有效实现党的领导的坚强战斗堡垒。B 项说法正确。巩固提升非公有制企业党建工作，分类推进混合所有制企业党建工作，加强平台企业、科技创新型企业等党建工作，建立互联网企业党组织提级管理动态调整机制，推动落实党建责任。C 项说法不准确。坚持把政治标准放在首位，严格程序、严格把关、严肃纪律，提高发展党员质量，防止动机不纯的人入党。D 选项说法正确。故本题选 C。"},{"id":"cg-5q2","n":2,"s":"2026年10月，《中共中央 国务院关于发展新质生产力的意见》重磅发布，《意见》围绕科技创新、产业创新、发展方式创新、体制机制创新、人才工作机制创新五方面，提出重点举措。以下不属于推动科技创新和产业创新深度融合的举措的是：","o":["改造提升传统产业、培育壮大新兴产业、前瞻布局未来产业","加强原创性颠覆性科技创新","促进实体经济和数字经济深度融合","全面实施“人工智能+”行动"],"a":"B","e":"2026年10月，《中共中央 国务院关于发展新质生产力的意见》重磅发布，《意见》围绕科技创新、产业创新、发展方式创新、体制机制创新、人才工作机制创新五方面，提出重点举措。其中，推动科技创新和产业创新深度融合的举措包括：改造提升传统产业；培育壮大新兴产业；前瞻布局未来产业；促进实体经济和数字经济深度融合；全面实施“人工智能+”行动。ACD属于推动科技创新和产业创新深度融合的举措。B 项属于大力推进科技创新的举措。故本题选 B。"},{"id":"cg-5q3","n":3,"s":"2026年1月16日，《求是》杂志刊发了习近平总书记《在中央城市工作会议上的讲话》，文章指出，党的十八大以来，我们推动城市发展取得历史性成就，同时，我国城市发展也面临一些新情况新问题。下列相关说法正确的是：","o":["城市基础设施迭代升级，公共服务功能逐步完善，安全韧性水平整体提高，建成世界规模最大的城市住房保障体系","人口结构呈现整体稳定态势，但城市老龄化少子化、区域人口增减分化特征明显","我国城镇化正从快速增长期转向稳定发展期，城市发展正从存量提质增效阶段转向增量扩张为主的阶段","要以建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市为目标，以推动城市高质量发展为主题，以坚持规模化发展为主线，以推进城市更新为重要抓手"],"a":"A","e":"2026年1月16日，《求是》杂志刊发了习近平总书记《在中央城市工作会议上的讲话》，文章指出，城市基础设施迭代升级，公共服务功能逐步完善，安全韧性水平整体提高，建成世界规模最大的城市住房保障体系。A 项说法正确。我国城市发展也面临一些新情况新问题：城市老龄化少子化、区域人口增减分化特征明显，人口结构快速变化；“土地财政”难以为继；城市部分房屋和基础设施老化，安全稳定风险增多，治理难度加大。总的看，我国城镇化正从快速增长期转向稳定发展期，城市发展正从大规模增量扩张阶段转向存量提质增效为主的阶段。BC 说法不准确。当前和今后一个时期城市工作的总体要求是：以新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三中全会精神，坚持和加强党的全面领导，认真践行人民城市理念，坚持稳中求进工作总基调，坚持因地制宜、分类指导，以建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市为目标，以推动城市高质量发展为主题，以坚持城市内涵式发展为主线，以推进城市更新为重要抓手，大力推动城市结构优化、动能转换、品质提升、绿色转型、文脉赓续、治理增效，牢牢守住城市安全底线，走出一条中国特色城市现代化新路子。D 项说法不准确。故本题选 A。"},{"id":"cg-5q4","n":4,"s":"2026年6月，《加快农业农村现代化“十五五”规划》对外发布，《规划》指出，“十五五”时期是基本实现农业农村现代化的关键时期。下列相关说法正确的是：","o":["以推进乡村全面振兴为总抓手，以学习运用“千万工程”经验为引领，以改革创新为根本动力，一体推进农业现代化和农村现代化","到2030年，乡村全面振兴取得决定性进展，农业现代化基本实现，农村基本具备现代生活条件，农业强国建设取得显著成效","推动农业由产量主导向品质主导转变，增加优质食味稻、强筋弱筋专用小麦、高产高油大豆供给","强化开发式帮扶，发挥以工代赈兜底保障作用，确保不发生规模性返贫致贫"],"a":"A","e":"2026年6月，《加快农业农村现代化“十五五”规划》对外发布，《规划》指出，坚持农业农村优先发展，坚持城乡融合发展，锚定建设农业强国目标，以推进乡村全面振兴为总抓手，以学习运用“千万工程”经验为引领，以改革创新为根本动力，一体推进农业现代化和农村现代化。A项说法正确。到2035年，乡村全面振兴取得决定性进展，农业现代化基本实现，农村基本具备现代生活条件，农业强国建设取得显著成效。B项说法不正确。推动农业由产量主导向产量品质并重转变，增加优质食味稻、强筋弱筋专用小麦、高产高油大豆供给，提供更多营养、健康、风味农产品。C项说法不正确。强化开发式帮扶，发挥社会救助兜底保障作用，确保不发生规模性返贫致贫。分类推进现有产业巩固、升级、盘活、调整，推动主导产业全链开发，健全帮扶项目资产长效管理机制。D项说法不正确。故本题选A。"},{"id":"cg-5q5","n":5,"s":"《中华人民共和国国民经济和社会发展第十五个五年规划纲要》提出，加快高水平科技自立自强，引领发展新质生产力。下列有关说法正确的是：","o":["打好关键核心技术攻坚战，强化以攻促用、攻用结合，加快攻关成果应用和产品迭代升级","全面提升基础研究水平，完善以竞争性支持为主的投入机制，探索长周期资助模式","以创新能力、质量、实效、贡献为评价导向，深化项目评审、机构评估、人才评价、收入分配改革","发挥科技领军企业龙头作用，支持科技领军企业牵头实施国家重大科技任务、探索新型科研组织模式"],"a":"C","e":"A项错误，《纲要》指出：打好关键核心技术攻坚战。强化以用促攻、攻用结合，一体推进技术研发、成果转化、标准研制、产业培育，加快攻关成果应用和产品迭代升级。B项错误，《纲要》指出：全面提升基础研究水平。完善竞争性支持和稳定支持相结合的投入机制，加大对从事基础研究的优势团队和青年科技人才长期稳定支持，探索长周期资助模式。C项正确，《纲要》指出：以创新能力、质量、实效、贡献为评价导向，深化项目评审、机构评估、人才评价、收入分配改革，激发创新创造动力活力。D项错误，《纲要》指出：优化国家实验室、国家科研机构、高水平研究型大学和科技领军企业等国家战略科技力量定位和布局。发挥国家实验室龙头作用，支持国家实验室牵头实施国家重大科技任务、探索新型科研组织模式，加强全国重点实验室建设。故本题选C。"},{"id":"cg-5q6","n":6,"s":"习近平总书记强调，基础研究是整个科学体系的源头，是所有技术问题的总机关，是全球科技竞争的前沿阵地。关于加强基础研究的举措，下列说法正确的是：","o":["加强基础研究要坚持“四个面向”，坚持自由探索这个唯一根本导向","加紧建设世界一流科技期刊，鼓励重大基础研究成果率先在国外优秀期刊和平台首发","学科体系是基础研究的重要基础，面对学科边界不断拓展的新形势，要完善学科设置调整机制","基础研究归根结底靠高水平人才，要把引进全球顶尖基础研究人才和青年科研骨干作为主渠道，进一步壮大基础研究后备力量"],"a":"C","e":"A错误，2023年第15期《求是》文章《加强基础研究 实现高水平科技自立自强》指出，要坚持“四个面向”，坚持目标导向和自由探索“两条腿走路”，把世界科技前沿同国家重大战略需求和经济社会发展目标结合起来，统筹遵循科学发展规律提出的前沿问题和重大应用研究中抽象出的理论问题，凝练基础研究关键科学问题。B错误，2026年第18期《求是》文章《在加强基础研究座谈会上的讲话》指出，加紧建设世界一流科技期刊，鼓励国内外成果在我国期刊和平台首发。2023年第15期《求是》文章《加强基础研究 实现高水平科技自立自强》指出，要加快培育世界一流科技期刊，建设具有国际影响力的科技文献和数据平台，发起高水平国际学术会议，鼓励重大基础研究成果率先在我国期刊、平台上发表和开发利用。C正确，2026年第18期《求是》文章《在加强基础研究座谈会上的讲话》指出，学科体系是基础研究的重要基础。面对学科边界不断拓展的新形势，要完善学科设置调整机制。D错误，2026年第18期《求是》文章《在加强基础研究座谈会上的讲话》指出，基础研究归根结底靠高水平人才。要一体推进教育科技人才发展，全方位做好培养、引进、使用工作，努力使基础研究人才数量充足、素质优良、结构合理。要着力提高自主培养质量。自主培养始终是人才培养的主渠道。要大力扶持青年人才。青年人才是基础研究的生力军，很多重大成果都是年轻人做出来的。故本题选C。"},{"id":"cg-5q7","n":7,"s":"习近平总书记强调，要站在统筹高质量发展和高水平安全的战略高度，充分认识做好防灾减灾救灾工作的重要性，着力提高防范应对自然灾害能力，切实维护人民群众生命财产安全。下列相关说法正确的有几项？\n①坚持统分结合、防救衔接、上下联动，推动形成齐抓共管、协同配合的工作格局\n②我国国土广袤、地理复杂、气候多样，自然灾害少发，且影响范围较小\n③要树牢底线思维、极限思维深入研判大灾巨灾风险，强化监测预警，完善应急预案\n④降低灾害风险，减轻灾害损失，重在事前预防\n⑤基层是抵御自然灾害的第一线，抓基层、强基础的工作始终不能放松","o":["2项","3项","4项","5项"],"a":"C","e":"2026年4月28日下午，中共中央政治局就提高防灾减灾救灾能力进行第二十五次集体学习。①项正确，坚持统分结合、防救衔接、上下联动，推动形成齐抓共管、协同配合的工作格局。②项错误，我国国土广袤、地理复杂、气候多样，自然灾害易发多发。③项正确，要树牢底线思维、极限思维深入研判大灾巨灾风险，强化监测预警，完善应急预案。④项正确，降低灾害风险，减轻灾害损失，重在事前预防。⑤项正确，基层是抵御自然灾害的第一线，抓基层、强基础的工作始终不能放松。故本题选C。"},{"id":"cg-5q8","n":8,"s":"国家安全是中国式现代化行稳致远的重要基础。关于国家安全，以下说法不准确的是：","o":["新时代的中国国家安全是总体的、系统的、绝对的大安全，是以人民安全为宗旨、以政治安全为根本、以国家利益为准则的安全","总体国家安全观的关键在于“总体”，“总体”是新时代中国国家安全的灵魂","坚持把政治安全摆在首位，这是新时代中国国家安全的生命线","加强党对国家安全工作的绝对领导，这是新时代中国国家安全的根本保证"],"a":"A","e":"新时代的中国国家安全是总体的、系统的、相对的大安全，是以人民安全为宗旨、以政治安全为根本、以国家利益为准则的安全，是服务和促进高质量发展的安全，是根据经济社会发展动态调整的安全，是支撑进一步扩大高水平开放的安全，是在法治轨道上规范运行的安全。中国统筹自身安全和共同安全，反对安全泛化，不实施安全胁迫，不接受威胁施压，坚持独立自主、自信自立，把解决安全难题放在自身力量的基点上，坚持中国特色国家安全道路。A说法不准确。总体国家安全观的关键在于“总体”，“总体”是新时代中国国家安全的灵魂。它突出大安全理念，涵盖政治、军事、国土、经济、金融、文化、社会、科技、网络、粮食、生态、资源、核、海外利益、太空、深海、极地、生物、人工智能、数据等诸多领域，并随着社会发展不断动态调整。大安全，是新形势下对国家生存和可持续发展的维护，但不是安全泛化，更不是追求绝对安全。大安全是通过抓好一地一域一业的安全为国家总体安全创造条件，是通过及时有效解决一个个安全问题为国家长治久安筑牢根基。B说法正确。坚持把政治安全摆在首位，这是新时代中国国家安全的生命线。政治安全的核心是政权安全和制度安全，最根本的就是维护中国共产党的领导和执政地位、维护中国特色社会主义制度。C说法正确。中国国家安全关键在党。加强党对国家安全工作的绝对领导，这是新时代中国国家安全的根本保证。D说法正确。故本题选A。"},{"id":"cg-5q9","n":9,"s":"中国共产党第二十届中央纪律检查委员会第五次全体会议，于2026年1月12日至14日在北京举行。全会提出，强化标本兼治，用好一体推进不敢腐、不能腐、不想腐战略抓手。下列相关说法正确的有几项？\n①以加强监督制约强化不敢腐，坚持猛药去疴、重典治乱\n②以保持高压震慑强化不能腐，健全授权用权制权相统一、清晰透明可追溯的制度机制\n③以深化廉洁教育强化不想腐，提升廉洁宣传教育的针对性有效性\n④以完善体制机制促进一体推进，健全党委统一领导下的反腐败工作机制","o":["1项","2项","3项","4项"],"a":"B","e":"中国共产党第二十届中央纪律检查委员会第五次全体会议，于2026年1月12日至14日在北京举行。全会提出，强化标本兼治，用好一体推进不敢腐、不能腐、不想腐战略抓手。以保持高压震慑强化不敢腐，坚持猛药去疴、重典治乱，继续起底清理，深化整治金融、国企、能源、教育、学会协会、开发区和招标投标等重点领域腐败，严肃查处政商勾连、权力为资本提供保护、资本向政治领域渗透等问题，深挖细查预期收益、约定代持、政商“旋转门”等新型腐败和隐性腐败，着重查处“关键少数”、年轻干部腐败，深化受贿行贿一起查，加大跨境腐败案件查办力度，配合全国人大常委会制定反跨境腐败法。不断提高反腐败穿透力，及时发现、准确识别、有效治理各类腐败问题。以加强监督制约强化不能腐，健全授权用权制权相统一、清晰透明可追溯的制度机制，协助党中央修订《中国共产党党内监督条例》，深入落实关于加强对“一把手”和领导班子监督的意见，推动科学授权、正确用权、有效制权。以深化廉洁教育强化不想腐，深入落实新时代廉洁文化建设三年行动计划，提升廉洁宣传教育的针对性有效性，不断塑造清正廉洁的思想品格、廉洁奉公的政德修养、廉洁自律的道德操守、崇廉拒腐的社会风尚。以完善体制机制促进一体推进，健全党委统一领导下的反腐败工作机制，完善反腐败责任落实机制，深化以案促改促治，注重科技赋能，加快推进数字纪检监察体系建设，严格依规依纪依法使用。①②说法有误，故本题选B。"},{"id":"cg-5q10","n":10,"s":"2026年5月13日至15日，应国家主席习近平邀请，美国总统对中国进行国事访问。下列相关说法不准确的是：","o":["中美经贸关系的本质是相互竞争，面对分歧和摩擦，平等协商是唯一正确选择","台湾问题是中美关系中最重要的问题，处理好了，两国关系就能保持总体稳定","中美关系是当今世界最重要的双边关系，只能搞好不能搞坏","能不能做到相互尊重、和平共处、合作共赢是双边关系能否稳定发展的关键所在"],"a":"A","e":"中美经贸关系的本质是互利共赢，面对分歧和摩擦，平等协商是唯一正确选择。A项说法不准确。台湾问题是中美关系中最重要的问题。处理好了，两国关系就能保持总体稳定。“台独”与台海和平水火不容，维护台海和平稳定是中美双方最大公约数，美方务必慎之又慎处理台湾问题。B项说法正确。中美关系是当今世界最重要的双边关系，只能搞好不能搞坏。两国合则两利、斗则俱伤，应该成为伙伴而不是对手。我们同意构建中美建设性战略稳定关系，推动中美关系稳定、健康、可持续发展，为世界带来更多和平、繁荣、进步。C项说法正确。纵观中美关系发展历程，能不能做到相互尊重、和平共处、合作共赢是双边关系能否稳定发展的关键所在。D项说法正确。故本题选 A。"},{"id":"cg-5q11","n":11,"s":"党的二十届五中全会强调，必须完善和落实民主集中制各项制度，充分发扬党内民主，有效实行正确的集中，更好发挥民主集中制的政治优势、组织优势、制度优势、工作优势。下列相关说法正确的有几项？\n①坚持和完善党内民主制度，尊重党员主体地位，保障党员民主权利\n②完善党委（党组）议事规则和决策程序，重要议题出现较大意见分歧时不得强行作出决策\n③健全领导班子权力运行制约机制，规范“一把手”职责权限，执行“一把手”首位表态制\n④维护党中央和各级党委权威，强化层层要求维护“一把手”个人权威","o":["1项","2项","3项","4项"],"a":"B","e":"党的二十届五中全会指出，坚持和完善党内民主制度，尊重党员主体地位，保障党员民主权利。①说法正确。完善党委（党组）议事规则和决策程序，加强重大决策的调查研究、科学论证、风险评估，重要议题出现较大意见分歧时不得强行作出决策。②说法正确。落实加强对“一把手”和领导班子监督的制度规定。选拔任用“一把手”注重考察贯彻执行民主集中制素养和能力。健全领导班子权力运行制约机制，规范“一把手”职责权限，执行“一把手”末位表态制。书记专题会议不得代替党委常委会会议作出决策。党委（党组）书记必须发扬民主，认真听取不同意见，正确对待少数人意见，不搞“一言堂”“家长制”，该由集体研究的不得擅自表态，不得用个人意见代替班子集体决定，不得擅自改变集体决定，不得层层要求维护“一把手”个人权威。③④说法有误。故本题选 B。"},{"id":"cg-5q12","n":12,"s":"2026年6月，国务院新闻办公室发布《构建更加公正合理的全球治理体系：中国的理念、倡议与行动》白皮书，白皮书指出，全球治理是关乎人类福祉的共同事业，构建公正合理的全球治理体系是各国人民孜孜以求的共同愿景。关于全球治理，下列说法不正确的是：","o":["落实全球治理倡议，最根本的是坚定维护联合国的权威和地位，最关键的是大国展现责任担当，最需要的是各国团结合作，最紧迫的是弥补和平与发展赤字","国际法治是全球治理的根本保障，唯有基于法治的全球治理体系，才能真正为各国提供公平公正的发展环境","作为最大的发展中国家，中国始终将自身发展置于人类发展的坐标系，坚持开放共赢、倡导普惠包容，积极输出中国式现代化这一全新模式","人类福祉是全球治理的核心关切，各国人民是全球治理的根本参与者和受益者"],"a":"C","e":"2026年6月，国务院新闻办公室发布《构建更加公正合理的全球治理体系：中国的理念、倡议与行动》白皮书，白皮书指出，中国提出全球治理倡议，旨在推动构建更加公正合理的全球治理体系。落实全球治理倡议，最根本的是坚定维护联合国的权威和地位，最关键的是大国展现责任担当，最需要的是各国团结合作，最紧迫的是弥补和平与发展赤字。必须毫不动摇地维护以联合国为核心的国际体系，维护以国际法为基础的国际秩序，维护以联合国宪章宗旨和原则为基础的国际关系基本准则，而不是另起炉灶。A项说法正确。国际法治是全球治理的根本保障。唯有基于法治的全球治理体系，才能真正为各国提供公平公正的发展环境，确保权利与义务的平衡，推动国际秩序朝着更加公正合理的方向演进。B项说法正确。作为最大的发展中国家，中国始终将自身发展置于人类发展的坐标系，坚持开放共赢、倡导普惠包容，以中国式现代化为世界提供新机遇，促进世界各国现代化的发展潮流。C项说法不正确。人类福祉是全球治理的核心关切，各国人民是全球治理的根本参与者和受益者。只有以人民的获得为目标，不断为民众提供信心和稳定预期，全球治理体系才能得到广泛支持并有效运作。D 项说法正确。故本题选 C。"},{"id":"cg-5q13","n":13,"s":"2026年6月，中央党的建设工作领导小组印发《关于学习贯彻习近平党建思想的通知》，《通知》强调，要深入学习领会习近平党建思想的实践基础和理论渊源。下列相关说法正确的有几项？\n①习近平党建思想丰富和发展了马克思主义建党学说，是坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合推进党的理论创新的重大成果\n②习近平党建思想蕴含着坚定的理想信念、高度的历史主动、鲜明的问题导向、强烈的使命担当、深厚的为民情怀、科学的思想方法，明体达用、体用贯通，具有鲜明的理论品格\n③习近平党建思想源自于马克思主义科学理论，植根于中华优秀传统文化，孕育于新时代全面从严治党的伟大实践，具有坚实的实践基础和深厚的理论渊源\n④习近平党建思想是习近平新时代中国特色社会主义思想的重要组成部分，为深入推进新时代党的建设新的伟大工程提供了根本遵循和行动指南","o":["1项","2项","3项","4项"],"a":"D","e":"2026年6月，中央党的建设工作领导小组印发《关于学习贯彻习近平党建思想的通知》，《通知》强调，习近平党建思想丰富和发展了马克思主义建党学说，是坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合推进党的理论创新的重大成果，是党和人民实践经验和集体智慧的结晶，是习近平新时代中国特色社会主义思想的重要组成部分，为深入推进新时代党的建设新的伟大工程提供了根本遵循和行动指南。①④说法正确。习近平党建思想蕴含的坚定的理想信念、高度的历史主动、鲜明的问题导向、强烈的使命担当、深厚的为民情怀、科学的思想方法，明体达用、体用贯通，具有鲜明的理论品格。②说法正确。习近平党建思想源自于马克思主义科学理论，植根于中华优秀传统文化，孕育于新时代全面从严治党的伟大实践，是马克思主义建党学说中国化时代化的最新成果。③说法正确。故本题选 D。"},{"id":"cg-5q14","n":14,"s":"2025年12月25日至26日，中共中央政治局召开民主生活会，中共中央总书记习近平主持会议并发表重要讲话。下列相关说法正确的有几项？\n①笃信马克思主义，坚定理想信念是共产党人的立身之本\n②共产党人是唯物主义者，务实是必备品格，必须实事求是、求真务实、真抓实干\n③领导干部要勇于担当，在其位、谋其政、尽其责，在职责范围内主动担重、担难\n④要严格执行民主集中制，严格落实中央八项规定及其实施细则精神，严格遵守议事决策规则，自觉按制度规矩办事","o":["1项","2项","3项","4项"],"a":"D","e":"2025年12月25日至26日，中共中央政治局召开民主生活会，中共中央总书记习近平主持会议并发表重要讲话。习近平总书记指出，笃信马克思主义，坚定理想信念，是共产党人的立身之本。①说法正确。习近平总书记强调，共产党人是唯物主义者，务实是必备品格，必须实事求是、求真务实、真抓实干。②说法正确。习近平总书记指出，领导干部要勇于担当，在其位、谋其政、尽其责，在职责范围内主动担重、担难。要正视困难矛盾、风险隐患，迎难而上、攻坚克难。要坚持党性原则，是非分明、敢于斗争，在重大问题、原则问题上旗帜鲜明。③说法正确。习近平总书记强调，领导干部特别是高级干部必须头脑清醒、严格自律，始终保持本色、安守本分，如临如履、谦虚谨慎。要严格执行民主集中制，严格落实中央八项规定及其实施细则精神，严格遵守议事决策规则，自觉按制度规矩办事。要怀德自重、洁身自好，反对特权思想和特权行为，管好身边人身边事，真正做到清正廉洁。④说法正确。故本题选 D。"},{"id":"cg-5q15","n":15,"s":"2026年6月15日，国务院以 “强化主体功能区战略实施，促进区域协调发展” 为主题，进行第二十次专题学习。关于实施主体功能区战略，以下说法不准确的是：","o":["充分考虑国家战略需求和地方发展条件的变化，在科学评估基础上对主体功能定位进行动态调整","根据地方独特区位和资源禀赋，对特殊功能区实施差异化管理","要完善与主体功能区相适应的政策制度体系，引导不同地区同质同步发展","对农产品主产区和重点生态功能区给予更多保障性政策，健全强化转移支付、保护补偿等机制"],"a":"C","e":"2026年6月15日，国务院以“强化主体功能区战略实施，促进区域协调发展”为主题，进行第二十次专题学习。要聚焦突出矛盾，找准切入点，更大力度推动主体功能区战略有效落地。要优化主体功能区划，推动空间治理更加精准精细。充分考虑国家战略需求和地方发展条件的变化，在科学评估基础上对主体功能定位进行动态调整。根据地方独特区位和资源禀赋，对特殊功能区实施差异化管理。拓展国土空间规划“一张图”信息集成功能，推动跨部门跨层级共享共用，构建国土空间治理基础平台。要完善与主体功能区相适应的政策制度体系，引导不同地区差异化协同发展。对城市化地区给予更多激励性政策，引导资源要素适当倾斜配置。对农产品主产区和重点生态功能区给予更多保障性政策，健全强化转移支付、保护补偿等机制。故本题选C。"},{"id":"cg-5q16","n":16,"s":"习近平总书记在新时代文化建设方面提出一系列新思想新观点新论断，丰富和发展了马克思主义文化理论，构成了习近平新时代中国特色社会主义思想的文化篇，形成了习近平文化思想。关于习近平文化思想，下列表述不正确的是：\n①推动文艺繁荣发展，最根本的是要重构文艺人才培养体系，建设社会主义文艺人才队伍②在新的时代条件下，要承担起党的新闻舆论工作的职责和使命，坚持贴合人民群众喜好第一位的\n③中国式现代化，借鉴吸收一切人类优秀文明成果，展现了不同于西方现代化模式的新图景\n④坚持以马克思主义为指导，首先要解决真懂真信的问题，核心要解决好为什么人的问题","o":["①②","①④","②③","③④"],"a":"A","e":"2026年8月，中共中央党史和文献研究院编辑的《习近平文化文选》第一卷、第二卷出版发行。①错误，推动文艺繁荣发展，最根本的是要创作生产出无愧于我们这个伟大民族、伟大时代的优秀作品。②错误，在新的时代条件下，党的新闻舆论工作的职责和使命是，高举旗帜、引领导向，围绕中心、服务大局，团结人民、鼓舞士气，成风化人、凝心聚力，澄清谬误、明辨是非，联接中外、沟通世界。要承担起这个职责和使命，坚持正确政治方向是第一位的。③正确，中国式现代化，深深植根于中华优秀传统文化，体现科学社会主义的先进本质，借鉴吸收一切人类优秀文明成果，代表人类文明进步的发展方向，展现了不同于西方现代化模式的新图景，是一种全新的人类文明形态。④正确，坚持以马克思主义为指导，首先要解决真懂真信的问题，核心要解决好为什么人的问题，最终要落实到怎么用上来。故本题选 A。"},{"id":"cg-5q17","n":17,"s":"节能降碳是推进碳达峰碳中和、加快发展方式绿色转型的重要抓手，是维护国家能源安全、促进产业提质升级的重要支撑。下列关于协同推进节能降碳与绿色转型，表述正确的有几项？\n①强化节能降碳激励约束和标准提升引领，持续降低产业对能源的依赖\n②科学调控能源消费总量，严格控制化石能源消费，深入推进减煤控油，强化新增用煤用油需求管理\n③合理控制煤电装机规模和发电量，大力发展非化石能源和新型储能，加快建设新型电力系统\n④推动清洁能源发电量逐步覆盖全社会用电需求","o":["1项","2项","3项","4项"],"a":"C","e":"2026年4月，《中共中央办公厅 国务院办公厅关于更高水平更高质量做好节能降碳工作的意见》指出，①正确，强化节能降碳激励约束和标准提升引领，持续降低产业对能源的依赖。②正确，科学调控能源消费总量，严格控制化石能源消费，深入推进减煤控油，强化新增用煤用油需求管理。③正确，合理控制煤电装机规模和发电量，大力发展非化石能源和新型储能，加快建设新型电力系统。④错误，推动新增清洁能源发电量逐步覆盖全社会新增用电需求。故本题选 C。"},{"id":"cg-5q18","n":18,"s":"习近平总书记强调，中国共产党因理想而生，为使命而战。只要心中有理想、胸中有家国、肩上有使命，就能站得高看得远，不断增强信心和力量；就能压倒一切困难、不为困难所压倒，形成全党一条心、全国一盘棋，切实把党中央重大决策部署贯彻落实好，凝心聚力征服一个个“娄山关”“腊子口”。这一论述所体现的马克思主义原理是：","o":["事物的性质由主要矛盾的主要方面决定","辩证的否定是事物联系和发展的环节","意识对物质具有能动的反作用","矛盾具有特殊性，要做到具体问题具体分析"],"a":"C","e":"题干“心中有理想、胸中有家国、肩上有使命”，就能“站得高看得远”“增强信心和力量”“压倒一切困难”，“形成全党一条心、全国一盘棋，推动党中央决策部署贯彻落实”强调正确意识能够指导人们认识世界和改造世界，体现意识对物质具有能动的反作用。ABD说法正确，但题干未涉及。故本题选C。"},{"id":"cg-5q19","n":19,"s":"全面推进乡村振兴、加快建设农业强国，是夯实中国式现代化根基的重大战略任务。宜居宜业的和美乡村、蒸蒸日上的乡村产业、富足安稳的农民生活，这些实实在在的发展成效，从来不是凭空出现、坐等而来的，也不是口头号召就能实现的，而是各级干部扎根基层、真抓实干，广大农民群众勤劳耕耘、拼搏进取，日复一日脚踏实地奋斗出来的。这蕴含的哲理是（）。","o":["实践是主观见之于客观的物质活动，具有直接现实性","实践是人类有目的的自觉活动，具有自觉能动性","实践活动是不断发展的，具有社会历史性","实践是人类获得成功的基础，具有必然性"],"a":"A","e":"A项符合题意，发展成效不是凭空等来、靠口号实现，而是依靠实干奋斗取得，体现实践具有直接现实性，能够把观念中的东西变成现实的东西。B 说法不符合题意，自觉能动性侧重实践带有目的、意识指导，不是题干重点。C 说法不符合题意，社会历史性侧重实践受历史条件制约、是历史地变化发展，材料未体现。D 说法错误，实践不具有必然性，实践也不一定必然带来成功。故本题选 A。"},{"id":"cg-5q20","n":20,"s":"近几年来，我国各种电子产品的价格呈不断下跌的趋势，商家也采用降价、返券或买产品赠周边礼品等各种促销手段，以保证产品的销售，形成价格下跌这一趋势的根本原因是（）。","o":["国家对商品价格的宏观调整","社会劳动生产率不断提高","市场为主导的价格机制正在形成","市场供给超过了市场需求"],"a":"B","e":"价格总是以价值为基础，围绕价值上下波动是价值规律的唯一表现形式。商品的价值量由生产这种商品的社会必要劳动时间决定，商品交换以价值量为基础，按照等价交换的原则进行。当社会劳动生产率不断提高时，生产商品的社会必要劳动时间缩短，单位商品的价值量下降。B项符合题意。故本题选 B。"}]},{"id":"xh-zz","cat":"zz","title":"小黑最后冲刺 · 50 题","short":"冲刺 50 题","sub":"50 题","questions":[{"id":"xh-zzq1","n":1,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。持之以恒推进全面从严治党，是我们党作为马克思主义执政党所承担的使命和责任决定的。下列属于持之以恒推进全面从严治党重要意义的是：\n①是保持党的先进性和纯洁性、巩固党的长期执政地位的必然要求\n②是巩固和发展全党高度团结统一、党心军心民心高度凝聚良好政治局面的必然要求\n③是实现党的历史使命、推动党和国家事业行稳致远的必然要求\n④是坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化的必然要求","o":["①②③","①②④","①③④","②③④"],"a":"A","e":""},{"id":"xh-zzq2","n":2,"s":"2026年2月，《中共中央国务院关于锚定农业农村现代化扎实推进乡村全面振兴的意见》发布。文件指出，要实施常态化精准帮扶。下列属于相关措施的有几项？\n①健全常态化帮扶政策体系\n②提高监测帮扶精准性时效性\n③提升产业和就业帮扶实效\n④集中统一帮扶欠发达地区\n⑤加强耕地保护和质量提升","o":["2项","3项","4项","5项"],"a":"B","e":""},{"id":"xh-zzq3","n":3,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议把严格贯彻执行民主集中制作为全面从严治党的重要着力点，并且作出了具体部署。下列属于相关部署的是：\n①坚持和加强党中央集中统一领导\n②提高党内民主质量\n③严格执行领导班子决策议事规则\n④规范”一把手”履职用权\n⑤提高培养选拔优秀年轻干部质量","o":["①②③④⑤","①②③④","①②③⑤","②③④⑤"],"a":"B","e":""},{"id":"xh-zzq4","n":4,"s":"2026年10月22日，纪念中国工农红军长征胜利90周年大会在京隆重举行。下列属于伟大长征精神的是：\n①把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信念，坚信正义事业必然胜利的精神\n②为了救国救民，不怕任何艰难险阻，不惜付出一切牺牲的精神\n③坚持独立自主、实事求是，一切从实际出发的精神\n④顾全大局、严守纪律、紧密团结的精神\n⑤紧紧依靠人民群众，同人民群众生死相依、患难与共、艰苦奋斗的精神\n⑥互信、互利、平等、协商、尊重多样文明、谋求共同发展","o":["①②③④⑤","①②③⑤⑥","①③④⑤⑥","①②③④⑤⑥"],"a":"A","e":""},{"id":"xh-zzq5","n":5,"s":"2026年10月9日，《中共中央国务院关于发展新质生产力的意见》发布。《意见》指出，要改造提升传统产业、培育壮大新兴产业、前瞻布局未来产业。下列属于”培育壮大新兴产业”相关举措的是：\n①巩固提升矿业、冶金、化工等产业在全球产业分工中的地位和竞争力\n②加快新一代信息技术、新能源、新材料、智能网联新能源汽车等产业发展\n③推动量子科技、氢能和核聚变能、具身智能、第六代移动通信等产业发展\n④在确保安全前提下，推动低空经济、商业航天健康有序发展","o":["①③","①④","②③","②④"],"a":"D","e":""},{"id":"xh-zzq6","n":6,"s":"持之以恒推进全面从严治党遵循的原则包括坚持服务使命任务，坚持以党的政治建设为统领，坚持全面从严，坚持问题导向，坚持守正创新，坚持以上率下，坚持依规治党。关于持之以恒推进全面从严治党遵循的原则，下列对应正确的是：\n①坚持问题导向—把解决党内突出问题作为着力点，不回避矛盾，不讳疾忌医……\n②坚持服务使命任务—坚持党的基本理论、基本路线、基本方略，遵循马克思主义执政党建设规律，运用党的建设历史经验，根据形势任务发展变化不断提出新举措新办法\n③坚持依规治党—把制度建设贯穿其中，注重用制度管权管事管人，严格执行党章党规党纪，以系统完备、科学规范、运行有效的党内法规制度体系增强工作效能\n④坚持全面从严—从党中央做起，从领导机关和领导干部严起，一级做给一级看、一级带着一级干，以”关键少数”示范带动”绝大多数”","o":["①③","②③","①④","②④"],"a":"A","e":""},{"id":"xh-zzq7","n":7,"s":"新时代以来，习近平总书记在地方考察和重要指示中，多次肯定基层创造的一系列先进发展治理经验，并要求各地结合实际学习借鉴、复制推广，更好推动高质量发展和社会治理现代化。下列经验与学习要求对应正确的是：","o":["学习”义乌发展经验”——引导各地区立足自身资源禀赋，因地制宜发展县域经济","学习”闽宁协作”经验——因地制宜完善乡村建设实施机制，推进乡村全面振兴","学习新时代”枫桥经验”—加强东西部协作，推动产业互补、人员互动、技术互学……","学习”千万工程”经验——紧紧依靠人民群众，把问题解决在基层、化解在萌芽状态"],"a":"A","e":""},{"id":"xh-zzq8","n":8,"s":"“六个必须坚持”是新时代中国特色社会主义思想的世界观和方法论，深刻揭示了这一思想的理论品格和鲜明特质，构成相互联系、内在统一的有机整体。下列对应准确的是：","o":["推进改革发展往往牵一发而动全身——坚持胸怀天下","既不能刻舟求剑、封闭僵化，也不能照抄照搬、食洋不化——坚持自信自立","为解决人类面临的共同问题作出贡献——坚持人民至上","人民的创造性实践是理论创新的不竭源泉——坚持系统观念"],"a":"B","e":""},{"id":"xh-zzq9","n":9,"s":"党的十八大以来，习近平总书记多次赴地方考察调研并发表重要讲话，就各地区发展定位作出重要指示、提出明确要求，为各地因地制宜推进高质量发展指明了方向。下列地区与其发展定位对应正确的是：\n①浙江——两岸融合发展示范区\n②福建——社会主义现代化建设引领区\n③山西——国家资源型经济转型综合配套改革试验区\n④深圳——高质量发展建设共同富裕示范区\n⑤山东——绿色低碳高质量发展先行区","o":["5项","4项","3项","2项"],"a":"D","e":""},{"id":"xh-zzq10","n":10,"s":"习近平总书记指出，扎实推进黄河大保护，确保黄河安澜，是治国理政的大事。党的十八大以来，从三江之源到黄河入海口，习近平总书记多次到黄河流域各省区考察，溯历史、问生态、察防洪、访民生。下列讲话对应的地点，说法正确的是：","o":["宁夏——要加强黄河保护，坚决杜绝污染黄河行为，让母亲河永远健康","西藏——必须担负起保护三江源、保护’中华水塔’的重大责任","青海——推动黄河流域从过度干预、过度利用向自然修复、休养生息转变","上海——要把保护黄河口湿地作为一项崇高事业"],"a":"A","e":""},{"id":"xh-zzq11","n":11,"s":"2026年10月22日，纪念中国工农红军长征胜利90周年大会隆重举行。习近平总书记指出，正是在党的正确路线指引下，红军作战指挥实行了一系列符合实际、机动灵活的战略战术，从而成功突破敌人层层封锁，不断走向新生、走向胜利。历史雄辩地证明，马克思主义基本原理只有同中国具体实际紧密结合，才能解决中国的问题，才能展现出强大生命力。这段材料最能体现的哲学道理是：","o":["物质决定意识，客观必须符合主观，做到一切从实际出发","量变是质变的必要准备，要重视量的积累","矛盾的普遍性决定特殊性，要坚持普遍性与特殊性相结合","正确的认识对实践发展具有积极的推动作用"],"a":"D","e":""},{"id":"xh-zzq12","n":12,"s":"习近平总书记指出，保障和改善民生要抓住人民最关心最直接最现实的利益问题，既尽力而为，又量力而行，一件事情接着一件事情办，一年接着一年干。这一要求体现的哲学道理是：\n①发挥主观能动性与尊重客观规律是辩证统一的\n②量变是质变的必要准备，量变比质变更重要\n③办事情要善于抓住重点，集中力量解决主要矛盾\n④人民群众是社会历史的主体，是社会变革的决定力量","o":["①③④","①④","②③","②④"],"a":"A","e":""},{"id":"xh-zzq13","n":13,"s":"就了伟大长征精神。精神所在，就是力量所在。伟大长征精神充分彰显了忠诚的力量、真理的力量、正义的力量、团结的力量，它作为中国共产党人精神谱系的重要组成部分，跨越时空、历久弥新，永远是激励我们战胜困难、勇往直前的宝贵财富和强大动力。这体现的哲学道理是：\n①实践是认识的基础，是认识的来源\n②社会意识具有相对独立性，先进的社会意识对社会发展起促进作用\n③认识具有直接现实性，正确的认识对实践具有巨大的指导效果\n④事物的发展是内因和外因共同作用的结果，二者相辅相成","o":["③④","①③","②④","①②"],"a":"D","e":""},{"id":"xh-zzq14","n":14,"s":"2026年8月，习近平总书记作出重要指示强调，树立和践行正确政绩观是一项长期任务，必须久久为功，不断巩固拓展学习教育成果，持续推动各级党组织和广大党员、干部立党为公、为民造福、科学决策、真抓实干，努力创造经得起实践、人民、历史检验的实绩。上述指示蕴含的哲学道理是：\n①量变是质变的必要准备，干事创业要重视量的积累\n②人民群众是历史的主体，要坚持以人民为中心的价值立场\n③实践是检验认识真理性的唯一标准，政绩要经受实践的检验\n④发挥主观能动性是尊重客观规律的前提，要做到科学决策真抓实干","o":["①②③","①③","②③④","②④"],"a":"A","e":""},{"id":"xh-zzq15","n":15,"s":"为推动人工智能更好赋能新型工业化，国家提出要以”基础大模型+行业专用模型”双轮驱动，在高端装备、新能源、生物医药等重点领域率先突破，同时要求各地因地制宜制定差异化落地方案，避免”一刀切”式推进。这一政策设计最体现的哲学原理是：","o":["矛盾普遍性与特殊性相互联结，要坚持共性与个性相统一","要善于抓住主要矛盾，集中力量解决重点领域的关键问题","具体问题具体分析是正确解决矛盾的关键","生产关系决定生产力，要加快形成新型生产关系"],"a":"A","e":""},{"id":"xh-zzq16","n":16,"s":"2026年4月，全国服务业大会在京召开。习近平总书记就服务业发展作出重要指示。下列相关说法，正确的是：","o":["我国服务业规模稳步扩大，质效持续提升，在支撑产业升级、满足民生需要、带动就业扩容等方面发挥了重要作用，服务贸易规模稳居全球第一","要突出需求牵引、改革攻坚、科技赋能、开放合作，深入实施服务业扩能提质行动","要推进生活性服务业向专业化和价值链高端延伸，促进生产性服务业高品质多样化便利化发展","要扩大服务业高水平对外开放，服务业领域外资准入负面清单已实现清零"],"a":"B","e":""},{"id":"xh-zzq17","n":17,"s":"2026年3月，《关于做好第二轮土地承包到期后再延长30年试点工作的意见》发布。下列相关要求，说法正确的是：","o":["牢牢把住提高农民收入这条主线，坚持把依法维护农民权益作为出发点和落脚点","逐步推行市场化改革，农村集体土地可以由本集体经济组织外的成员有偿进行承包","不断完善”三权分置”政策体系，落实集体所有权、稳定土地经营权、放活农户承包权","坚持农民主体地位，充分发挥农民主动性和创造性，鼓励农民集体在法律和政策范围内因地制宜探索延包具体路径和办法"],"a":"D","e":""},{"id":"xh-zzq18","n":18,"s":"2026年7月，习近平总书记对基础教育工作作出重要指示，强调党的十八大以来，党中央把基础教育作为基础性、先导性工作来抓，多措并举推动基础教育实现长足发展，为建设教育强国提供了有力支撑。下列相关说法，正确的是：","o":["要以加强师德师风建设为教育的根本任务，坚持不懈用党的创新理论铸魂育人，培养德智体美劳全面发展的社会主义建设者和接班人","要遵循教育规律，落实健康第一教育理念，促进广大学生身心健康、成长成才","要推动学校、家庭、社会各自发力，不断开创基础教育高质量发展新局面","我国已建成了世界上质量最高的基础教育体系，基础教育总体已经达到世界高收入国家的平均水平"],"a":"B","e":""},{"id":"xh-zzq19","n":19,"s":"实体经济是一国经济的立身之本，是财富创造的根本源泉，是国家强盛的重要支柱。下列相关说法，正确的有几项？\n①坚持把发展经济的着力点放在实体经济上，推动资源要素向实体经济集聚、政策措施向实体经济倾斜、工作力量向实体经济加强\n②制造业是实体经济的基础，要快速扩大制造业规模，坚定不移建设制造强国\n③实施产业基础再造工程和重大技术装备攻关工程，支持专精特新企业发展，推动制造业高端化、智能化、绿色化发展\n④实体经济是金融的根基，金融是实体经济的血脉，要推动金融逐渐脱实向虚","o":["1项","2项","3项","4项"],"a":"B","e":""},{"id":"xh-zzq20","n":20,"s":"2026年9月，第18期《求是》杂志发表习近平总书记重要文章《在加强基础研究座谈会上的讲话》。基础研究是打基础、利长远的事业，既不能急功近利，也不可消极无为。下列说法正确的是：","o":["要逐步提高基础研究经费占比，进一步拓宽筹资渠道，形成企业投入为主体的基础研究多元化投入格局","统筹布局国家新兴产业创新中心、国家产业技术工程化中心、国家技术创新中心、国家制造业创新中心等，优先强化重点产业关键个性技术供给","要加紧建设世界一流科技期刊，鼓励国内外成果在海外期刊和平台首发","要深化科技体制改革，健全符合基础研究特点的差异化评价体系，完善基础研究激励机制"],"a":"D","e":""},{"id":"xh-zzq21","n":21,"s":"2026年6月18日，《关于学习贯彻习近平党建思想的通知》印发。关于习近平党建思想的科学内涵，下列说法正确的有几项？\n①坚持党中央集中统一领导是党的领导的最高原则\n②坚持锤炼坚强党性是党的宗旨立场和价值取向\n③坚持落实管党治党政治责任是全面从严治党需要牢牢牵住的”牛鼻子”\n④坚持推进组织建设常态化长效化是保持党同人民群众血肉联系的有效途径\n⑤坚持用党的创新理论凝心铸魂是党的思想建设的根本任务","o":["2项","3项","4项","5项"],"a":"B","e":""},{"id":"xh-zzq22","n":22,"s":"2026年2月，《中共中央国务院关于锚定农业农村现代化扎实推进乡村全面振兴的意见》发布。下列表述正确的有几项？\n①有序推进农村集体经营性建设用地入市，支持入市土地优先用于发展集体经济和乡村产业，鼓励用于建设商品住房\n②分区分类高质量推进高标准农田建设，完善立项、建设、验收和管护机制\n③加强北方地区防洪排涝体系建设，适度提高工程建设标准\n④强化输血式帮扶，增强内生动力，发挥社会救助兜底保障作用，推动帮扶政策协同集成\n⑤深化涉农高校教育教学改革，以需求为导向加快新农科建设","o":["2项","3项","4项","5项"],"a":"B","e":""},{"id":"xh-zzq23","n":23,"s":"2026年8月15日，《生态环境法典》正式施行。下列相关说法，正确的有几项？\n①这是中国第二部以”法典”命名的法律，也是世界上首部以”生态环境”命名的法典\n②法典中”污染防治”单独成编，为世界环境法典体例之首创\n③法典以”五编体”搭建科学完备的生态环境法治体系，促进生态环境治理系统集成、协同高效\n④法典以”完全法典化”的编纂模式，形成法典统领、单行法配套衔接的分层立法格局，探索出兼具体系性与开放性、稳定性与适应性的编纂新路\n⑤法典以习近平生态文明思想为魂和纲，是习近平生态文明思想和习近平法治思想贯通融合、交相辉映的重要结晶","o":["5项","4项","3项","2项"],"a":"C","e":""},{"id":"xh-zzq24","n":24,"s":"党的十八大以来，我们不断推进金融实践创新、理论创新、制度创新，积累了宝贵经验，逐步走出一条中国特色金融发展之路。下列相关举措，说法正确的是：","o":["坚持把金融服务实体经济作为根本宗旨，坚持把防控风险作为金融工作的永恒主题","我国金融体系的重要特征和优势是民营金融机构占主体，但存在间接融资和债权融资比重偏高、金融服务普惠性不足等问题","我国金融机构门类齐全，关键是要同质发展、优势互补，要各司其职、各展所长","金融具有功能性和盈利性双重属性，功能发挥要服从盈利目标"],"a":"A","e":""},{"id":"xh-zzq25","n":25,"s":"记出席会议并发表重要讲话。讲话指出，改革是卫生与健康事业发展的强大动力。下列相关说法正确的是：","o":["要坚持把推进医疗、医保、医药独立发展和治理作为医药卫生体制改革的主攻方向","要以市场化为导向深化公立医院改革，加强县区、基层医疗机构运行保障","要构建多层次医疗保障体系，优化药品耗材分级采购、医保支付和资金使用政策，实现基金安全运行、医院良性运转、群众负担合理","要健全药品供应保障和使用管理机制，完善国家基本药物制度，强化药品质量安全监管"],"a":"D","e":""},{"id":"xh-zzq26","n":26,"s":"次集体学习。关于未来产业的发展，下列说法错误的是：","o":["要综合考虑国家战略需求、技术成熟程度、要素支撑条件等因素，因地制宜、错位发展","要充分发挥新型举国体制优势，坚持”产业出题、科技答题”","要完善财税等政策，以发展绿色金融为重点促进未来产业发展","要加强基础研究战略性、前瞻性、体系化布局，加快科技成果转化应用"],"a":"C","e":""},{"id":"xh-zzq27","n":27,"s":"2026年10月12日至13日，全国卫生与健康大会在京召开。习近平总书记出席会议并发表重要讲话。下列相关说法，正确的有几项？\n①卫生与健康事业具有全局性、基础性作用，必须坚定实施健康优先发展战略\n②健全疾病防控体系，守牢不发生疫情的底线\n③营造良好生态环境和生产生活环境，鼓励和支持全民健身、健康休闲\n④引导全社会树立正确健康观，进行有效的健康自塑和管理\n⑤及时治疗是最经济最有效的健康策略，要抓细抓好卫生与健康各项基础性、源头性工作","o":["2项","3项","4项","5项"],"a":"B","e":""},{"id":"xh-zzq28","n":28,"s":"2026年7月1日，庆祝中国共产党成立105周年大会在京举行。习近平总书记指出，中国共产党之所以能够在105年奋斗中不断铸就辉煌，历史和人民之所以选择中国共产党，根本在于我们党具有其他政党和政治力量无可比拟的优秀特质。下列相关说法正确的是：\n①矢志追求真理、始终把准前进方向，党把马克思主义作为改造主观世界和客观世界的强大思想武器，注重在社会矛盾运动中揭示和运用真理，善于在理论中检验和发展真理\n②深深植根人民、始终拥有坚实根基，党牢记江山就是人民、人民就是江山\n③勇担历史使命、始终掌握战略主动，党胸怀共产主义远大理想、立志于中华民族千秋伟业\n④注重强健自身、始终充满生机活力，党清醒认识到打铁必须自身硬，善于以时代发展要求审视自己、以强烈忧患意识警醒自己、以社会革命精神完善自己","o":["1项","4项","3项","2项"],"a":"D","e":""},{"id":"xh-zzq29","n":29,"s":"2026年9月1日，习近平总书记在”上海合作组织+“会议上发表讲话指出，中国作为负责任大国，积极倡导平等有序的世界多极化。主权平等、相互尊重是根本原则，均衡有序、遵守法治是必然要求，多边主义、对话协商是关键路径，互利共赢、普惠包容是发展方向。下列说法正确的有几项？\n①要坚持各国无论大小、强弱、贫富，都权利平等、机会平等、规则平等\n②要弘扬社会主义核心价值观，摒弃双重标准、例外主义、干涉霸凌、丛林法则\n③联合国宪章宗旨和原则确立了国际关系基本准则，是战后国际秩序的基石\n④要聚焦发展议题，坚持开放合作，弥合数字和智能鸿沟，让发展成果惠及各国人民\n⑤要坚持对话不对抗、结伴又结盟，推动各国在全球治理中平等参与、普遍受益","o":["5项","4项","3项","2项"],"a":"C","e":""},{"id":"xh-zzq30","n":30,"s":"习近平总书记指出，2026年是”十五五”开局之年，地方各级领导班子将陆续换届，通过学习教育推动各级领导班子和领导干部树立和践行正确政绩观，十分重要，很有必要。下列相关说法正确的是：","o":["要以立党为公、为民造福、科学决策、真抓实干为总要求，以分类推进学查改为抓手","要坚持聚焦主题、简约务实，划分批次、划分阶段，认真落实学习研讨、查摆问题、整改整治、建章立制、开门教育等工作安排","要坚持实事求是、求真务实，为人民出政绩、以实干出政绩","要坚持与中央巡察整改、深入贯彻中央八项规定精神学习教育整改、“十五五”规划编制实施、生态环保督察整改等相结合"],"a":"C","e":""},{"id":"xh-zzq31","n":31,"s":"如期实现建军一百年奋斗目标，加快把人民军队建成世界一流军队，是全面建设社会主义现代化国家的战略要求。下列相关举措，说法正确的有几项？\n①”十五五”时期要如期实现建军一百年奋斗目标、高质量推进国防和军队现代化，必须坚持好、运用好、发展好改革强军这个重要法宝，毫不动摇坚持和加强党对军队绝对领导\n②完成”十五五”时期国防和军队现代化目标任务，归根到底要靠各级政府来领导和推进\n③要加强我军党的领导和党的建设，选准配强高层党委班子，增强基层党组织自主抓建能力\n④要完善促进人才发展的制度和条件，体系推进联合作战指挥、新型作战力量、高层次科技创新、高水平战略管理”四类人才”培养，实现人的能力素质同强军实践协调发展\n⑤要传承和弘扬我党我军优良传统，推进新时代强军文化建设，加强先进典型培养和激励","o":["2项","3项","4项","5项"],"a":"B","e":""},{"id":"xh-zzq32","n":32,"s":"2026年10月9日，《中共中央国务院关于发展新质生产力的意见》发布。《意见》指出，要推动科技创新和产业创新深度融合。下列相关说法正确的是：","o":["深化产业内、产品内专业分工，促进跨行业跨区域融合，避免”内卷式”竞争","以产业链为主导、以政府为主体建立跨区域产业协作机制，支持东部地区带动中西部和东北地区因地制宜发展新兴产业","实施”西数东算”、智能制造、工业互联网创新发展等工程，建设全国一体化算力网、国家区块链网络","规范统一、分业施策布局国家人工智能行业应用中试基地和高价值应用场景"],"a":"A","e":""},{"id":"xh-zzq33","n":33,"s":"2026年4月28日，中共中央政治局就提高防灾减灾救灾能力进行第二十五次集体学习。下列相关表述，正确的有几项？\n①降低灾害风险，减轻灾害损失，重在事中管控，要坚持源头管控，将安全韧性要求贯穿国土空间规划及各类建设规划之中\n②基层是抵御自然灾害的第一线，抓基层、强基础的工作始终不能放松\n③要坚决纠正重发展轻安全、重救灾轻预防等倾向\n④要树牢底线思维、极限思维，不断提升大灾巨灾应对处置能力\n⑤各地区各有关部门要守土尽责，坚持统分结合、防救衔接、上下联动","o":["5项","4项","3项","2项"],"a":"B","e":""},{"id":"xh-zzq34","n":34,"s":"2026年10月9日，《中共中央国务院关于发展新质生产力的意见》发布。《意见》指出，要大力推进科技创新。下列相关说法正确的是：","o":["坚持基础研究从目标导向转变为自由探索，支持自由探索类基础研究开拓创新","统筹国家战略科技力量建设，以经济发展需求为导向，优化国家科研机构、高水平研究型大学、科技领军企业定位","探索建立科技项目全过程评价机制，立项时一体部署研发和转化任务，验收时考核应用实绩，解决技术开发与成果转化脱节问题","引导高等学校、科研院所按照先付费使用后方式把科技成果许可给中小微企业使用"],"a":"C","e":""},{"id":"xh-zzq35","n":35,"s":"2026年10月9日，《中共中央国务院关于发展新质生产力的意见》发布。《意见》指出，发展新质生产力是推动高质量发展的内在要求和重要着力点。下列相关说法正确的是：","o":["要坚持创新主导、改革为要、因地制宜、先破后立","要加快发展新质生产力以适应新型生产关系","发展新质生产力以制度创新为引领，以全要素生产率大幅提升为核心标志","要推动技术革命性突破、生产要素创新性配置、产业深度转型升级，推动劳动者、劳动资料、劳动对象优化组合和更新跃升"],"a":"D","e":""},{"id":"xh-zzq36","n":36,"s":"2026年9月20日，《关于分类推进高校改革的意见》印发。《意见》指出，要激发分类发展动能。下列相关举措，说法正确的是：\n①围绕国家战略需求协同育人，以统筹规划为先导、以科学评价为动力、以分类改革为牵引\n②打造服务国家重大战略支撑力量，发挥好”双一流”建设对研究型大学改革的牵引作用\n③建强服务区域经济社会发展基础力量，实施优质特色应用型本科院校和学科专业建设工程，优化实施高水平高等职业学校和专业建设计划\n④科学构建高校分类发展体系，区分综合性、特色化基本方向，确立高校分类框架","o":["①②③","①②④","①③④","②③④"],"a":"D","e":""},{"id":"xh-zzq37","n":37,"s":"2026年1月，习近平总书记在省部级主要领导干部学习贯彻党的二十届四中全会精神专题研讨班开班仪式上发表重要讲话强调，要全面深刻准确领会和把握党的二十届四中全会的战略部署。下列相关说法正确的是：","o":["各地区各行业要找准定位，坚持智能化、绿色化、融合化方向，充分发挥比较优势，形成上下游产业相互衔接、各展其长、同向发力的生动局面","发展新质生产力是建设现代化产业体系的必然要求，不能一哄而上、跟风冒进，更不能停滞不前，要逐步替代传统产业","要以做强国际循环提升扩大高水平对外开放的自主性，以拓展国内大循环增强国内改革发展的活力，努力实现内外联通、互促共进","促进社会发展，发展经济是重点，要把发展经济和改善民生有机统一起来"],"a":"A","e":""},{"id":"xh-zzq38","n":38,"s":"2026年8月17日，习近平总书记在纪念江泽民同志诞辰100周年大会上发表重要讲话指出，我们要学习江泽民同志与时俱进的创新精神。江泽民同志提出党的全部理论和工作要体现时代性、把握规律性、富于创造性，集中全党智慧创立”三个代表”重要思想。下列关于江泽民同志的主要理论贡献，说法正确的是：\n①创造性回答了”什么是社会主义、怎样建设社会主义”的问题\n②强调我们党始终代表中国先进生产力的发展要求、代表中国先进文化的前进方向、代表中国最广大人民的根本利益\n③确定社会主义初级阶段的基本路线，提出”三步走”发展战略\n④确立社会主义市场经济体制的改革目标和基本框架，确立公有制为主体、多种所有制经济共同发展的基本经济制度和按劳分配为主体、多种分配方式并存的分配制度","o":["①③","①④","②③","②④"],"a":"D","e":""},{"id":"xh-zzq39","n":39,"s":"习近平总书记指出，新时代新征程，各级党委和政府要坚持以人民为中心，加强对民政工作的领导，加强普惠性、基础性、兜底性民生建设，解决好人民最关心最直接最现实的利益问题，不断推动民政事业高质量发展。下列相关举措，说法正确的有几项？\n①加快建立长期护理保险制度，起步阶段保障重度失能人员\n②以满足群众就近就便看病就医需求为出发点，以实施医疗卫生强基工程为支撑，加快建设分级诊疗体系\n③深化住房公积金制度改革，扩大使用范围，支持灵活就业人员参加住房公积金制度\n④全面推进常住地提供基本公共服务，逐步消除基本公共服务与户籍挂钩因素，促进未落户常住人口与户籍人口同等享有基本公共服务","o":["4项","3项","2项","1项"],"a":"A","e":""},{"id":"xh-zzq40","n":40,"s":"2026年9月，习近平总书记同美国总统特朗普在白宫举行会谈。下列相关说法，正确的是：","o":["中美两国要朝着合作为主、竞争有度、分歧可控、和平可期的方向努力，走出一条两个大国的正确相处之道","合作是双行道，中美经贸关系的稳定既需要压缩合作清单，也需要拉长问题清单","要秉持平等、尊重、互惠的精神，坚持零和博弈导向，推动中美经贸关系持续稳定向好发展","双方同意构建”基于尊重、公平、对等的中美全面战略协作伙伴关系”"],"a":"A","e":""},{"id":"xh-zzq41","n":41,"s":"2026年11月，第21期《求是》杂志发表习近平重要文章《关于的说明》。关于《决定》稿的起草过程，着重把握了以下哪几点？\n①全面贯彻新时代党建思想。新时代党建思想是党和人民实践经验和集体智慧的结晶\n②服务使命任务，服从服务于党和国家事业发展，历来是党的建设的重要原则\n③坚持严的基调，持之以恒推进全面从严治党必须一以贯之、一严到底\n④突出结果导向，持之以恒推进全面从严治党必须在巩固已有成果基础上不断研究新情况、解决新问题\n⑤强化系统观念，必须把党的各项建设作为一个有机整体来谋划和推进","o":["①②③④⑤","①②③⑤","①②③④","①③④⑤"],"a":"B","e":""},{"id":"xh-zzq42","n":42,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。下列关于全面从严治党，说法正确的是：","o":["在各个历史时期都高度重视管党治党，勇于坚持真理、修正错误，在依靠自身力量和人民支持解决自身问题中不断强大，成为党和人民事业的坚强领导核心","中国共产党在革命、建设、改革中先后把党的建设作为伟大梦想、新的伟大梦想","中国共产党先后找到”自我革命”和”让人民来监督政府”两个跳出治乱兴衰历史周期率的答案，这是中国共产党的独特创造","新时代以来，中国共产党把全面从严治党纳入”四个全面”总体布局"],"a":"A","e":""},{"id":"xh-zzq43","n":43,"s":"2026年10月26日，二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。下列相关说法正确的是：\n①增强党性是全面从严治党的基础性任务\n②”三重一大”制度是党的根本组织原则和领导制度，贯彻执行”三重一大”制度是全面从严治党的内在要求\n③全面从严治党关键在从严治吏\n④党的各级组织是全面从严治党的主体\n⑤一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本方针","o":["①②③","①④⑤","③④⑤","②③⑤"],"a":"C","e":""},{"id":"xh-zzq44","n":44,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议指出，要严格执行领导班子决策议事规则。下列相关说法，正确的有几项？\n①坚持集体领导和个人分工负责相结合，坚持科学决策、民主决策、依法决策，凡属重大问题必须按照集体领导、民主集中、个别酝酿、会议决定的原则，由集体讨论作出决定\n②完善党委（党组）议事规则和决策程序，加强重大决策的调查研究、科学论证、风险评估，重要议题出现较大意见分歧时可以先行作出决策，以保障工作执行效率\n③加强重大决策合规合法性审查，健全重大决策、重要人事任免、重大项目安排、大额资金使用事项监督机制\n④健全领导干部重大决策终身负责制\n⑤健全领导班子权力运行制约机制，执行”一把手”首要表态制","o":["2项","3项","4项","5项"],"a":"B","e":""},{"id":"xh-zzq45","n":45,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议强调，全面从严治党关键在从严治吏。下列相关说法，正确的是：","o":["坚持正确用人导向，坚持德才兼备、以才为先，坚持五湖四海、任人唯贤，坚持事业为上、公道正派","严格执行干部选拔任用原则和程序，坚持首长选人、公正用人、以事择人，发挥党组织领导和把关作用","坚持个体强整体优、功能服从结构，选优配强各级领导班子特别是”一把手”","加强对领导班子和领导干部的分析研判，推进领导干部能上能下常态化，加大调整不胜任现职干部力度"],"a":"D","e":""},{"id":"xh-zzq46","n":46,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。《决定》指出，要建设上下贯通、执行有力的严密组织体系。下列相关说法，正确的是：","o":["推动基层党组织走好第一方阵，发挥表率作用，建设成为讲政治、守纪律、负责任、有效率的模范机关","坚持地方党委在本地区发挥总揽全局、协调各方的领导作用，履行把方向、管大局、作决策、保落实职责","坚持把能力标准放在首位，严格程序、严格把关、严肃纪律，提高发展党员质量","完善属地管理和垂直管理的党建工作体系，推动条块分割、各负其责、紧密衔接"],"a":"B","e":""},{"id":"xh-zzq47","n":47,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。《决定》指出，建设上下贯通、执行有力的严密组织体系，要统筹推进各领域基层党组织建设。下列相关说法，正确的有几项？\n①强化大抓基层鲜明导向，坚持补短板、填空白和提质量、强功能并举，把基层党组织建设成为有效实现党的领导的坚强战斗堡垒\n②探索社区党组织领导下的居委会、村委会、物业服务企业协调运行新模式\n③深化党建引领基层治理和基层政权建设，坚持和发展新时代”义乌发展经验”，健全党组织领导的自治、法治、德治相结合的城乡基层治理体系\n④推动资源服务管理下沉、政策向基层倾斜，改善基层工作条件","o":["1项","2项","3项","4项"],"a":"B","e":""},{"id":"xh-zzq48","n":48,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。《决定》指出，驰而不息正风肃纪，要强化从严执纪。下列相关说法，正确的是：\n①严格执行党的组织纪律，带动政治纪律、廉洁纪律、群众纪律、工作纪律、生活纪律全面从严\n②坚持法严于纪、法在纪前，执纪执法贯通、有效衔接司法\n③坚持抓早抓小、防微杜渐，对苗头性、倾向性问题及时提醒纠正\n④把严的要求贯穿党规制定、党纪教育、执纪监督全过程","o":["①②","②④","①③","③④"],"a":"D","e":""},{"id":"xh-zzq49","n":49,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。党的十八大以来，领导创造性提出”依规治党”，并作出一系列重要论断。下列说法正确的是：\n①把制度建设贯穿党的各方面建设之中，注重用制度管权管事管人\n②完善的党内法规体系是中国特色社会主义法治体系的重要内容\n③完善党内法规制度体系，重点是做好顶层设计、查漏补缺、提质增效文章\n④要增强制度执行力，法规制度的生命力在于完善\n⑤把权力关进制度笼子，既要完善制度规定，把笼子织密织牢，防止”纸笼禁虎”；又要提高制度执行力，增强刚性约束，防止”牛栏关猫”","o":["①②③","①③④","①③⑤","②③⑤"],"a":"A","e":""},{"id":"xh-zzq50","n":50,"s":"2026年10月26日至29日，党的二十届五中全会召开，会议强调，持之以恒推进全面从严治党，是全党的共同政治责任，必须扭住管党治党责任制”牛鼻子”。下列说法不正确的是：","o":["压紧压实党委（党组）主体责任、政府监督责任、纪委书记第一责任人责任、领导班子其他成员”一岗双责”和党员、干部具体责任","各级党委（党组）要主动抓、用心管，扣紧责任链条，层层传导压力","县级以上党委（党组）至少每年听取一次领导班子成员履行管党治党责任情况汇报，加强督促指导","领导干部特别是高级干部要严于律己、严负其责、严管所辖，在履行管党治党责任上作示范"],"a":"A","e":""}]}]);})(window.XCTK_DATA);
